    public static string GetLogPath()
    {
        EnsureLogPath();
        return _logPath ?? LogFileName;
    }

    public static void WriteLog(string message)
    {
        try
        {
            EnsureLogPath();
            var line = DateTime.Now.ToString("HH:mm:ss.fff")
                       + " [pid=" + Process.GetCurrentProcess().Id + "] "
                       + (message ?? "")
                       + Environment.NewLine;
            lock (LogLock)
            {
                // 多开共享日志：允许读写共享，避免第二个客户端 Append 失败/卡死
                using (var fs = new FileStream(
                           _logPath,
                           FileMode.OpenOrCreate,
                           FileAccess.Write,
                           FileShare.ReadWrite))
                {
                    var rotated = false;
                    if (fs.Length > MaxLogBytes)
                    {
                        fs.SetLength(0);
                        rotated = true;
                    }

                    fs.Seek(0, SeekOrigin.End);
                    using (var sw = new StreamWriter(fs, Encoding.UTF8))
                    {
                        if (rotated)
                        {
                            sw.Write(DateTime.Now.ToString("HH:mm:ss.fff")
                                     + " [pid=" + Process.GetCurrentProcess().Id + "] "
                                     + "log rotated, previous file exceeded 16MB"
                                     + Environment.NewLine);
                        }

                        sw.Write(line);
                    }
                }
            }
        }
        catch
        {
            // ignore
        }
    }

    public static bool OnWikiClick()
    {
        EnsureLogBoot("OnWikiClick");
        _wikiCalls++;
        var now = NowMs();
        WriteLog("OnWikiClick #" + _wikiCalls + " visibleBefore=" + _visible);

        try
        {
            // 最小化时再点百科：展开，不要当成关闭（不受开关防抖影响）
            if (_visible && _minimized)
            {
                _lastToggleMs = now;
                EnsureHost();
                EnsurePanel();
                SetMinimized(false);
                WriteLog("wiki restore from minimized");
                return true;
            }

            if (_lastToggleMs > 0 && now - _lastToggleMs < DebounceMs)
            {
                WriteLog("DEBOUNCE keep visible=" + _visible);
                return _visible;
            }

            EnsureHost();
            _visible = !_visible;
            _lastToggleMs = now;

            if (_visible)
            {
                EnsurePanel();
                // 同步战斗模式（关掉默认九动等），保证面板选项与 DLL 开关一致
                ApplyBattleMode(_battleMode);
                SetPanelActive(true);
                SetMinimized(false);
                ShowTab(_tab);
                RefreshOverview(true);
            }
            else
            {
                _minimized = false;
                _pendingAutoMinimizeMs = 0;
                SetPanelActive(false);
            }

            WriteLog("toggle -> visible=" + _visible + " tab=" + _tab + " mode=" + _battleMode);
            return _visible;
        }
        catch (Exception ex)
        {
            WriteLog("OnWikiClick EX: " + RootMessage(ex));
            Tip("面板异常: " + RootMessage(ex));
            return false;
        }
    }

    /// <summary>
    /// 多开器：打开助手并约 3 秒后缩到右上角。已手动打开（含最小化）则忽略。
    /// </summary>
    public static string OpenAndMinimizeFromLauncher()
    {
        try
        {
            if (_visible)
            {
                WriteLog("OpenAndMinimizeFromLauncher skip already visible minimized=" + _minimized);
                return "already open";
            }

            EnsureHost();
            EnsurePanel();
            _visible = true;
            _lastToggleMs = NowMs();
            ApplyBattleMode(_battleMode);
            SetPanelActive(true);
            SetMinimized(false);
            ShowTab(_tab);
            RefreshOverview(true);
            _pendingAutoMinimizeMs = NowMs() + 3000;
            WriteLog("OpenAndMinimizeFromLauncher scheduled minimize");
            return "opening";
        }
        catch (Exception ex)
        {
            WriteLog("OpenAndMinimizeFromLauncher EX: " + RootMessage(ex));
            return "error: " + RootMessage(ex);
        }
    }

    private static string _ctrlMsg = "";
    private static bool _ctrlOk;
    private static long _ctrlUnix;

    private static void SetControlResult(bool ok, string msg)
    {
        _ctrlOk = ok;
        _ctrlMsg = msg ?? "";
        _ctrlUnix = (long)(DateTime.UtcNow - new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc)).TotalSeconds;
    }

    private static void MergeDailyControlResult(Dictionary<string, object> d)
    {
        try
        {
            var t = FindLoadedType("SeqChapterDailyClaim");
            if (t == null)
            {
                return;
            }

            var text = Convert.ToString(t.GetField("ControlResultText", BindingFlags.Public | BindingFlags.Static)?.GetValue(null) ?? "") ?? "";
            if (string.IsNullOrEmpty(text))
            {
                return;
            }

            var unix = Convert.ToInt64(t.GetField("ControlResultUnix", BindingFlags.Public | BindingFlags.Static)?.GetValue(null) ?? 0);
            if (unix < _ctrlUnix)
            {
                return;
            }

            var ok = Convert.ToBoolean(t.GetField("ControlResultOk", BindingFlags.Public | BindingFlags.Static)?.GetValue(null) ?? false);
            d["ctrl_ok"] = ok;
            d["ctrl_msg"] = text;
            d["ctrl_unix"] = unix;
        }
        catch
        {
            // ignore
        }
    }

    /// <summary>
    /// 给精简桥接 / 序章中控读的监视快照。助手未打开也可调用。
    /// 不写日志。
    /// </summary>
    public static Dictionary<string, object> GetMonitorSnapshot()
    {
        var d = new Dictionary<string, object>();
        d["helper_open"] = _visible;
        d["helper_minimized"] = _minimized;
        d["battle_mode"] = _battleMode ?? "";
        d["battle_mode_label"] = ModeLabel(_battleMode);
        d["escort_battle"] = _battleMode == ModeEscortBattle;
        d["escort_busy"] = _escortBattleBusy;
        d["escort_note"] = _escortBattleNote ?? "";
        d["escort_last_end_unix"] = _escortBattleLastEndUnix;
        d["escort_stop"] = _escortBattleStopReason ?? "";
        try
        {
            d["script_run"] = FormatActiveScriptRunStatus() ?? "";
        }
        catch
        {
            d["script_run"] = "";
        }

        try
        {
            d["overview"] = BuildOverviewText() ?? "";
        }
        catch
        {
            d["overview"] = "";
        }

        try
        {
            int floor;
            string floorName;
            int mapResId;
            TryGetCurrentMapInfo(out floor, out floorName, out mapResId);
            var loc = GetStaticMember("PlayerDataHolder", "location");
            var x = Convert.ToInt32(GetMember(loc, "x") ?? GetMember(loc, "X") ?? 0);
            var y = Convert.ToInt32(GetMember(loc, "y") ?? GetMember(loc, "Y") ?? 0);
            var captainUid = GetCaptainUid() ?? "";
            var mainUid = GetMainPlayerUidSafe();
            if (string.IsNullOrEmpty(mainUid))
            {
                mainUid = captainUid;
            }

            var player = GetPlayer(mainUid);
            var name = Convert.ToString(GetMember(player, "Name") ?? GetMember(player, "name") ?? "") ?? "";
            d["floor"] = floor;
            d["floor_name"] = floorName ?? "";
            d["map_res_id"] = mapResId;
            d["x"] = x;
            d["y"] = y;
            d["captain_uid"] = captainUid;
            d["main_uid"] = mainUid ?? "";
            d["name"] = name;
            d["phone"] = LoginPhoneDigits();
            d["in_battle"] = IsInBattleNow();
            // 空格必须数本窗口角色，勿用队伍队长
            d["bag_empty"] = CountBagEmptySlots(mainUid);
        }
        catch
        {
            d["floor"] = 0;
            d["floor_name"] = "";
            d["map_res_id"] = 0;
            d["x"] = 0;
            d["y"] = 0;
            d["captain_uid"] = "";
            d["main_uid"] = "";
            d["name"] = "";
            d["phone"] = "";
            d["in_battle"] = false;
            d["bag_empty"] = 0;
        }

        d["ctrl_ok"] = _ctrlOk;
        d["ctrl_msg"] = _ctrlMsg ?? "";
        d["ctrl_unix"] = _ctrlUnix;
        MergeDailyControlResult(d);
        return d;
    }

    public static void Tick()
    {
        _updateCalls++;

        if (_pendingAutoMinimizeMs > 0 && NowMs() >= _pendingAutoMinimizeMs)
        {
            _pendingAutoMinimizeMs = 0;
            if (_visible && !_minimized)
            {
                SetMinimized(true);
            }
        }

        // 窗口标题统一协调：各功能后缀（计数挂机/自动提取等）合并刷新。
        // 放 _visible 判断之前：面板隐藏时挂机也保持标题提示。
        if (NowMs() - _lastTitleRefreshMs >= TitleRefreshIntervalMs)
        {
            _lastTitleRefreshMs = NowMs();
            try
            {
                RefreshTitleFromFeature();
            }
            catch
            {
                // ignore
            }
        }

        // 护航/刷灵堂/超级AI在关面板时也要跑；自动暂停铃声同理
        try
        {
            TickEscortBattle();
            TickEscort();
            TickEscortAlertRing();
            TickLingTang();
            TickSkCNav();
            TickSuperAi();
            TickSuperAiPrep();
            TickSuperAiPotionBankPull();
            TickPetNamer();
            TickJunkDrop();
            TickOpenBook();
            TickScriptWingTest();
            TickFloraHeal();
            TickCrystalChallenge();
            TickFullAutoScript();
            TickWarpWait();
            TickBanshanTest();
            TryLoadDojoLayerForLoginPhone();
            TickDojoRun();
            TickDojoHell();
            TickBrawlSign();
            TickMoneyFarm();
            TickSaveGold();
            TickEnchantStoneSort();
            TickPlayerTrade();
            TickTradeGotoSpot();
            TickTradeBankTake();
            TickTradeSecurityVerify();
            TickStopEncounter();
            TickDojoRoster();
            TickZhongyuanAll();
            TickZhongyuanCatch();
            TickZhongyuanTransfer();
            TickZhongyuanBattleExitSealCheck();
            TickSniffAccountBank();
            // 大乱斗脚本 / PVP：强制关跳过动画与单体变群体
            TickForceOffSkipAnimAndAoeForPvpOrBrawl();
            // 跳过动画：只清表现队列；选指令交给官方 AutoFight，禁止回合间隙乱踢 DoAutoFight。
            TickSkipBattleAnim();
            // 跳过动画开着时仍跑无法行动兜底（石化/死亡漏 N）；与清队列不冲突。
            TickBattleUnableActFix();
            TickBattleRoundTimeoutLog();
            TickBattleAssist();
            TickPvpAutoHold();
        }
        catch (Exception ex)
        {
            WriteLog("TickEscort/LingTang/SuperAi/WingTest/SkipAnim/UnableAct EX: " + RootMessage(ex));
        }

        if (!_visible)
        {
            return;
        }

        if (_canvasGo == null || IsUnityNull(_canvasGo))
        {
            try
            {
                EnsurePanel();
                SetPanelActive(true);
                ShowTab(_tab);
            }
            catch (Exception ex)
            {
                WriteLog("Tick rebuild EX: " + RootMessage(ex));
            }

            return;
        }

        if (_tab == TabOverview && NowMs() - _lastOverviewRefreshMs >= OverviewRefreshMs)
        {
            RefreshOverview(false);
        }

        if (_tab == TabNav && NowMs() - _lastOverviewRefreshMs >= OverviewRefreshMs)
        {
            RefreshNavPos(false);
        }

        if (_tab == TabEscort && _escortStatusText != null && !IsUnityNull(_escortStatusText))
        {
            SetText(_escortStatusText, FormatEscortStatus(), 13);
        }

        if (_tab == TabScript)
        {
            RefreshScriptRunStatus();
        }

        if (_tab == TabSuperAi && _superAiActive)
        {
            RefreshSuperAiBattlefieldUi(false);
        }
        else if (_tab == TabSuperAi && _superAiStatusText != null && !IsUnityNull(_superAiStatusText))
        {
            SetText(_superAiStatusText, FormatSuperAiStatus(), 11);
        }

        if (_tab == TabBattle && _escortBattleStatusText != null && !IsUnityNull(_escortBattleStatusText))
        {
            SetText(_escortBattleStatusText, _escortBattleNote ?? "", 12);
        }
    }

