    private static void StartJunkDrop()
    {
        try
        {
            var uids = CollectTeamOrMultiUids();
            if (uids.Count == 0)
            {
                var cap = GetCaptainUid();
                if (!string.IsNullOrEmpty(cap))
                {
                    uids.Add(cap);
                }
            }

            if (uids.Count > JunkDropMaxUids)
            {
                uids = uids.GetRange(0, JunkDropMaxUids);
            }

            if (uids.Count == 0)
            {
                _junkDropNote = "未找到角色";
                Tip("一键丢弃：未找到角色");
                return;
            }

            _junkDropActive = true;
            _junkDropUids = uids;
            _junkDropUidIdx = 0;
            _junkDropDropped = 0;
            _junkDropFailStreak = 0;
            _junkDropPending = false;
            _junkDropPendUid = "";
            _junkDropPendIndex = -1;
            _junkDropPendId = 0;
            _junkDropPendName = "";
            _junkDropPendPile = 0;
            _junkDropNote = "准备中…";
            _junkDropNextAtMs = NowMs();
            Tip("一键丢弃：开始 " + uids.Count + " 个角色");
            WriteLog("JunkDrop start uids=" + string.Join(",", uids.ToArray()));
            RefreshScriptTabIfVisible();
        }
        catch (Exception ex)
        {
            _junkDropNote = "失败: " + RootMessage(ex);
            WriteLog("StartJunkDrop EX: " + RootMessage(ex));
            Tip("一键丢弃失败: " + RootMessage(ex));
        }
    }

    /// <summary>中控「一键丢弃道具」。与脚本页「一键丢弃」同一条流水线。成功返回「已启动」。</summary>
    public static string TryStartJunkDropFromControl()
    {
        if (_junkDropActive)
        {
            SetControlResult(false, "一键丢弃已在运行");
            return "一键丢弃已在运行";
        }

        _junkDropFromControl = false;
        _junkDropNote = "";
        StartJunkDrop();
        if (!_junkDropActive)
        {
            var note = string.IsNullOrEmpty(_junkDropNote) ? "未启动" : _junkDropNote;
            SetControlResult(false, "一键丢弃 " + note);
            return note;
        }

        _junkDropFromControl = true;
        SetControlResult(false, "进行中 一键丢弃");
        return "已启动";
    }

    private static void StopJunkDrop(string reason)
    {
        var fromControl = _junkDropFromControl;
        _junkDropFromControl = false;
        _junkDropActive = false;
        _junkDropPending = false;
        _junkDropUids = null;
        _junkDropNote = reason ?? "";
        Tip("一键丢弃：" + reason);
        WriteLog("JunkDrop stop: " + reason + " dropped=" + _junkDropDropped);
        if (fromControl)
        {
            var note = reason ?? "";
            var ok = note.StartsWith("完成", StringComparison.Ordinal);
            SetControlResult(ok, "一键丢弃 " + note);
        }
    }

    private static string FormatJunkDropStatus()
    {
        if (!_junkDropActive)
        {
            return "一键丢弃: 未启动\n关键字(引魔香/绿红头盔/封印卡/铜钥匙/梦幻头巾/红蓝凤凰羽毛/试炼洞穴/乐谱) + 名含卡片/图鉴卡 + 未鉴定≤4级宝石/装备；5角色；间隔0.5s；同格失败3次停";
