        }

        var main = Convert.ToString(GetStaticMember("PlayerDataHolder", "MainPlayerUid") ?? "") ?? "";
        if (string.IsNullOrEmpty(main) || !string.Equals(main, cap, StringComparison.Ordinal))
        {
            StopOpenBook("请在队长窗口运行开书");
            return "";
        }

        return cap;
    }

    /// <summary>道具栏是否已无空位。</summary>
    private static bool IsOpenBookBagFull(string uid)
    {
        return CountBagEmptySlots(uid) <= 0;
    }

    /// <summary>读 PlayerData.itemGridNum（背包终点，不含该下标）；失败回退 68。</summary>
    private static int TryReadItemGridNum(string uid)
    {
        try
        {
            var player = GetPlayer(uid);
            if (player != null)
            {
                var n = Convert.ToInt32(
                    GetMember(player, "itemGridNum")
                    ?? GetProp(player, "itemGridNum")
                    ?? GetMember(player, "ItemGridNum")
                    ?? 0);
                if (n > FloraHealBagStart)
                {
                    return n;
                }
            }
        }
        catch
        {
            // ignore
        }

        return FloraHealBagEnd;
    }

    /// <summary>背包空格数：扫 [8 .. itemGridNum)，useFlag!=1 / null 视为空。
    /// 勿用队伍队长 uid；列表短于 gridNum 时，缺省下标也算空格。</summary>
    private static int CountBagEmptySlots(string uid)
    {
        try
        {
            if (string.IsNullOrEmpty(uid))
            {
                return 0;
            }

            var items = GetItemDatasFromUid(uid);
            if (items == null)
            {
                return 0;
            }

            var gridNum = TryReadItemGridNum(uid);
            if (gridNum <= FloraHealBagStart)
            {
                gridNum = FloraHealBagEnd;
            }

            var empty = 0;
            for (var i = FloraHealBagStart; i < gridNum; i++)
            {
                if (i >= items.Count)
                {
                    empty++;
                    continue;
                }

                var item = items[i];
                if (item == null || Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
                {
                    empty++;
                }
            }

            return empty;
        }
        catch (Exception ex)
        {
            WriteLog("CountBagEmptySlots EX: " + RootMessage(ex));
            return 0;
        }
    }

    private static string OpenBookPhaseName(int phase)
    {
        switch (phase)
        {
            case OpenBookPhaseUse: return "使用抉择宝箱";
            case OpenBookPhaseWaitUse: return "等确定弹框";
            case OpenBookPhaseDrop: return "丢技能书";
            case OpenBookPhaseWaitDrop: return "确认丢弃";
            case OpenBookPhaseMove: return "右上移2格";
            default: return "就绪";
        }
    }

    private static void TickOpenBook()
    {
        if (!_openBookActive)
        {
            return;
        }

        try
        {
            var now = NowMs();
            if (_openBookDelayUntilMs > 0 && now < _openBookDelayUntilMs)
            {
                return;
            }

            _openBookDelayUntilMs = 0;
            if (IsInBattleNow())
            {
                _openBookNote = "战斗中，等待…";
                return;
            }

            var uid = GetOpenBookCaptainUidOrStop();
            if (string.IsNullOrEmpty(uid))
            {
                return;
            }

            switch (_openBookPhase)
            {
                case OpenBookPhaseUse:
                    TickOpenBookUse(uid, now);
                    break;
                case OpenBookPhaseWaitUse:
                    TickOpenBookWaitUse(uid, now);
                    break;
                case OpenBookPhaseDrop:
                    TickOpenBookDrop(uid, now);
                    break;
                case OpenBookPhaseWaitDrop:
                    TickOpenBookWaitDrop(uid, now);
                    break;
                case OpenBookPhaseMove:
                    TickOpenBookMove(uid, now);
                    break;
                default:
                    StopOpenBook("未知阶段");
                    break;
            }
        }
        catch (Exception ex)
        {
            WriteLog("TickOpenBook EX: " + RootMessage(ex));
            StopOpenBook("异常: " + RootMessage(ex));
        }
    }

    private static void TickOpenBookUse(string uid, long now)
    {
        if (IsOpenBookBagFull(uid))
        {
            StopOpenBook("队长背包已满，停止");
            return;
        }

        if (CountBagItemByKeyword(uid, OpenBookChestKw) <= 0)
        {
            StopOpenBook(_openBookUsed > 0
                ? "没有抉择宝箱，结束（用" + _openBookUsed + "/丢" + _openBookDropped + "）"
                : "没有抉择宝箱，停止");
            return;
        }

        if (!TryUseBagItemByKeyword(uid, OpenBookChestKw))
        {
            StopOpenBook("使用抉择宝箱失败");
            return;
        }

        _openBookUsed++;
        _openBookMovedOnce = false;
        _openBookPhase = OpenBookPhaseWaitUse;
        _openBookConfirmSinceMs = now;
        _openBookDelayUntilMs = now + OpenBookUseWaitMs;
        _openBookNote = "已用抉择宝箱×" + _openBookUsed + "，等确定弹框…";
        WriteLog("open-book use chest #" + _openBookUsed);
    }

    private static void TickOpenBookWaitUse(string uid, long now)
    {
        if (TryConfirmMessageBoxPanel())
        {
            WriteLog("open-book confirm MessageBoxPanel");
            _openBookPhase = OpenBookPhaseDrop;
            _openBookDelayUntilMs = now + 600;
            _openBookNote = "已点确定，扫背包丢书";
            return;
        }

        if (TryPickWildExWindowsOk())
        {
            WriteLog("open-book confirm WindowsMessage");
            _openBookPhase = OpenBookPhaseDrop;
            _openBookDelayUntilMs = now + 600;
            _openBookNote = "已点确定(窗)，扫背包丢书";
            return;
        }

        // 弹框已关：可能点过了或无需确认，继续丢书
        var box = GetUiPanel("MessageBoxPanel");
        var boxOpen = box != null && IsUnityObjectActive(box);
        if (!boxOpen && now - _openBookConfirmSinceMs >= OpenBookUseWaitMs + 1500)
        {
            _openBookPhase = OpenBookPhaseDrop;
            _openBookNote = "未见弹框，继续丢书";
            WriteLog("open-book no MessageBox, go drop");
            return;
        }

        if (now - _openBookConfirmSinceMs >= OpenBookConfirmTimeoutMs)
        {
            StopOpenBook("确定弹框超时未点到");
            return;
        }

        _openBookNote = "等确定弹框… "
                        + ((now - _openBookConfirmSinceMs) / 1000) + "s";
    }

    private static void TickOpenBookDrop(string uid, long now)
    {
        int index;
        object data;
        string name;
        if (!TryFindOpenBookDropTarget(uid, out index, out data, out name))
        {
            // 本轮书丢完，继续开下一箱
            _openBookPhase = OpenBookPhaseUse;
            _openBookNote = "无可丢技能书，继续找抉择宝箱";
            _openBookDelayUntilMs = now + 300;
            return;
        }

        if (!SendOpenBookDrop(uid, index, data, name))
        {
            StopOpenBook("丢弃发包失败: " + name);
            return;
        }

        _openBookPhase = OpenBookPhaseWaitDrop;
        _openBookDelayUntilMs = now + OpenBookDropWaitMs;
    }

    private static void TickOpenBookWaitDrop(string uid, long now)
    {
        var still = JunkDropSlotStillPresent(uid, _openBookPendIndex, _openBookPendId, _openBookPendName);
        if (!still)
        {
            _openBookDropped++;
            _openBookPendingDrop = false;
            _openBookMovedOnce = false;
            _openBookPhase = OpenBookPhaseDrop;
            _openBookNote = "已丢[" + _openBookPendName + "] 累计" + _openBookDropped;
            WriteLog("open-book drop ok name=" + _openBookPendName);
            _openBookDelayUntilMs = now + 200;
            return;
        }

        _openBookPendingDrop = false;
        if (!_openBookMovedOnce)
        {
            int px;
            int py;
            if (!TryGetPlayerXY(out px, out py))
            {
                StopOpenBook("丢弃失败且读坐标失败: " + _openBookPendName);
                return;
            }

            // 向右(+X) 向上(-Y) 两格
            _openBookMoveTx = px + OpenBookMoveDelta;
            _openBookMoveTy = py - OpenBookMoveDelta;
            _openBookMovedOnce = true;
            _openBookMoveSinceMs = now;
            _openBookPhase = OpenBookPhaseMove;
            _openBookNote = "丢弃失败，右上移至(" + _openBookMoveTx + "," + _openBookMoveTy + ")";
            WriteLog("open-book drop fail → move " + px + "," + py
                     + " → " + _openBookMoveTx + "," + _openBookMoveTy
                     + " name=" + _openBookPendName);
            TryWalkTo(_openBookMoveTx, _openBookMoveTy);
            return;
        }

        StopOpenBook("挪位后仍丢弃失败: " + _openBookPendName);
    }

    private static void TickOpenBookMove(string uid, long now)
    {
        int px;
        int py;
        TryGetPlayerXY(out px, out py);
        var near = Math.Abs(px - _openBookMoveTx) + Math.Abs(py - _openBookMoveTy) <= 1;
        if (!near && now - _openBookMoveSinceMs < OpenBookMoveTimeoutMs)
        {
            if ((now - _openBookMoveSinceMs) % 2000 < 80)
            {
                TryWalkTo(_openBookMoveTx, _openBookMoveTy);
            }

            _openBookNote = "挪位中 现" + px + "," + py
                            + " → " + _openBookMoveTx + "," + _openBookMoveTy;
            return;
        }

        // 到位或超时：再丢同一本
        object data = null;
        var items = GetItemDatasFromUid(uid);
        if (items != null && _openBookPendIndex >= 0 && _openBookPendIndex < items.Count)
        {
            var item = items[_openBookPendIndex];
            if (item != null && Convert.ToInt32(GetMember(item, "useFlag") ?? 0) == 1)
            {
                data = GetMember(item, "data");
            }
        }

        if (data == null || !IsOpenBookDropName(Convert.ToString(GetMember(data, "Name") ?? "") ?? ""))
        {
            // 格变了，重新找
            _openBookPhase = OpenBookPhaseDrop;
            _openBookNote = "挪位后重扫技能书";
            return;
        }

        var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? _openBookPendName;
        if (!SendOpenBookDrop(uid, _openBookPendIndex, data, name))
        {
            StopOpenBook("挪位后重丢发包失败: " + name);
            return;
        }

        _openBookPhase = OpenBookPhaseWaitDrop;
        _openBookDelayUntilMs = now + OpenBookDropWaitMs;
        _openBookNote = "挪位后再丢[" + name + "]";
    }

    private static bool IsOpenBookDropName(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return false;
        }

        if (name.IndexOf(OpenBookSkillKw, StringComparison.Ordinal) < 0)
        {
            return false;
        }

        if (name.IndexOf(OpenBookKeepKw, StringComparison.Ordinal) >= 0)
        {
            return false;
        }

        return true;
    }

    private static bool TryFindOpenBookDropTarget(
        string uid, out int index, out object data, out string name)
    {
        index = -1;
        data = null;
        name = "";
        try
        {
            var items = GetItemDatasFromUid(uid);
            if (items == null)
            {
                return false;
            }

            for (var i = 0; i < items.Count; i++)
            {
                var item = items[i];
                if (item == null || Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
                {
                    continue;
                }

                var d = GetMember(item, "data");
                if (d == null)
                {
                    continue;
                }

                var n = Convert.ToString(GetMember(d, "Name") ?? "") ?? "";
                if (!IsOpenBookDropName(n))
                {
                    continue;
                }

                index = i;
                data = d;
                name = n;
                return true;
            }
        }
        catch (Exception ex)
        {
            WriteLog("TryFindOpenBookDropTarget EX: " + RootMessage(ex));
        }

        return false;
    }

    private static bool SendOpenBookDrop(string uid, int index, object data, string name)
    {
        var itemMgr = GetManagerInstance("ItemManager");
        var send = FindSendBackPackMessage(itemMgr);
        if (send == null)
        {
            return false;
        }

        if (string.IsNullOrEmpty(name))
        {
            name = "#" + index;
        }

        var id = Convert.ToInt32(GetMember(data, "Id") ?? 0);
        var pile = Convert.ToInt32(GetMember(data, "Pile") ?? 1);
        if (pile < 1)
        {
            pile = 1;
        }

        send.Invoke(itemMgr, new object[] { "丢弃道具", index, pile, uid });
        _openBookPendingDrop = true;
        _openBookPendIndex = index;
        _openBookPendId = id;
        _openBookPendName = name;
        _openBookPendPile = pile;
        _openBookNote = "丢弃中[" + name + "]×" + pile;
        WriteLog("open-book drop send idx=" + index + " id=" + id + " name=" + name);
        return true;
    }

    private static void TickJunkDrop()
    {
        if (!_junkDropActive)
        {
            return;
        }

        try
        {
            var now = NowMs();
            if (now < _junkDropNextAtMs)
            {
                return;
            }

            if (_junkDropPending)
            {
                JunkDropVerifyPending();
                return;
            }

            if (_junkDropUids == null || _junkDropUidIdx >= _junkDropUids.Count)
            {
                StopJunkDrop("完成，共丢 " + _junkDropDropped + " 次");
                RefreshScriptTabIfVisible();
                return;
            }

            var uid = _junkDropUids[_junkDropUidIdx];
            if (!TryFindNextJunkDropTarget(uid, out var index, out var data, out var reason))
            {
                WriteLog("JunkDrop uid done " + uid + " (" + reason + ")");
                _junkDropUidIdx++;
                _junkDropFailStreak = 0;
                _junkDropNote = "角色切换 " + Math.Min(_junkDropUidIdx + 1, _junkDropUids.Count)
                                + "/" + _junkDropUids.Count;
                _junkDropNextAtMs = now + JunkDropIntervalMs;
                return;
            }

            if (!SendJunkDrop(uid, index, data))
            {
                StopJunkDrop("发包失败（SendBackPackMessage）");
                RefreshScriptTabIfVisible();
            }
        }
        catch (Exception ex)
        {
            WriteLog("TickJunkDrop EX: " + RootMessage(ex));
            StopJunkDrop("异常: " + RootMessage(ex));
            RefreshScriptTabIfVisible();
        }
    }

    private static void JunkDropVerifyPending()
    {
        var uid = _junkDropPendUid;
        var index = _junkDropPendIndex;
        var still = JunkDropSlotStillPresent(uid, index, _junkDropPendId, _junkDropPendName);
        if (!still)
        {
            _junkDropDropped++;
            _junkDropFailStreak = 0;
            _junkDropPending = false;
            _junkDropNote = "已丢[" + _junkDropPendName + "] 累计" + _junkDropDropped;
            WriteLog("JunkDrop ok uid=" + uid + " idx=" + index + " name=" + _junkDropPendName);
            _junkDropNextAtMs = NowMs(); // 间隔已在发包后等过，可立刻找下一件
            return;
        }

        _junkDropFailStreak++;
        WriteLog("JunkDrop fail#" + _junkDropFailStreak + " uid=" + uid
                 + " idx=" + index + " name=" + _junkDropPendName);
        if (_junkDropFailStreak >= JunkDropMaxFails)
        {
            _junkDropPending = false;
            StopJunkDrop("同一道具丢弃失败 " + JunkDropMaxFails
                         + " 次（可能地面满/二级密码），已停。最后: "
                         + _junkDropPendName);
            RefreshScriptTabIfVisible();
            return;
        }

        // 再丢一次同一格
        var items = GetItemDatasFromUid(uid);
        object data = null;
        if (items != null && index >= 0 && index < items.Count)
        {
            var item = items[index];
            if (item != null && Convert.ToInt32(GetMember(item, "useFlag") ?? 0) == 1)
            {
                data = GetMember(item, "data");
            }
        }

        if (data == null || !SendJunkDrop(uid, index, data))
        {
            _junkDropPending = false;
            StopJunkDrop("重试发包失败: " + _junkDropPendName);
            RefreshScriptTabIfVisible();
        }
    }

    private static bool SendJunkDrop(string uid, int index, object data)
    {
        var itemMgr = GetManagerInstance("ItemManager");
        var send = FindSendBackPackMessage(itemMgr);
        if (send == null)
        {
            return false;
        }

        var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
        if (string.IsNullOrEmpty(name))
        {
            name = "#" + index;
        }

        var id = Convert.ToInt32(GetMember(data, "Id") ?? 0);
        var pile = Convert.ToInt32(GetMember(data, "Pile") ?? 1);
        if (pile < 1)
        {
            pile = 1;
        }

        send.Invoke(itemMgr, new object[] { "丢弃道具", index, pile, uid });
        _junkDropPending = true;
        _junkDropPendUid = uid;
        _junkDropPendIndex = index;
        _junkDropPendId = id;
        _junkDropPendName = name;
        _junkDropPendPile = pile;
        _junkDropNote = "丢弃中[" + name + "]×" + pile + " 等确认…";
        _junkDropNextAtMs = NowMs() + JunkDropIntervalMs;
        WriteLog("JunkDrop send uid=" + uid + " idx=" + index + " id=" + id
                 + " pile=" + pile + " name=" + name);
        return true;
    }

    private static bool JunkDropSlotStillPresent(string uid, int index, int expectId, string expectName)
    {
        try
        {
            var items = GetItemDatasFromUid(uid);
            if (items == null || index < 0 || index >= items.Count)
            {
                return false;
            }

            var item = items[index];
            if (item == null || Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
            {
                return false;
            }

            var data = GetMember(item, "data");
            if (data == null)
            {
                return false;
            }

            var id = Convert.ToInt32(GetMember(data, "Id") ?? 0);
            if (expectId != 0 && id == expectId)
            {
                return true;
            }

            var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
            return !string.IsNullOrEmpty(expectName) && name == expectName;
        }
        catch
        {
            return true; // 读失败当作还在，避免误判成功狂丢
        }
    }

    private static System.Collections.IList GetItemDatasFromUid(string uid)
    {
        try
        {
            return FindType("PlayerDataHolder")?.GetMethod(
                    "GetItemDatasFromUid",
                    BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic)
                ?.Invoke(null, new object[] { uid }) as System.Collections.IList;
        }
        catch
        {
            return null;
        }
    }

    /// <summary>找当前角色背包下一件可丢垃圾。index 用列表下标（与丢弃协议 Haveitemindex 一致）。</summary>
    private static bool TryFindNextJunkDropTarget(
        string uid, out int index, out object data, out string missReason)
    {
        index = -1;
        data = null;
        missReason = "";
        var items = GetItemDatasFromUid(uid);
        if (items == null)
        {
            missReason = "无背包数据";
            return false;
        }

        var start = Math.Min(JunkDropBagStart, items.Count);
        for (var i = start; i < items.Count; i++)
        {
            var item = items[i];
            if (item == null)
            {
                continue;
            }

            if (Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
            {
                continue;
            }

            try
            {
                if (Convert.ToBoolean(GetMember(item, "isEquip") ?? false))
                {
                    continue;
                }
            }
            catch
            {
                // ignore
            }

            var d = GetMember(item, "data");
            if (d == null || !IsJunkDropTarget(d))
            {
                continue;
            }

            index = i;
            data = d;
            missReason = "";
            return true;
        }

        missReason = "无可丢道具";
        return false;
    }

    private static bool IsJunkDropTarget(object data)
    {
        try
        {
            var locked = Convert.ToInt32(GetMember(data, "Locked") ?? 0);
            if (locked != 0)
            {
                return false;
            }

            var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
            var secret = Convert.ToString(GetMember(data, "Secretname") ?? "") ?? "";
            for (var k = 0; k < JunkDropNameKeywords.Length; k++)
            {
                var kw = JunkDropNameKeywords[k];
                if ((!string.IsNullOrEmpty(name) && name.IndexOf(kw, StringComparison.Ordinal) >= 0)
                    || (!string.IsNullOrEmpty(secret) && secret.IndexOf(kw, StringComparison.Ordinal) >= 0))
                {
                    return true;
                }
            }

            // 宠物图鉴卡：按名字（TypeName「图鉴」不可靠）
            if ((!string.IsNullOrEmpty(name)
                 && (name.IndexOf("卡片", StringComparison.Ordinal) >= 0
                     || name.IndexOf("图鉴卡", StringComparison.Ordinal) >= 0))
                || (!string.IsNullOrEmpty(secret)
                    && (secret.IndexOf("卡片", StringComparison.Ordinal) >= 0
                        || secret.IndexOf("图鉴卡", StringComparison.Ordinal) >= 0)))
            {
                return true;
            }

            var typeName = Convert.ToString(GetMember(data, "TypeName") ?? "") ?? "";
            var flg = Convert.ToInt32(GetMember(data, "Flg") ?? 0);
            var unidentified = (flg & JunkDropAppraisalFlag) != 0;
            if (!unidentified)
            {
                return false;
            }

            var level = Convert.ToInt32(GetMember(data, "Level") ?? 0);
            if (level > JunkDropMaxLevel)
            {
                return false;
            }

            // 宝石类 / 装备类（排除宠物装备）
            if (typeName.IndexOf("宝石", StringComparison.Ordinal) >= 0)
            {
                return true;
            }

            if (typeName.IndexOf("装备", StringComparison.Ordinal) >= 0
                && typeName.IndexOf("宠物", StringComparison.Ordinal) < 0)
            {
                return true;
            }

            return false;
        }
        catch
        {
            return false;
        }
    }

    private static bool IsPerfectPetNamer(object pet, object data)
    {
        try
        {
            var flag = GetMember(pet, "isPrefectPet");
            if (flag is bool b)
            {
                return b;
            }
        }
        catch
        {
            // fall through
        }

        try
        {
            return Convert.ToInt32(GetMember(data, "Nowvitalbase") ?? 0)
                   >= Convert.ToInt32(GetMember(data, "Maxvitalbase") ?? 0)
                   && Convert.ToInt32(GetMember(data, "Nowstrbase") ?? 0)
                   >= Convert.ToInt32(GetMember(data, "Maxstrbase") ?? 0)
                   && Convert.ToInt32(GetMember(data, "Nowtghbase") ?? 0)
                   >= Convert.ToInt32(GetMember(data, "Maxtghbase") ?? 0)
                   && Convert.ToInt32(GetMember(data, "Nowquickbase") ?? 0)
                   >= Convert.ToInt32(GetMember(data, "Maxquickbase") ?? 0)
                   && Convert.ToInt32(GetMember(data, "Nowmagicbase") ?? 0)
                   >= Convert.ToInt32(GetMember(data, "Maxmagicbase") ?? 0);
        }
        catch
        {
            return false;
        }
    }

    private static int GetPetGradeValueNamer(object petMgr, MethodInfo getFileValue, object data)
    {
        if (petMgr != null && getFileValue != null)
        {
            try
            {
                return Convert.ToInt32(getFileValue.Invoke(petMgr, new object[] { data }) ?? 0);
            }
            catch
            {
                // fall through
            }
        }

        try
        {
            var maxSum = Convert.ToInt32(GetMember(data, "Maxvitalbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Maxstrbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Maxtghbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Maxquickbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Maxmagicbase") ?? 0);
            var nowSum = Convert.ToInt32(GetMember(data, "Nowvitalbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Nowstrbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Nowtghbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Nowquickbase") ?? 0)
                         + Convert.ToInt32(GetMember(data, "Nowmagicbase") ?? 0);
            return maxSum - nowSum;
        }
        catch
        {
            return 0;
        }
    }

    private static bool TryGetMaxResetBaseRandomNamer(object data, out int maxRand)
    {
        maxRand = 0;
        var reset = GetMember(data, "ResetBaseInfo");
        if (reset == null)
        {
            return false;
        }

        foreach (var name in new[]
                 {
                     "Vitalbase", "Strbase", "Tghbase", "Quickbase", "Magicbase",
                     "vitalbase_", "strbase_", "tghbase_", "quickbase_", "magicbase_"
                 })
        {
            var v = ReadIntMemberNamer(reset, name);
            if (v > maxRand)
            {
                maxRand = v;
            }
        }

        return true;
    }

    private static string FormatPetMarkNameNamer(bool perfect, int grade, int maxRand)
    {
        var head = perfect ? "#满" : "#" + grade;
        if (maxRand >= PetNamerMinRandomSuffix)
        {
            return head + "@" + maxRand;
        }

        return head;
    }

    private static bool NeedsPetRenameMarkNamer(string display, string newName, int maxRand)
    {
        if (string.IsNullOrEmpty(display) || string.IsNullOrEmpty(newName))
        {
            return false;
        }

        if (string.Equals(display, newName, StringComparison.Ordinal))
        {
            return false;
        }

        if (!display.StartsWith("#", StringComparison.Ordinal))
        {
            return true;
        }

        var at = display.LastIndexOf('@');
        if (at > 0 && at < display.Length - 1)
        {
            if (int.TryParse(display.Substring(at + 1), out var tagged)
                && tagged < PetNamerMinRandomSuffix)
            {
                return true;
            }
        }
        else if (maxRand >= PetNamerMinRandomSuffix)
        {
            return true;
        }

        return false;
    }

    private static string GetDisplayPetNameNamer(object data)
    {
        var free = Convert.ToString(GetMember(data, "FreeName") ?? "") ?? "";
        if (!string.IsNullOrEmpty(free))
        {
            return free;
        }

        return Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
    }

    private static MethodInfo FindSendChangePetNameNamer(object petMgr)
    {
        if (petMgr == null)
        {
            return null;
        }

        foreach (var m in petMgr.GetType().GetMethods(
                     BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
        {
            if (m.Name != "SendChangePetName")
            {
                continue;
            }

            var ps = m.GetParameters();
            if (ps.Length == 3
                && ps[0].ParameterType == typeof(string)
                && (ps[1].ParameterType == typeof(int) || ps[1].ParameterType == typeof(short))
                && ps[2].ParameterType == typeof(string))
            {
                return m;
            }
        }

        return null;
    }

    private static MethodInfo FindGetPetFileValueNamer(object petMgr)
    {
        if (petMgr == null)
        {
            return null;
        }

        foreach (var m in petMgr.GetType().GetMethods(
                     BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
        {
            if (m.Name != "GetPetFileValue")
            {
                continue;
            }

            if (m.GetParameters().Length == 1)
            {
                return m;
            }
        }

        return null;
    }

    private static int ReadIntMemberNamer(object obj, string name)
    {
        try
        {
            var v = GetMember(obj, name);
            if (v == null || v is bool)
            {
                return 0;
            }

            return Convert.ToInt32(v);
        }
        catch
        {
            return 0;
        }
    }

    private static void InvokeDailyClaimToggle(string methodName, string label)
    {
        try
        {
            WriteLog(methodName);
            var t = EnsureFeatureType("SeqChapterDailyClaim", "hotfixdata/SeqChapterDailyClaim.dll.bytes");
            if (t == null)
            {
                Tip(label + " DLL 加载失败（见日志）");
                return;
            }

            var m = t.GetMethod(methodName, BindingFlags.Public | BindingFlags.Static, null, Type.EmptyTypes, null);
            if (m == null)
            {
                Tip(label + "入口缺失（请更新 DailyClaim DLL）");
                return;
            }

            var r = m.Invoke(null, null);
            Tip(r is bool b && b ? label + "已开始" : label + "已停止/未开始");
        }
        catch (Exception ex)
        {
            WriteLog(methodName + " EX: " + RootMessage(ex));
            Tip(label + "失败: " + RootMessage(ex));
        }
    }

