    /// <summary>
    /// 中控「一键打卡」。等同更多→快速打卡→一键打卡：SendMenu(2,"全队打卡")。
    /// 不进脚本切页，只给中控用。
    /// </summary>
    public static string TryStartFastPunchFromControl()
    {
        var role = GetManagerInstance("RoleManager");
        if (role == null)
        {
            SetControlResult(false, "无 RoleManager");
            return "无 RoleManager";
        }

        try
        {
            var flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
            var send = role.GetType().GetMethod(
                "SendMenu", flags, null,
                new[] { typeof(int), typeof(string), typeof(string), typeof(string) }, null);
            if (send != null)
            {
                send.Invoke(role, new object[] { 2, "全队打卡", "", "" });
            }
            else
            {
                send = role.GetType().GetMethod(
                    "SendMenu", flags, null, new[] { typeof(int), typeof(string) }, null);
                if (send == null)
                {
                    SetControlResult(false, "SendMenu 不可用");
                    return "SendMenu 不可用";
                }

                send.Invoke(role, new object[] { 2, "全队打卡" });
            }

            Tip("已打卡");
            WriteLog("fast-punch SendMenu(2,全队打卡)");
            SetControlResult(true, "已打卡");
            return "已打卡";
        }
        catch (Exception ex)
        {
            var note = "打卡失败: " + RootMessage(ex);
            WriteLog("fast-punch EX " + RootMessage(ex));
            SetControlResult(false, note);
            return note;
        }
    }

    // ----- 中控：开始遇敌 / 停止遇敌（无脚本页入口） -----
    private const long StopEncounterTimeoutMs = 120000;
    private const long StopEncounterRetryMs = 1500;
    private static bool _stopEncounterActive;
    private static long _stopEncounterSinceMs;
    private static long _stopEncounterLastSendMs;
    private static string _stopEncounterNote = "";

    /// <summary>
    /// 中控「开始遇敌」：切护航战斗模式（顺带开自动战斗）并开遇敌。
    /// 遇敌已开则仍切模式，回报「已忽略」。
    /// </summary>
    public static string TryStartEncounterFromControl()
    {
        if (!IsLocalCaptain())
        {
            SetControlResult(false, "请在队长客户端运行");
            return "请在队长客户端运行";
        }

        // 护航战斗模式内会 EnsureOfficialAutoBattleOn，此处不再重复开自动战斗
        if (_battleMode != ModeEscortBattle)
        {
            SelectBattleMode(ModeEscortBattle);
        }

        if (GetEncounterStatus() != 0)
        {
            SetControlResult(true, "遇敌已开，已忽略");
            Tip("遇敌已开，已忽略");
            WriteLog("start-encounter already on, ignore (escort mode)");
            return "已忽略";
        }

        if (!TrySendCaptainAutoBattle("开始挂机"))
        {
            if (GetEncounterStatus() != 0)
            {
                SetControlResult(true, "已开始遇敌");
                return "已开始遇敌";
            }

            SetControlResult(false, "开始遇敌发包失败");
            return "开始遇敌发包失败";
        }

        Tip("已开始遇敌");
        WriteLog("start-encounter SendAutoBattle 开始挂机 + escort mode");
        SetControlResult(true, "已开始遇敌");
        return "已开始遇敌";
    }

    /// <summary>
    /// 中控「停止遇敌」：停挂机；若在战斗中则等退出战斗后再回报成功。
    /// </summary>
    public static string TryStartStopEncounterFromControl()
    {
        if (_stopEncounterActive)
        {
            SetControlResult(false, "停止遇敌已在运行");
            return "停止遇敌已在运行";
        }

        if (!IsLocalCaptain())
        {
            SetControlResult(false, "请在队长客户端运行");
            return "请在队长客户端运行";
        }

        var enc = GetEncounterStatus() != 0;
        var battle = IsInBattleNow();
        if (!enc && !battle)
        {
            SetControlResult(true, "停止遇敌 已是非遇敌且非战斗");
            Tip("停止遇敌：无需操作");
            WriteLog("stop-encounter already idle");
            return "已启动";
        }

        _stopEncounterActive = true;
        _stopEncounterSinceMs = NowMs();
        _stopEncounterLastSendMs = 0;
        _stopEncounterNote = enc ? "停止挂机…" : "等退出战斗…";
        if (enc)
        {
            TrySendCaptainAutoBattle("停止挂机");
            _stopEncounterLastSendMs = NowMs();
        }

        SetControlResult(false, "进行中 停止遇敌");
        Tip("停止遇敌开始");
        WriteLog("stop-encounter start enc=" + enc + " battle=" + battle);
        RefreshScriptRunStatus();
        return "已启动";
    }

    private static void StopStopEncounter(string reason, bool success)
    {
        if (!_stopEncounterActive)
        {
            return;
        }

        _stopEncounterActive = false;
        _stopEncounterNote = reason ?? "";
        SetControlResult(success, "停止遇敌 " + (reason ?? ""));
        Tip((success ? "停止遇敌成功：" : "停止遇敌失败：") + (reason ?? ""));
        WriteLog("stop-encounter stop ok=" + success + " " + reason);
        RefreshScriptRunStatus();
    }

    private static void TickStopEncounter()
    {
        if (!_stopEncounterActive)
        {
            return;
        }

        var now = NowMs();
        if (now - _stopEncounterSinceMs > StopEncounterTimeoutMs)
        {
            StopStopEncounter("超时 遇敌=" + GetEncounterStatus() + " 战斗=" + IsInBattleNow(), false);
            return;
        }

        if (GetEncounterStatus() != 0)
        {
            if (now - _stopEncounterLastSendMs >= StopEncounterRetryMs)
            {
                TrySendCaptainAutoBattle("停止挂机");
                _stopEncounterLastSendMs = now;
            }

            _stopEncounterNote = "停遇敌中…";
            RefreshScriptRunStatus();
            return;
        }

        if (IsInBattleNow())
        {
            _stopEncounterNote = "等退出战斗…";
            RefreshScriptRunStatus();
            return;
        }

        StopStopEncounter("已停遇敌并退出战斗", true);
    }

    /// <summary>中控「打开跳过动画」。已开则不动。成功返回「已打开」或「已忽略」。</summary>
    public static string TryEnableSkipAnimFromControl()
    {
        if (_skipBattleAnim)
        {
            SetControlResult(true, "跳过动画已开启，已忽略");
            return "已忽略";
        }

        CaptureSkipAnimDelayInputsFromUi();
        _skipBattleAnim = true;
        _skipBattleAnimFlushLogged = false;
        _skipBattleAnimCmdSinceMs = 0;
        _skipBattleAnimManualDone = false;
        Tip("跳过动画已开启");
        WriteLog("EnableSkipAnimFromControl=true");
        if (_tab == TabBattle)
        {
            ClearBody();
            BuildBattleBody();
            RefreshTabButtonLabels();
        }

        SetControlResult(true, "跳过动画已开启");
        return "已打开";
    }

    private static void CaptureSkipAnimDelayInputsFromUi()
    {
        _skipAnimFirstDelayStr = ReadNavField(_skipAnimFirstDelayInput, _skipAnimFirstDelayStr);
        _skipAnimEveryDelayStr = ReadNavField(_skipAnimEveryDelayInput, _skipAnimEveryDelayStr);
        _skipAnimFirstRoundExtraSec = ParseSkipAnimDelaySec(_skipAnimFirstDelayStr);
        _skipAnimEveryRoundExtraSec = ParseSkipAnimDelaySec(_skipAnimEveryDelayStr);
        _skipAnimFirstDelayStr = FormatSkipAnimDelaySec(_skipAnimFirstRoundExtraSec);
        _skipAnimEveryDelayStr = FormatSkipAnimDelaySec(_skipAnimEveryRoundExtraSec);
    }

    private static float ParseSkipAnimDelaySec(string raw)
    {
        if (string.IsNullOrEmpty(raw))
        {
            return 0f;
        }

        float v;
        if (!float.TryParse(raw.Trim(), out v) || float.IsNaN(v) || float.IsInfinity(v))
        {
            return 0f;
        }

        if (v < 0f)
        {
            return 0f;
        }

        if (v > 30f)
        {
            return 30f;
        }

        return v;
    }

    /// <summary>战斗辅助：在各单位 BattleUnitUI 血条下方画血/蓝与恢·攻无等。</summary>
    private static void TickBattleAssist()
    {
        try
        {
            if (!_battleAssist || !IsInBattleNow())
            {
                if (BattleAssistLabels.Count > 0)
                {
                    ClearBattleAssistLabels();
                }

                return;
            }

            var now = NowMs();
            if (now - _battleAssistLastRefreshMs < BattleAssistRefreshMs)
            {
                return;
            }

            _battleAssistLastRefreshMs = now;
            RefreshBattleAssistLabels();
        }
        catch (Exception ex)
        {
            WriteLog("TickBattleAssist EX: " + RootMessage(ex));
        }
    }

    private static void ClearBattleAssistLabels()
    {
        foreach (var kv in BattleAssistLabels)
        {
            try
            {
                DestroyUnityObject(kv.Value);
            }
            catch
            {
                // ignore
            }
        }

        BattleAssistLabels.Clear();
    }

    private static void RefreshBattleAssistLabels()
    {
        var brc = FindType("BattleRoleContainer");
        var dic = brc?.GetField("BattleRoleDic", BindingFlags.Public | BindingFlags.Static)
            ?.GetValue(null) as IDictionary;
        if (dic == null || dic.Count == 0)
        {
            ClearBattleAssistLabels();
            return;
        }

        var alive = new HashSet<int>();
        foreach (DictionaryEntry kv in dic)
        {
            var role = kv.Value;
            if (role == null)
            {
                continue;
            }

            var idx = Convert.ToInt32(GetMember(role, "Index") ?? kv.Key ?? -1);
            if (idx < 0)
            {
                continue;
            }

            var dead = Convert.ToBoolean(GetMember(role, "IsDead") ?? false);
            var roleData = GetMember(role, "RoleData");
            var ch = roleData != null ? GetMember(roleData, "Char") : null;
            var hp = ch != null ? Convert.ToInt32(GetMember(ch, "Hp") ?? 0) : 0;
            if (dead || hp <= 0)
            {
                continue;
            }

            alive.Add(idx);
            var mp = ch != null ? Convert.ToInt32(GetMember(ch, "Mp") ?? 0) : 0;
            var bc = GetBattleRoleStatus(role);
            var line = FormatBattleAssistLine(hp, mp, bc);
            EnsureBattleAssistLabel(role, idx, line);
        }

        var stale = new List<int>();
        foreach (var idx in BattleAssistLabels.Keys)
        {
            if (!alive.Contains(idx))
            {
                stale.Add(idx);
            }
        }

        for (var i = 0; i < stale.Count; i++)
        {
            object go;
            if (BattleAssistLabels.TryGetValue(stale[i], out go))
            {
                DestroyUnityObject(go);
                BattleAssistLabels.Remove(stale[i]);
            }
        }
    }

    private static string FormatBattleAssistLine(int hp, int mp, long bc)
    {
        var sb = new StringBuilder();
        sb.Append("血").Append(hp).Append(" 蓝").Append(mp);
        if ((bc & BcRcvUp) != 0)
        {
            sb.Append(" 恢");
        }

        // 六种理论互斥，按用户顺序只写一种
        if ((bc & BcAtkAbsorb) != 0)
        {
            sb.Append(" 攻吸");
        }
        else if ((bc & BcAtkInvalid) != 0)
        {
            sb.Append(" 攻无");
        }
        else if ((bc & BcAtkRebound) != 0)
        {
            sb.Append(" 攻反");
        }
        else if ((bc & BcMagicInvalid) != 0)
        {
            sb.Append(" 魔无");
        }
        else if ((bc & BcMagicRebound) != 0)
        {
            sb.Append(" 魔反");
        }
        else if ((bc & BcMagicAbsorb) != 0)
        {
            sb.Append(" 魔吸");
        }

        return sb.ToString();
    }

    private static void EnsureBattleAssistLabel(object role, int idx, string line)
    {
        object labelGo;
        if (!BattleAssistLabels.TryGetValue(idx, out labelGo) || labelGo == null || IsUnityNull(labelGo))
        {
            labelGo = CreateBattleAssistLabel(role);
            if (labelGo == null)
            {
                BattleAssistLabels.Remove(idx);
                return;
            }

            BattleAssistLabels[idx] = labelGo;
        }

        var text = GetComp(labelGo, "UnityEngine.UI.Text")
                   ?? GetComp(labelGo, "TMPro.TextMeshProUGUI");
        if (text == null)
        {
            var child = FindChildByName(labelGo, "L");
            if (child != null)
            {
                text = GetComp(child, "UnityEngine.UI.Text")
                       ?? GetComp(child, "TMPro.TextMeshProUGUI");
            }
        }

        if (text != null)
        {
            SetText(text, line, 14);
        }
    }

    private static object CreateBattleAssistLabel(object role)
    {
        var worldUi = GetMember(role, "WorldUI") ?? GetMember(role, "m_WorldUI");
        if (worldUi == null || IsUnityNull(worldUi))
        {
            return null;
        }

        var isEnemy = Convert.ToBoolean(GetMember(worldUi, "isEmeny")
                                        ?? GetMember(worldUi, "isEnemy")
                                        ?? false);
        // 己方贴蓝条(mpSlider)；敌方无蓝条则贴血条
        var slider = isEnemy
            ? (GetMember(worldUi, "enemeyHpSlider") ?? GetProp(worldUi, "enemeyHpSlider"))
            : (GetMember(worldUi, "mpSlider") ?? GetProp(worldUi, "mpSlider"));
        if (slider == null)
        {
            slider = GetMember(worldUi, "hpSlider") ?? GetProp(worldUi, "hpSlider");
        }

        var sliderGo = slider != null
            ? (GetProp(slider, "gameObject") ?? slider)
            : null;
        var area = isEnemy
            ? (GetMember(worldUi, "enemyArea") ?? GetProp(worldUi, "enemyArea"))
            : (GetMember(worldUi, "playerArea") ?? GetProp(worldUi, "playerArea"));
        // 清掉旧版挂在 area / 其它位置的残留
        DestroyUnityObject(FindChildByName(area, BattleAssistChildName));
        DestroyUnityObject(FindChildByName(sliderGo, BattleAssistChildName));
        DestroyUnityObject(FindChildByName(
            GetProp(worldUi, "gameObject") ?? worldUi, BattleAssistChildName));

        var parent = sliderGo ?? area ?? GetProp(worldUi, "gameObject") ?? worldUi;
        if (parent == null || IsUnityNull(parent))
        {
            return null;
        }

        var rtType = RequireType("UnityEngine.RectTransform");
        var go = CreateUiChild(parent, BattleAssistChildName, rtType);

        // 紧贴条下方：只向下、向右放大，不往上挤血/蓝条
        var barH = 12f;
        try
        {
            var srt = RequireRect(parent, "bas");
            var rect = GetProp(srt, "rect");
            if (rect != null)
            {
                barH = Math.Max(8f, Convert.ToSingle(GetMember(rect, "height") ?? barH));
            }
        }
        catch
        {
            // ignore
        }

        // 左上锚点：加宽向右，加高向下
        SetAnchoredTopLeft(RequireRect(go, "ba"), 0f, -(barH + 1f), 220f, 28f);

        var bg = AddComp(go, "UnityEngine.UI.Image");
        SetColor(bg, 0f, 0f, 0f, 0.88f);
        try
        {
            SetProp(bg, "raycastTarget", false);
        }
        catch
        {
            // ignore
        }

        try
        {
            var cg = AddComp(go, "UnityEngine.CanvasGroup");
            SetProp(cg, "blocksRaycasts", false);
            SetProp(cg, "interactable", false);
        }
        catch
        {
            // ignore
        }

        var lab = CreateUiChild(go, "L", rtType);
        StretchFull(RequireRect(lab, "bal"));
        var text = AddText(lab);
        SetProp(text, "color", MakeColor(1f, 1f, 1f, 1f));
        try
        {
            SetProp(text, "raycastTarget", false);
            SetProp(text, "alignment", EnumValue("UnityEngine.TextAnchor", "MiddleLeft", 3));
        }
        catch
        {
            // ignore
        }

        SetText(text, "", 14);
        return go;
    }

    private static object FindChildByName(object parent, string name)
    {
        try
        {
            var tr = GetProp(parent, "transform") ?? parent;
            if (tr == null)
            {
                return null;
            }

            var find = tr.GetType().GetMethod("Find", new[] { typeof(string) });
            var childTr = find?.Invoke(tr, new object[] { name });
            if (childTr == null || IsUnityNull(childTr))
            {
                return null;
            }

            return GetProp(childTr, "gameObject") ?? childTr;
        }
        catch
        {
            return null;
        }
    }

    private static void DestroyUnityObject(object obj)
    {
        if (obj == null || IsUnityNull(obj))
        {
            return;
        }

        try
        {
            var go = GetProp(obj, "gameObject") ?? obj;
            var ot = FindType("UnityEngine.Object");
            var destroy = ot?.GetMethod("Destroy", BindingFlags.Public | BindingFlags.Static, null,
                new[] { ot }, null);
            destroy?.Invoke(null, new object[] { go });
        }
        catch
        {
            try
            {
                SetGoActive(obj, false);
            }
            catch
            {
                // ignore
            }
        }
    }

    private static string FormatSkipAnimDelaySec(float sec)
    {
        if (sec <= 0f)
        {
            return "0";
        }

        if (Math.Abs(sec - (float)Math.Round(sec)) < 0.001f)
        {
            return ((int)Math.Round(sec)).ToString();
        }

        return sec.ToString("0.##");
    }

    /// <summary>本次 hold 是否为首回合选指令门闸。</summary>
    private static bool IsSkipAnimFirstBattleRound()
    {
        return _skipAnimHoldForFirstSelect;
    }

    /// <summary>当前门闸应等待的额外毫秒：首回合/每回合分开；与石化 3s 取较大。</summary>
    private static long GetSkipAnimHoldNeedMs(bool menuNon)
    {
        CaptureSkipAnimDelayInputsFromUi();
        var extraSec = _skipAnimHoldForFirstSelect
            ? _skipAnimFirstRoundExtraSec
            : _skipAnimEveryRoundExtraSec;
        var extraMs = (long)(extraSec * 1000f + 0.5f);
        if (extraMs < 0)
        {
            extraMs = 0;
        }

        return menuNon ? Math.Max(extraMs, SkipAnimMenuNonHoldMs) : extraMs;
    }

    private static void TickEscortBattle()
    {
        var inBattle = IsInBattleNow();
        if (_battleMode != ModeEscortBattle)
        {
            _escortBattlePrevInBattle = inBattle;
            if (_escortBattleBusy)
            {
                AbortEscortBattle("模式已关");
            }

            return;
        }

        MaybeRefreshEscortBattleTitle();

        if (_escortBattleBusy)
        {
            var nowBusy = NowMs();
            if (_escortBattlePhase >= 10)
            {
                TickEscortBattleExtract(nowBusy);
            }
            else
            {
                TickEscortBattleRefill(nowBusy);
            }

            _escortBattlePrevInBattle = inBattle;
            return;
        }

        if (inBattle)
        {
            _escortBattleExitAtMs = 0;
            _escortBattlePrevInBattle = true;
            return;
        }

        var now = NowMs();
        if (_escortBattlePrevInBattle)
        {
            _escortBattlePrevInBattle = false;
            _escortBattleExitAtMs = now;
            _escortBattleLastEndUnix = UnixNow();
            _escortBattleStopReason = "";
            WriteLog("escort-battle 战斗结束");
            return;
        }

        if (_escortBattleExitAtMs <= 0)
        {
            return;
        }

        var sinceExit = now - _escortBattleExitAtMs;
        if (sinceExit < EscortBattleExitSettleMs)
        {
            return;
        }

        var uid = GetMainPlayerUidSafe();
        if (string.IsNullOrEmpty(uid))
        {
            if (sinceExit > EscortBattleExitGiveUpMs)
            {
                WriteLog("escort-battle skip exit: uid empty");
                _escortBattleExitAtMs = 0;
            }

            return;
        }

        // 战后队伍不足：停挂机，不自动补魔/提取（避免又开挂）
        var teamNum = GetEscortTeamNum();
        if (teamNum < EscortTeamMinMembers)
        {
            _escortBattleExitAtMs = 0;
            var reason = "战后队伍不足" + EscortTeamMinMembers + "人（当前" + teamNum + "），已停战";
            var wasHang = GetEncounterStatus() != 0;
            if (wasHang)
            {
                TrySendLocalAutoBattle("停止挂机");
            }

            SetEscortBattleNote(reason);
            _escortBattleStopReason = reason;
            Tip("护航战斗：" + reason);
            WriteLog("escort-battle 停战 reason=" + reason
                     + " wasHang=" + wasHang
                     + " fights=" + _escortBattleFightCount);
            return;
        }

        var mp = ReadMpPond(uid);
        var hp = ReadHpPond(uid);
        var pondZero = mp == 0 || (_escortBattleHpOn && hp == 0);
        if (pondZero && sinceExit < EscortBattleMpZeroRetryMs)
        {
            return;
        }

        _escortBattleExitAtMs = 0;
        WriteLog("escort-battle exit mp=" + mp + " hp=" + hp
                 + " hpOn=" + _escortBattleHpOn
                 + " item=" + EscortBattleMpItemId
                 + " fights=" + _escortBattleFightCount
                 + " extract=" + _escortBattleExtractOn
                 + " team=" + teamNum);
        UpdateEscortBattleTitlePools(hp, mp);
        if (_escortBattleExtractOn)
        {
            _escortBattleFightCount++;
            if (_escortBattleFightCount > EscortBattleExtractEvery)
            {
                _escortBattleFightCount = EscortBattleExtractEvery;
            }

            RefreshTitleFromFeature();
        }

        var needExtract = _escortBattleExtractOn && _escortBattleFightCount >= EscortBattleExtractEvery;
        var needHp = _escortBattleHpOn && hp >= 0 && hp < EscortBattleHpLow;
        var needMp = mp >= 0 && mp < EscortBattleMpLow;
        _escortBattlePendingHp = false;
        _escortBattlePendingMp = false;
        _escortBattleResumeHang = false;
        if (needHp || needMp)
        {
            _escortBattleExtractAfterRefill = needExtract;
            if (needHp && needMp)
            {
                _escortBattlePendingMp = true;
            }

            if (needHp)
            {
                BeginEscortBattleRefill(uid, hp, EscortRefillHp);
            }
            else
            {
                BeginEscortBattleRefill(uid, mp, EscortRefillMp);
            }
        }
        else if (needExtract)
        {
            _escortBattleResumeHang = GetEncounterStatus() != 0;
            BeginEscortBattleExtract();
        }
        else
        {
            var note = _escortBattleHpOn
                ? ("血池 " + hp + " 魔池 " + mp + "，未补")
                : ("魔池 " + mp + "，未补魔");
            SetEscortBattleNote(note
                                + (_escortBattleExtractOn
                                    ? ("  采集" + _escortBattleFightCount + "/" + EscortBattleExtractEvery)
                                    : ""));
        }
    }

    private static void BeginEscortBattleRefill(string uid, int pond, int kind)
    {
        _escortBattleRefillKind = kind == EscortRefillHp ? EscortRefillHp : EscortRefillMp;
        _escortBattleResumeHang = GetEncounterStatus() != 0 || _escortBattleResumeHang;
        _escortBattleBusy = true;
        _escortBattlePhase = 1;
        _escortBattleWaitMs = NowMs();
        _escortBattleWhTabDone = false;
        _escortBattleLastWhOpenMs = 0;
        TrySendLocalAutoBattle("停止挂机");
        var itemId = CurrentEscortRefillItemId();
        var useNum = CurrentEscortRefillUseNum();
        var bag = CountBagItemById(uid, itemId);
        var name = EscortBattleItemNameFor(itemId);
        var label = CurrentEscortRefillLabel();
        var low = _escortBattleRefillKind == EscortRefillHp ? EscortBattleHpLow : EscortBattleMpLow;
        SetEscortBattleNote(label + pond + "＜" + low
                            + "，停挂机。背包" + name + "(" + itemId + ")×"
                            + bag + "/" + useNum);
        Tip(label + "不足" + pond + "，暂停战斗准备补" + (_escortBattleRefillKind == EscortRefillHp ? "血" : "魔"));
        WriteLog("escort-battle refill start kind=" + label + " pond=" + pond + " bag=" + bag
                 + " hang=" + _escortBattleResumeHang);
    }

    private static void TickEscortBattleRefill(long now)
    {
        var uid = GetMainPlayerUidSafe();
        if (string.IsNullOrEmpty(uid))
        {
            if (now - _escortBattleWaitMs > 2000)
            {
                FailEscortBattleRefill("没有角色");
            }

            return;
        }

        if (IsInBattleNow())
        {
            return;
        }

        var refillId = CurrentEscortRefillItemId();
        var useNum = CurrentEscortRefillUseNum();
        var refillName = EscortBattleItemNameFor(refillId);
        var useType = CurrentEscortRefillType();

        if (_escortBattlePhase == 1)
        {
            if (now - _escortBattleWaitMs < 400)
            {
                return;
            }

            var bag = CountBagItemById(uid, refillId);
            if (bag >= useNum)
            {
                _escortBattlePhase = 5;
                _escortBattleWaitMs = now;
                SetEscortBattleNote("背包已有" + bag + "，准备使用");
                return;
            }

            _escortBattleBagBefore = bag;
            ClearAccountBankItemCache();
            TryOpenAccountItemWarehouseUi(uid);
            TrySwitchChildWareHouseToAccountTab(uid);
            _escortBattlePhase = 2;
            _escortBattleWaitMs = now;
            SetEscortBattleNote("背包" + bag + "＜" + useNum + "，开超银取"
                                + (useNum - bag));
            return;
        }

        if (_escortBattlePhase == 2)
        {
            var waited = now - _escortBattleWaitMs;
            if (waited > 8000)
            {
                FailEscortBattleRefill("超银回包超时");
                return;
            }

            if (waited > 400)
            {
                var child = FindExistingUiByType("ChildWareHousePanel", "FindChildPanelByType");
                if (child == null)
                {
                    if (now - _escortBattleLastWhOpenMs >= EscortBattleWhOpenGapMs)
                    {
                        _escortBattleLastWhOpenMs = now;
                        TryOpenAccountItemWarehouseUi(uid);
                    }
                }
                else if (!_escortBattleWhTabDone)
                {
                    if (TrySwitchChildWareHouseToAccountTab(uid))
                    {
                        _escortBattleWhTabDone = true;
                    }
                }
            }

            IList update;
            if (!TryGetAccountBankUpdateItems(out update) || update.Count == 0)
            {
                SetEscortBattleNote("等超银回包… " + (waited / 1000) + "s");
                return;
            }

            var bankIndex = -1;
            var pile = 0;
            for (var i = 0; i < update.Count; i++)
            {
                var row = update[i];
                if (row == null)
                {
                    continue;
                }

                var itemId = Convert.ToInt32(GetMember(row, "Itemid") ?? GetProp(row, "Itemid") ?? 0);
                if (itemId != refillId)
                {
                    continue;
                }

                bankIndex = Convert.ToInt32(GetMember(row, "Index") ?? GetProp(row, "Index") ?? -1);
                pile = Convert.ToInt32(GetMember(row, "Pile") ?? GetProp(row, "Pile") ?? 0);
                break;
            }

            var bag = CountBagItemById(uid, refillId);
            var need = useNum - bag;
            if (need < 1)
            {
                TryDismissItemBankAfterStore(uid);
                _escortBattlePhase = 5;
                _escortBattleWaitMs = now;
                return;
            }

            if (bankIndex < 0 || pile < need)
            {
                FailEscortBattleRefill("超银" + refillName + "(" + refillId
                                       + ")不足，仓" + pile + " 包" + bag + " 需" + useNum);
                return;
            }

            if (!TrySendAccountBankTakeNum(uid, bankIndex, need))
            {
                FailEscortBattleRefill("超银取道具发包失败");
                return;
            }

            _escortBattleBagBefore = bag;
            _escortBattlePhase = 3;
            _escortBattleWaitMs = now;
            SetEscortBattleNote("已请求从超银取" + need + "，等入包");
            Tip("从超银取" + refillName + "×" + need);
            return;
        }

        if (_escortBattlePhase == 3)
        {
            var bag = CountBagItemById(uid, refillId);
            if (bag >= useNum)
            {
                TryDismissItemBankAfterStore(uid);
                _escortBattlePhase = 5;
                _escortBattleWaitMs = now;
                SetEscortBattleNote("入包成功 " + bag + "，准备使用");
                return;
            }

            if (now - _escortBattleWaitMs > 8000)
            {
                FailEscortBattleRefill("超银取出后背包仍不足，现" + bag);
                return;
            }

            SetEscortBattleNote("等取出入包… 现" + bag + "/" + useNum);
            return;
        }

        if (_escortBattlePhase == 5)
        {
            if (now - _escortBattleWaitMs < 300)
            {
                return;
            }

            var bag = CountBagItemById(uid, refillId);
            if (bag < useNum)
            {
                FailEscortBattleRefill("使用前背包不足 " + bag + "/" + useNum);
                return;
            }

            if (!TrySendUsePoolItem(uid, useType, refillId, useNum))
            {
                FailEscortBattleRefill(useType + "发包失败");
                return;
            }

            _escortBattlePhase = 6;
            _escortBattleWaitMs = now;
            SetEscortBattleNote("已发" + useType + " " + refillName
                                + "(" + refillId + ")×" + useNum);
            Tip(useType + " " + refillName + "×" + useNum);
            return;
        }

        if (_escortBattlePhase == 6)
        {
            if (now - _escortBattleWaitMs < 800)
            {
                return;
            }

            FinishEscortBattleRefillOk();
        }
    }

    private static void FinishEscortBattleRefillOk()
    {
        var uid = GetMainPlayerUidSafe();
        TryDismissItemBankAfterStore(uid);
        var kind = _escortBattleRefillKind;
        var hp = ReadHpPond(uid);
        var mp = ReadMpPond(uid);
        UpdateEscortBattleTitlePools(hp, mp);
        var verb = kind == EscortRefillHp ? "补血" : "补魔";
        var nowPond = kind == EscortRefillHp ? hp : mp;
        SetEscortBattleNote(verb + "成功，" + CurrentEscortRefillLabel() + "现" + nowPond);
        Tip(verb + "成功");
        WriteLog("escort-battle refill ok kind=" + kind + " hp=" + hp + " mp=" + mp);

        if (_escortBattlePendingHp)
        {
            _escortBattlePendingHp = false;
            BeginEscortBattleRefill(uid, hp, EscortRefillHp);
            return;
        }

        if (_escortBattlePendingMp)
        {
            _escortBattlePendingMp = false;
            BeginEscortBattleRefill(uid, mp, EscortRefillMp);
            return;
        }

        _escortBattleBusy = false;
        _escortBattlePhase = 0;

        if (_escortBattleExtractAfterRefill)
        {
            _escortBattleExtractAfterRefill = false;
            BeginEscortBattleExtract();
            return;
        }

        if (_escortBattleResumeHang)
        {
            TrySendLocalAutoBattle("开始挂机");
        }

        _escortBattleResumeHang = false;
    }

    private static void FailEscortBattleRefill(string reason)
    {
        var uid = GetMainPlayerUidSafe();
        if (!string.IsNullOrEmpty(uid))
        {
            TryDismissItemBankAfterStore(uid);
        }

        var chainMp = _escortBattleRefillKind == EscortRefillHp && _escortBattlePendingMp;
        _escortBattlePendingHp = false;
        _escortBattlePendingMp = false;
        if (chainMp && !string.IsNullOrEmpty(uid))
        {
            WriteLog("escort-battle hp fail, continue mp: " + reason);
            Tip("补血失败：" + reason + "，继续补魔");
            BeginEscortBattleRefill(uid, ReadMpPond(uid), EscortRefillMp);
            return;
        }

        _escortBattleBusy = false;
        _escortBattlePhase = 0;
        _escortBattleResumeHang = false;
        SetEscortBattleNote("补池失败：" + reason);
        Tip("补池失败：" + reason);
        WriteLog("escort-battle fail " + reason);
        _escortBattleExtractAfterRefill = false;
    }

    private static void BeginEscortBattleExtract()
    {
        _escortBattleExtractAfterRefill = false;
        _escortBattleBusy = true;
        _escortBattlePhase = 10;
        _escortBattleWaitMs = NowMs();
        TrySendLocalAutoBattle("停止挂机");
        SetEscortBattleNote("满" + EscortBattleExtractEvery + "场，暂停提取采集…");
        Tip("护航战斗：满" + EscortBattleExtractEvery + "场，暂停提取采集");
        WriteLog("escort-battle extract start fights=" + _escortBattleFightCount);
    }

    private static void TickEscortBattleExtract(long now)
    {
        if (_escortBattlePhase == 10)
        {
            if (now - _escortBattleWaitMs < 400)
            {
                return;
            }

            if (!TryStartAreaExtractNow())
            {
                FinishEscortBattleExtract("提取入口失败，跳过");
                return;
            }

            _escortBattlePhase = 11;
            _escortBattleWaitMs = now;
            SetEscortBattleNote("正在遍历采集提取…");
            return;
        }

        if (_escortBattlePhase == 11)
        {
            var waited = now - _escortBattleWaitMs;
            if (waited > 90000)
            {
                FinishEscortBattleExtract("提取超时，继续战斗");
                return;
            }

            if (waited < 400)
            {
                return;
            }

            if (IsAreaExtractBusy())
            {
                SetEscortBattleNote("正在遍历采集提取… " + (waited / 1000) + "s");
                return;
            }

            FinishEscortBattleExtract("采集提取完成");
        }
    }

    private static void FinishEscortBattleExtract(string note)
    {
        _escortBattleBusy = false;
        _escortBattlePhase = 0;
        _escortBattleFightCount = 0;
        _escortBattleExtractAfterRefill = false;
        SetEscortBattleNote(note + "  采集0/" + EscortBattleExtractEvery);
        Tip(note);
        WriteLog("escort-battle extract done " + note);
        try
        {
            RefreshTitleFromFeature();
        }
        catch
        {
            // ignore
        }

        if (_escortBattleResumeHang)
        {
            TrySendLocalAutoBattle("开始挂机");
        }

        _escortBattleResumeHang = false;
    }

    private static bool TryStartAreaExtractNow()
    {
        try
        {
            var t = EnsureFeatureType("SeqChapterAreaExtract", "hotfixdata/SeqChapterAreaExtract.dll.bytes");
            var m = t?.GetMethod(
                "ExtractNowFromUi",
                BindingFlags.Public | BindingFlags.Static,
                null,
                Type.EmptyTypes,
                null);
            if (m == null)
            {
                WriteLog("escort-battle ExtractNowFromUi miss");
                return false;
            }

            m.Invoke(null, null);
            return true;
