        _escortBattleExtractAfterRefill = false;
        _escortBattlePendingHp = false;
        _escortBattlePendingMp = false;
        _escortBattleExitAtMs = 0;
        SetEscortBattleNote("已取消：" + reason);
        WriteLog("escort-battle abort " + reason);
