    {
        var changed = false;
        if (hp >= 0 && hp != _escortBattleTitleHp)
        {
            _escortBattleTitleHp = hp;
            changed = true;
        }

        if (mp >= 0 && mp != _escortBattleTitleMp)
        {
            _escortBattleTitleMp = mp;
            changed = true;
        }

        if (!changed && !_escortBattleHpOn)
        {
            return;
        }

        if (!changed)
        {
            return;
        }

        try
        {
            RefreshTitleFromFeature();
        }
        catch
        {
            // ignore
        }
    }

