    }

    private static void StartSuperAi()
    {
        if (!IsSuperAiModeAllowed(_battleMode))
        {
            Tip("AI战斗：请先到「战斗」页选常规");
            return;
        }

        _superAiActive = true;
        _superAiLastHintKey = "";
        _superAiLastSimLine = "已启动，等待战斗回合…";
        _superAiHintTurn = -1;
        ResetSuperAiBattleClassify();
        EnsureSuperAiDojoPriorityLoaded();
        EnsureSuperAiHintOverlay();
        RefreshSuperAiHintOverlay("等待进入战斗…");
        Tip("AI战斗已开启");
        WriteLog("SuperAI start(send) mode=" + _battleMode);
    }

    private static void StopSuperAi(string reason)
    {
        if (!_superAiActive)
        {
            return;
        }

        _superAiActive = false;
        _superAiLastSimLine = reason ?? "";
        _superAiUiPage = 0;
        _superAiDetailIndex = -1;
        _superAiUnits.Clear();
        _superAiPlannedCmds.Clear();
        _superAiLastHintKey = "";
        _superAiLastWindowTitleKey = "";
        ClearSuperAiVipFocusAnchor();
        ResetSuperAiBattleClassify();
        HideSuperAiHintOverlay();
        try { RefreshTitleFromFeature(); } catch { }
        WriteLog("SuperAI stop: " + reason);
        Tip("AI战斗已关闭");
    }

    private static void ResetSuperAiBattleClassify()
    {
        _superAiClassifiedBattleIndex = -1;
        _superAiIsBossBattle = false;
        _superAiIsHighPressure = false;
        _superAiSpecialRuleId = "";
        _superAiSpecialRuleTitle = "";
        _superAiFerniPhase = SuperAiFerniPhase.None;
        _superAiGoldSilverPhase = SuperAiGoldSilverPhase.None;
        _superAiWaitBattleIndex = -1;
        _superAiNextInfoProbeAtMs = 0;
        _superAiInfoProbeAttempt = 0;
        _superAiStartInfoReady = false;
        _superAiTakeoverFailed = false;
        _superAiPotionPlanBattle = -1;
        _superAiPotionPlanTurn = -1;
        _superAiPotionAssignByGiver.Clear();
        _superAiPotionPlanNote = "";
        _superAiEnemyRoleByIdx.Clear();
        _superAiStartEnemyNames.Clear();
        ClearSuperAiVipFocusAnchor();
    }

    /// <summary>首领战标题：普通「AI战斗」；特殊「AI战斗-{后缀}」；菲尔尼带阶段。</summary>
    private static string FormatSuperAiBattleTitle()
    {
        if (_superAiTakeoverFailed)
        {
            return "AI战斗 接管失败";
        }

        if (!_superAiStartInfoReady)
        {
            var n = Math.Min(_superAiInfoProbeAttempt + 1, SuperAiStartInfoMaxAttempts);
            return "AI战斗 等待开战信息(" + n + "/" + SuperAiStartInfoMaxAttempts + ")";
        }

        if (_superAiClassifiedBattleIndex < 0)
        {
            return "AI战斗 定档中";
        }

        if (!_superAiIsBossBattle)
        {
            return "AI战斗 非首领战·不接管";
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdFerni)
        {
            switch (ResolveSuperAiFerniPhase())
            {
                case SuperAiFerniPhase.Drain:
                    return "AI战斗-菲尔尼-第一阶段抽蓝";
                case SuperAiFerniPhase.Focus:
                    return "AI战斗-菲尔尼-第二阶段集火";
                case SuperAiFerniPhase.Cleanup:
                    return "AI战斗-菲尔尼-第三阶段收尾";
                default:
                    return "AI战斗-菲尔尼";
            }
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdGoldSilver)
        {
            switch (ResolveSuperAiGoldSilverPhase())
            {
                case SuperAiGoldSilverPhase.ClearAdds:
                    return "AI战斗-金银角-清杂";
                case SuperAiGoldSilverPhase.DuoHighestHp:
                    return "AI战斗-金银角-双王比血";
                default:
                    return "AI战斗-金银角";
            }
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdRepChallenge)
        {
            string focusKw;
            if (TryPeekSuperAiRepChallengeFocusKw(out focusKw) && !string.IsNullOrEmpty(focusKw))
            {
                return "AI战斗-声望挑战-" + focusKw;
            }

            return "AI战斗-声望挑战";
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdBullGhost)
        {
            int xingIdx;
            string xingName;
            string xingRole;
            if (TryFindSuperAiBullGhostXingXiong(out xingIdx, out xingName, out xingRole))
            {
                return "AI战斗-牛鬼-星雄";
            }

            return "AI战斗-回来报仇的牛鬼";
        }

        if (_superAiDojoMode)
        {
            string dojoKw;
            if (TryPeekSuperAiDojoPriorityKw(out dojoKw) && !string.IsNullOrEmpty(dojoKw))
            {
                return "AI战斗-百人-" + dojoKw;
            }

            return "AI战斗-百人";
        }

        if (_superAiSpecialRuleTitle.Length > 0)
        {
            return "AI战斗-" + _superAiSpecialRuleTitle;
        }

        return "AI战斗";
    }

    /// <summary>
    /// 记下集火单位，并清掉官方 <c>focusFireIndex</c>。
    /// 官方集火会在 VIP 列表之前把出手掐成单体攻击，治疗/气绝回复排不到。
    /// 目标改写在 <c>SendBattleCommond</c>，只动攻击类包。
    /// </summary>
    private static void SyncSuperAiVipFocusAnchor()
    {
        // 金银角 / 声望 / 牛鬼 / AI百人优先名单命中：强制写锚点；其它仍受「重写攻防序」约束
        int idx = -1;
        string name = "";
        string role = "";
        var dojoPriorityHit = false;
        if (_superAiDojoMode)
        {
            EnsureSuperAiDojoPriorityLoaded();
            dojoPriorityHit = TryFindSuperAiDojoPriorityEnemy(out idx, out name, out role);
        }

        var forceAnchor = _superAiSpecialRuleId == SuperAiSpecialIdGoldSilver
                          || _superAiSpecialRuleId == SuperAiSpecialIdRepChallenge
                          || _superAiSpecialRuleId == SuperAiSpecialIdBullGhost
                          || dojoPriorityHit;
        if (!_superAiIsBossBattle || (!_superAiRewriteAtkDef && !forceAnchor))
        {
            ClearSuperAiVipFocusAnchor();
            return;
        }

        if (!dojoPriorityHit)
        {
            if (!TryFindSuperAiPriorityEnemy(out idx, out name, out role) || idx < 0)
            {
                // 单位表瞬间是空的（切号/跳过动画）不要把已锁的集火清掉
                if (!SuperAiSnapHasLivingEnemy() && _superAiLastFocusAnchorIdx >= 0)
                {
                    return;
                }

                ClearSuperAiVipFocusAnchor();
                return;
            }
        }
        else if (idx < 0)
        {
            if (!SuperAiSnapHasLivingEnemy() && _superAiLastFocusAnchorIdx >= 0)
            {
                return;
            }

            ClearSuperAiVipFocusAnchor();
            return;
        }

        TrySetAiBattleTargetIndex(idx);
        // 不写官方集火，否则 PlayerFocusFireAttack 会跳过治疗/气绝回复。
        TrySetOfficialFocusFireIndex(-1);

        if (idx != _superAiLastFocusAnchorIdx
            || !string.Equals(_superAiLastFocusAnchorName, name ?? "", StringComparison.Ordinal))
        {
            _superAiLastFocusAnchorIdx = idx;
            _superAiLastFocusAnchorName = name ?? "";
            WriteLog("SuperAI focus target=" + idx + " [" + role + "] " + _superAiLastFocusAnchorName);
        }
        else
        {
            _superAiLastFocusAnchorIdx = idx;
            _superAiLastFocusAnchorName = name ?? "";
        }
    }

    private static void ClearSuperAiVipFocusAnchor()
    {
        if (_superAiLastFocusAnchorIdx == -1 && string.IsNullOrEmpty(_superAiLastFocusAnchorName))
        {
            TrySetAiBattleTargetIndex(-1);
            TrySetOfficialFocusFireIndex(-1);
            return;
        }

        TrySetAiBattleTargetIndex(-1);
        TrySetOfficialFocusFireIndex(-1);
        _superAiLastFocusAnchorIdx = -1;
        _superAiLastFocusAnchorName = "";
        WriteLog("SuperAI focus target cleared");
    }

    /// <summary>辅助面板锚点文案：优先敌人名。</summary>
    private static string FormatSuperAiFocusAnchorShort()
    {
        if (_superAiLastFocusAnchorIdx < 0)
        {
            return "无锚点";
        }

        var n = _superAiLastFocusAnchorName;
        if (string.IsNullOrEmpty(n))
        {
            return "锚点#" + _superAiLastFocusAnchorIdx;
        }

        return "锚点 " + n + "#" + _superAiLastFocusAnchorIdx;
    }

    /// <summary>写官方 VIP 集火下标；-1 清除。</summary>
    private static bool TrySetOfficialFocusFireIndex(int index)
    {
        try
        {
            var mgr = GetManagerInstance("BattleAutoSkillManager");
            if (mgr == null)
            {
                return false;
            }

            var cur = Convert.ToInt32(GetMember(mgr, "focusFireIndex") ?? -1);
            if (cur == index)
            {
                return true;
            }

            SetMember(mgr, "focusFireIndex", index);
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("TrySetOfficialFocusFireIndex EX: " + RootMessage(ex));
            return false;
        }
    }

    /// <summary>发包钩子用来认出正在 Tick 的那份助手，避免打到另一份已卸载的静态。</summary>
    public static bool SuperAiCommandHookLive()
    {
        // 发包钩子入口：AI 攻防序 或 单体变群体 任一开着都要进 Rewrite。
        return _superAiActive || _singleToAoeEnabled;
    }

    /// <summary>
    /// SendBattleCommond 入口改写：①单体变群体（战斗页开关，默开）；②AI 攻防序换锚点。
    /// </summary>
    public static string RewriteSuperAiBattleCommand(string cmd)
    {
        if (string.IsNullOrEmpty(cmd))
        {
            return cmd ?? "";
        }

        if (_superAiRewriteBusy)
        {
            return cmd;
        }

        if (!_singleToAoeEnabled && !_superAiActive)
        {
            return cmd;
        }

        _superAiRewriteBusy = true;
        try
        {
            var rewritten = cmd;
            if (_singleToAoeEnabled)
            {
                rewritten = TryRewriteSingleToAoeCommand(rewritten);
            }

            if (_superAiActive)
            {
                rewritten = TryRewriteSuperAiFocusRetarget(rewritten);
            }

            return rewritten;
        }
        catch (Exception ex)
        {
            WriteLog("RewriteSuperAiBattleCommand EX: " + RootMessage(ex));
            return cmd;
        }
        finally
        {
            _superAiRewriteBusy = false;
        }
    }

    /// <summary>白名单人物单体 → SIDE 群抬（40/41）。只改 S 包，不改宠物 W。名单见 single_to_aoe_skills.json。</summary>
    private static string TryRewriteSingleToAoeCommand(string cmd)
    {
        if (string.IsNullOrEmpty(cmd) || cmd.Length < 3)
        {
            return cmd;
        }

        EnsureSingleToAoeConfigLoaded(false);
        if (_singleToAoeAllyIds.Count == 0 && _singleToAoeEnemyPlayerIds.Count == 0)
        {
            return cmd;
        }

        if (!Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
        {
            return cmd;
        }

        var head = cmd[0];
        if (head != 'S' && head != 's')
        {
            return cmd;
        }

        var parts = cmd.Split('|');
        if (parts.Length != 4)
        {
            return cmd;
        }

        int oldTarget;
        if (!TryParseSuperAiHex(parts[parts.Length - 1], out oldTarget))
        {
            return cmd;
        }

        // 已是群抬/排/全体编码
        if (oldTarget == 40 || oldTarget == 41 || oldTarget == 42
            || (oldTarget >= 20 && oldTarget <= 39))
        {
            return cmd;
        }

        int skillId;
        int magicIndex;
        if (!TryParseSuperAiHex(parts[1], out magicIndex)
            || !TryResolvePlayerMagicSkillId(magicIndex, out skillId))
        {
            return cmd;
        }

        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var allyLowSide = playerIdx < 10;
        int sendTarget;
        string kind;
        if (SingleToAoeIdHit(_singleToAoeAllyIds, skillId, false))
        {
            sendTarget = allyLowSide ? 40 : 41;
            kind = "ally";
        }
        else if (SingleToAoeIdHit(_singleToAoeEnemyPlayerIds, skillId, false))
        {
            sendTarget = allyLowSide ? 41 : 40;
            kind = "enemyPlayer";
        }
        else
        {
            return cmd;
        }

        if (oldTarget == sendTarget)
        {
            return cmd;
        }

        parts[parts.Length - 1] = SuperAiHex(sendTarget);
        var rewritten = string.Join("|", parts);
        WriteLog("SingleToAoe " + kind + " id=" + skillId + " " + cmd + " -> " + rewritten);
        return rewritten;
    }

    private static bool TryResolvePlayerMagicSkillId(int magicIndex, out int skillId)
    {
        skillId = -1;
        try
        {
            var uid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
            if (string.IsNullOrEmpty(uid) || magicIndex < 0)
            {
                return false;
            }

            var getMag = FindType("PlayerDataHolder")?.GetMethod(
                "GetMagicDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var dict = getMag?.Invoke(null, new object[] { uid }) as IDictionary;
            if (dict == null)
            {
                return false;
            }

            object magic = null;
            if (dict.Contains(magicIndex))
            {
                magic = dict[magicIndex];
            }
            else
            {
                foreach (DictionaryEntry kv in dict)
                {
                    var m = kv.Value;
                    if (m == null)
                    {
                        continue;
                    }

                    var idx = Convert.ToInt32(GetMember(m, "index") ?? kv.Key ?? -1);
                    if (idx == magicIndex)
                    {
                        magic = m;
                        break;
                    }
                }
            }

            if (magic == null)
            {
                return false;
            }

            skillId = Convert.ToInt32(GetMember(magic, "skillId") ?? GetMember(magic, "SkillId") ?? -1);
            return skillId >= 0;
        }
        catch
        {
            return false;
        }
    }

    private static void EnsureSingleToAoeConfigLoaded(bool forceLog)
    {
        if (_singleToAoeConfigLoaded)
        {
            return;
        }

        _singleToAoeConfigLoaded = true;
        _singleToAoeAllyIds.Clear();
        _singleToAoeEnemyPlayerIds.Clear();
        try
        {
            var bytes = LoadBytes(SingleToAoeAsset);
            if (bytes == null || bytes.Length == 0)
            {
                foreach (var path in EnumerateHotfixAssetPaths(SingleToAoeFileName, SingleToAoeAsset))
                {
                    if (!File.Exists(path))
                    {
                        continue;
                    }

                    bytes = File.ReadAllBytes(path);
                    if (bytes != null && bytes.Length > 0)
                    {
                        WriteLog("SingleToAoe disk " + path);
                        break;
                    }
                }
            }

            if (bytes != null && bytes.Length > 0)
            {
                ParseSingleToAoeConfigJson(Encoding.UTF8.GetString(bytes));
            }

            if (_singleToAoeAllyIds.Count == 0)
            {
                for (var i = 0; i < SingleToAoeAllyDefaults.Length; i++)
                {
                    _singleToAoeAllyIds.Add(SingleToAoeAllyDefaults[i]);
                }
            }

            if (_singleToAoeEnemyPlayerIds.Count == 0)
            {
                for (var i = 0; i < SingleToAoeEnemyPlayerDefaults.Length; i++)
                {
                    _singleToAoeEnemyPlayerIds.Add(SingleToAoeEnemyPlayerDefaults[i]);
                }
            }

            if (forceLog || bytes != null)
            {
                WriteLog("SingleToAoe loaded ally=[" + string.Join(",", _singleToAoeAllyIds) + "]"
                         + " enemyPlayer=[" + string.Join(",", _singleToAoeEnemyPlayerIds) + "]");
            }
        }
        catch (Exception ex)
        {
            for (var i = 0; i < SingleToAoeAllyDefaults.Length; i++)
            {
                _singleToAoeAllyIds.Add(SingleToAoeAllyDefaults[i]);
            }

            for (var i = 0; i < SingleToAoeEnemyPlayerDefaults.Length; i++)
            {
                _singleToAoeEnemyPlayerIds.Add(SingleToAoeEnemyPlayerDefaults[i]);
            }

            WriteLog("SingleToAoe EX use defaults: " + RootMessage(ex));
        }
    }

    /// <summary>解析 ally_skill_ids / enemy_player_skill_ids 整型数组。</summary>
    private static void ParseSingleToAoeConfigJson(string text)
    {
        if (string.IsNullOrEmpty(text))
        {
            return;
        }

        FillIntIdSetFromJsonArray(text, "ally_skill_ids", _singleToAoeAllyIds);
        FillIntIdSetFromJsonArray(text, "enemy_player_skill_ids", _singleToAoeEnemyPlayerIds);
    }

    /// <summary>名单命中。宠技常是家族号，或 TechId（家族×100+等级），后者用 /100 再比一次。人物技能只比原号，避免 1001 被拆成 10。</summary>
    private static bool SingleToAoeIdHit(HashSet<int> set, int skillId, bool allowFamily)
    {
        if (set == null || skillId < 0)
        {
            return false;
        }

        if (set.Contains(skillId))
        {
            return true;
        }

        return allowFamily && skillId >= 100 && set.Contains(skillId / 100);
    }

    private static void FillIntIdSetFromJsonArray(string text, string key, HashSet<int> dest)
    {
        dest.Clear();
        var keyAt = text.IndexOf("\"" + key + "\"", StringComparison.OrdinalIgnoreCase);
        if (keyAt < 0)
        {
            return;
        }

        var bracket = text.IndexOf('[', keyAt);
        if (bracket < 0)
        {
            return;
        }

        var end = text.IndexOf(']', bracket);
        if (end < 0)
        {
            return;
        }

        var inner = text.Substring(bracket + 1, end - bracket - 1);
        var parts = inner.Split(',');
        for (var i = 0; i < parts.Length; i++)
        {
            var p = parts[i].Trim().Trim('"');
            int id;
            if (int.TryParse(p, NumberStyles.Integer, CultureInfo.InvariantCulture, out id) && id >= 0)
            {
                dest.Add(id);
            }
        }
    }

    /// <summary>
    /// AI 战斗：VIP/自动照常出手；攻击类包目标与集火同边则改成锚点。
    /// </summary>
    private static string TryRewriteSuperAiFocusRetarget(string cmd)
    {
        if (string.IsNullOrEmpty(cmd) || !_superAiActive)
        {
            return cmd;
        }

        if (!Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
        {
            return cmd;
        }

        CollectSuperAiRoundUnits();
        var battleIndex = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BattleIndex") ?? -1);
        if (battleIndex >= 0 && battleIndex != _superAiClassifiedBattleIndex)
        {
            ClassifySuperAiBattle(battleIndex);
        }
        else
        {
            ApplySuperAiEnemyRolesToUnits();
        }

        if (_superAiIsBossBattle)
        {
            SyncSuperAiVipFocusAnchor();
        }

        if (_superAiLastFocusAnchorIdx < 0 || !_superAiIsBossBattle)
        {
            return cmd;
        }

        var head = cmd[0];
        if (head == 'I' || head == 'i' || head == 'G' || head == 'g' || head == 'N' || head == 'n')
        {
            return cmd;
        }

        var parts = cmd.Split('|');
        if (parts.Length < 2)
        {
            return cmd;
        }

        var isPet = head == 'W' || head == 'w';
        var isSkill = head == 'S' || head == 's';
        var isHit = head == 'H' || head == 'h';
        if (!isPet && !isSkill && !isHit)
        {
            return cmd;
        }

        if (isHit && parts.Length != 2)
        {
            NoteSuperAiRetarget("bad-shape", cmd);
            return cmd;
        }

        if (isSkill && parts.Length != 4)
        {
            NoteSuperAiRetarget("bad-shape", cmd);
            return cmd;
        }

        if (isPet && string.Equals(parts.Length > 1 ? parts[1] : "", "FF", StringComparison.OrdinalIgnoreCase))
        {
            return cmd;
        }

        if (isPet && parts.Length != 3)
        {
            NoteSuperAiRetarget("bad-shape", cmd);
            return cmd;
        }

        var targetPos = isHit ? 1 : parts.Length - 1;
        int oldTarget;
        if (!TryParseSuperAiHex(parts[targetPos], out oldTarget))
        {
            NoteSuperAiRetarget("bad-target", cmd);
            return cmd;
        }

        // 群抬/排/全体编码不要改回单体锚点
        if (oldTarget == 40 || oldTarget == 41 || oldTarget == 42
            || (oldTarget >= 20 && oldTarget <= 39))
        {
            return cmd;
        }

        var focus = _superAiLastFocusAnchorIdx;
        if (oldTarget / 10 != focus / 10)
        {
            return cmd;
        }

        if (oldTarget == focus)
        {
            NoteSuperAiRetarget("already", cmd);
            return cmd;
        }

        parts[targetPos] = SuperAiHex(focus);
        var rewritten = string.Join("|", parts);
        WriteLog("SuperAI retarget " + cmd + " -> " + rewritten + " focus=" + focus);
        return rewritten;
    }

    private static void NoteSuperAiRetarget(string kind, string cmd)
    {
        var key = kind + "|" + cmd + "|" + _superAiLastFocusAnchorIdx;
        var now = Environment.TickCount;
        if (key == _superAiRetargetSeenKey && unchecked(now - _superAiRetargetSeenMs) < 8000)
        {
            return;
        }

        _superAiRetargetSeenKey = key;
        _superAiRetargetSeenMs = now;
        WriteLog("SuperAI retarget " + kind + " " + cmd + " focus=" + _superAiLastFocusAnchorIdx);
    }

    /// <summary>当前快照里还有活着的敌人。空表视为没扫到，不当成「目标已死」。</summary>
    private static bool SuperAiSnapHasLivingEnemy()
    {
        if (_superAiUnits.Count == 0)
        {
            return false;
        }

        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine && u.Hp > 0 && !u.Unable)
            {
                return true;
            }
        }

        return false;
    }

    private static bool TryParseSuperAiHex(string text, out int value)
    {
        return int.TryParse(text, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out value);
    }

    private static bool TrySetAiBattleTargetIndex(int index)
    {
        try
        {
            var field = FindAiBattleTargetIndexField();
            if (field == null)
            {
                return false;
            }

            var cur = Convert.ToInt32(field.GetValue(null) ?? -1);
            if (cur == index)
            {
                return true;
            }

            field.SetValue(null, index);
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("TrySetAiBattleTargetIndex EX: " + RootMessage(ex));
            return false;
        }
    }

    private static FieldInfo FindAiBattleTargetIndexField()
    {
        try
        {
            var probe = GetManagerInstance("BattleAutoSkillManager")
                        ?? GetManagerInstance("BattleManager");
            var asm = probe?.GetType().Assembly;
            if (asm == null)
            {
                return null;
            }

            var t = asm.GetType("SeqChapterAiBattleTarget", false, false);
            return t?.GetField("Index", BindingFlags.Public | BindingFlags.Static);
        }
        catch
        {
            return null;
        }
    }

    private static void TickSuperAi()
    {
        if (!_superAiActive)
        {
            return;
        }

        if (!IsSuperAiModeAllowed(_battleMode))
        {
            StopSuperAi("战斗模式非常规，已关闭AI战斗");
            return;
        }

        EnsureSuperAiHintOverlay();

        var inBattle = Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false);
        if (!inBattle)
        {
            _superAiLastHintKey = "";
            _superAiHintTurn = -1;
            if (_superAiClassifiedBattleIndex != -1 || _superAiWaitBattleIndex != -1)
            {
                ResetSuperAiBattleClassify();
            }

            ClearSuperAiVipFocusAnchor();
            RefreshSuperAiHintOverlay("等待进入战斗…");
            return;
        }

        var battleIndex = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BattleIndex") ?? -1);
        var now = NowMs();
        if (battleIndex != _superAiWaitBattleIndex)
        {
            _superAiWaitBattleIndex = battleIndex;
            _superAiLastHintKey = "";
            _superAiClassifiedBattleIndex = -1;
            _superAiStartInfoReady = false;
            _superAiTakeoverFailed = false;
            _superAiInfoProbeAttempt = 0;
            _superAiNextInfoProbeAtMs = now + SuperAiStartInfoProbeMs;
            WriteLog("SuperAI start-info probe battle=" + battleIndex
                     + " wait=" + SuperAiStartInfoProbeMs + "ms x" + SuperAiStartInfoMaxAttempts);
        }

        if (_superAiTakeoverFailed)
        {
            RefreshSuperAiHintOverlay("接管失败：开战信息未就绪（已试"
                                      + SuperAiStartInfoMaxAttempts + "次）");
            _superAiLastSimLine = "接管失败";
            return;
        }

        if (!_superAiStartInfoReady)
        {
            if (now < _superAiNextInfoProbeAtMs)
            {
                var nextAttempt = _superAiInfoProbeAttempt + 1;
                RefreshSuperAiHintOverlay("等待开战信息（" + nextAttempt + "/"
                                          + SuperAiStartInfoMaxAttempts + "）… "
                                          + FormatSuperAiWaitRemainSec(_superAiNextInfoProbeAtMs - now)
                                          + "s");
                return;
            }

            CollectSuperAiRoundUnits();
            _superAiInfoProbeAttempt++;
            if (SuperAiRoundStartInfoReady())
            {
                _superAiStartInfoReady = true;
                WriteLog("SuperAI start-info OK attempt=" + _superAiInfoProbeAttempt
                         + "/" + SuperAiStartInfoMaxAttempts
                         + " type=" + GetSuperAiBattleModeFlag()
                         + " enemies=" + CountSuperAiEnemies());
            }
            else if (_superAiInfoProbeAttempt >= SuperAiStartInfoMaxAttempts)
            {
                _superAiTakeoverFailed = true;
                WriteLog("SuperAI start-info FAIL after " + _superAiInfoProbeAttempt
                         + " attempts battle=" + battleIndex);
                Tip("AI接管失败：开战信息未就绪");
                RefreshSuperAiHintOverlay("接管失败：开战信息未就绪（已试"
                                          + SuperAiStartInfoMaxAttempts + "次）");
                _superAiLastSimLine = "接管失败";
                return;
            }
            else
            {
                _superAiNextInfoProbeAtMs = now + SuperAiStartInfoProbeMs;
                WriteLog("SuperAI start-info retry attempt=" + _superAiInfoProbeAttempt
                         + "/" + SuperAiStartInfoMaxAttempts);
                RefreshSuperAiHintOverlay("开战信息未齐，重试（"
                                          + (_superAiInfoProbeAttempt + 1) + "/"
                                          + SuperAiStartInfoMaxAttempts + "）… "
                                          + FormatSuperAiWaitRemainSec(SuperAiStartInfoProbeMs) + "s");
                return;
            }
        }

        // 百人道场官方会把自动战斗关掉，VIP 不出手，攻击包改目标也走不到
        if (_superAiDojoMode && _superAiIsBossBattle && !IsSuperAiAutoBattleOn()
            && now - _superAiDojoAutoEnsureMs >= 800)
        {
            _superAiDojoAutoEnsureMs = now;
            DispatchBattleAutoOperation(true);
            WriteLog("SuperAI dojo: auto was off, turn official auto on");
        }

        var turn = GetSuperAiBattleTurn();
        var acct = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
        var cmdRunning = false;
        try
        {
            var bm = GetManagerInstance("BattleManager");
            cmdRunning = bm != null && Convert.ToBoolean(GetMember(bm, "CmdRunningFlag") ?? false);
        }
        catch
        {
            // ignore
        }

        // 选指令阶段：每拍重采单位（死人换锚点）+ 定档 + 写集火锚点
        if (!cmdRunning)
        {
            CollectSuperAiRoundUnits();
            if (battleIndex != _superAiClassifiedBattleIndex)
            {
                ClassifySuperAiBattle(battleIndex);
            }
            else
            {
                ApplySuperAiEnemyRolesToUnits();
            }

            var prevFocusIdx = _superAiLastFocusAnchorIdx;
            var prevFocusName = _superAiLastFocusAnchorName ?? "";
            SyncSuperAiVipFocusAnchor();
            // 锚点因击杀切换时，同回合也要刷新辅助面板
            if (_superAiLastFocusAnchorIdx != prevFocusIdx
                || !string.Equals(_superAiLastFocusAnchorName, prevFocusName, StringComparison.Ordinal))
            {
                _superAiLastHintKey = "";
            }
        }

        // 按「战斗|回合|当前账号」刷新面板规划（强制出手由 AutoFight/DoVip 钩子代发）
        var key = battleIndex + "|" + turn + "|" + acct;
        if (cmdRunning)
        {
            return;
        }

        if (key == _superAiLastHintKey)
        {
            return;
        }

        FillSuperAiRoundSuggestions();
        _superAiLastHintKey = key;
        _superAiHintTurn = turn;
        var board = FormatSuperAiHintBoard(turn);
        if (!_superAiIsBossBattle)
        {
            _superAiLastSimLine = "非首领战 · 不接管";
        }
        else
        {
            var anchor = FormatSuperAiFocusAnchorShort();
            var handoff = FormatSuperAiHandoffShort();
            _superAiLastSimLine = FormatSuperAiBattleTitle() + " " + anchor + " · 第" + (turn + 1) + "回合 · " + handoff;
        }

        RefreshSuperAiHintOverlay(board);
        WriteLog("===== SuperAI turn=" + turn + " key=" + key
                 + " boss=" + _superAiIsBossBattle + " focus=" + _superAiLastFocusAnchorIdx
                 + " auto=" + IsSuperAiAutoBattleOn()
                 + " vipP=" + IsSuperAiVipAutoSwitchOn(acct, 0)
                 + " vipPet=" + IsSuperAiVipAutoSwitchOn(acct, 1)
                 + " spec=" + _superAiSpecialRuleId
                 + " type=" + GetSuperAiBattleModeFlag() + " =====");
        WriteLog(board);
        if (_tab == TabSuperAi && _visible && _superAiStatusText != null && !IsUnityNull(_superAiStatusText))
        {
            SetText(_superAiStatusText, FormatSuperAiStatus(), 13);
        }
    }

    private static int GetSuperAiBattleTurn()
    {
        try
        {
            var proc = TryGetBattleProcesser();
            return Convert.ToInt32(GetMember(proc, "m_BattleSvTurnIndex") ?? 0);
        }
        catch
        {
            return 0;
        }
    }

    private static void EnsureSuperAiHintOverlay()
    {
        try
        {
            if (_superAiHintCanvas != null && !IsUnityNull(_superAiHintCanvas))
            {
                SetGoActive(_superAiHintCanvas, true);
                LayoutSuperAiHintOverlay();
                return;
            }

            var rtType = RequireType("UnityEngine.RectTransform");
            var canvasType = RequireType("UnityEngine.Canvas");
            _superAiHintCanvas = CreateGoWithComponents(
                "SeqChapterAiHintOverlay",
                rtType,
                canvasType,
                FindType("UnityEngine.UI.CanvasScaler"));
            CallStatic(RequireType("UnityEngine.Object"), "DontDestroyOnLoad",
                new[] { RequireType("UnityEngine.Object") }, new[] { _superAiHintCanvas });

            var canvas = GetComp(_superAiHintCanvas, canvasType);
            SetProp(canvas, "renderMode", EnumValue("UnityEngine.RenderMode", "ScreenSpaceOverlay", 0));
            SetProp(canvas, "overrideSorting", true);
            SetProp(canvas, "sortingOrder", 32000);
            StretchFull(RequireRect(_superAiHintCanvas, "aiov"));

            var panel = CreateUiChild(_superAiHintCanvas, "Panel", rtType);
            var img = AddComp(panel, "UnityEngine.UI.Image");
            SetColor(img, 0.05f, 0.08f, 0.12f, 0.82f);
            try { SetProp(img, "raycastTarget", false); } catch { }

            var title = CreateUiChild(panel, "Title", rtType);
            var titleTx = AddText(title);
            _superAiHintTitleText = titleTx;
            try { SetProp(titleTx, "alignment", EnumValue("UnityEngine.TextAnchor", "MiddleLeft", 3)); } catch { }
            try { SetProp(titleTx, "raycastTarget", false); } catch { }

            var body = CreateUiChild(panel, "Body", rtType);
            _superAiHintText = AddText(body);
            try { SetProp(_superAiHintText, "alignment", EnumValue("UnityEngine.TextAnchor", "UpperLeft", 0)); } catch { }
            try { SetProp(_superAiHintText, "horizontalOverflow", EnumValue("UnityEngine.HorizontalWrapMode", "Wrap", 0)); } catch { }
            try { SetProp(_superAiHintText, "verticalOverflow", EnumValue("UnityEngine.VerticalWrapMode", "Overflow", 0)); } catch { }
            try { SetProp(_superAiHintText, "raycastTarget", false); } catch { }
            LayoutSuperAiHintOverlay();
            SetText(_superAiHintText, "等待进入战斗…", 12);
            RefreshSuperAiHintTitle();
        }
        catch (Exception ex)
        {
            WriteLog("EnsureSuperAiHintOverlay EX: " + RootMessage(ex));
        }
    }

    private static void LayoutSuperAiHintOverlay()
    {
        if (_superAiHintCanvas == null || IsUnityNull(_superAiHintCanvas))
        {
            return;
        }

        var panel = GetChild(_superAiHintCanvas, "Panel");
        if (panel == null)
        {
            return;
        }

        SetAnchoredTopLeft(RequireRect(panel, "aip"), 8f, -72f, 360f, 210f);
        var title = GetChild(panel, "Title");
        if (title != null)
        {
            SetAnchoredTopLeft(RequireRect(title, "ait"), 8f, -4f, 344f, 28f);
            _superAiHintTitleText = ResolveSuperAiHintTitleText(title);
            RefreshSuperAiHintTitle();
        }

        var body = GetChild(panel, "Body");
        if (body != null)
        {
            SetAnchoredTopLeft(RequireRect(body, "aib"), 8f, -34f, 344f, 168f);
        }
    }

    private static object ResolveSuperAiHintTitleText(object titleGo = null)
    {
        try
        {
            if (titleGo == null && _superAiHintCanvas != null && !IsUnityNull(_superAiHintCanvas))
            {
                var panel = GetChild(_superAiHintCanvas, "Panel");
                titleGo = panel != null ? GetChild(panel, "Title") : null;
            }

            if (titleGo == null || IsUnityNull(titleGo))
            {
                return _superAiHintTitleText;
            }

            var tx = GetComp(titleGo, FindType("UnityEngine.UI.Text"))
                     ?? GetComp(titleGo, FindType("TMPro.TextMeshProUGUI"));
            if (tx != null)
            {
                _superAiHintTitleText = tx;
                try { SetProp(tx, "horizontalOverflow", EnumValue("UnityEngine.HorizontalWrapMode", "Overflow", 1)); } catch { }
                try { SetProp(tx, "verticalOverflow", EnumValue("UnityEngine.VerticalWrapMode", "Overflow", 0)); } catch { }
                try { SetProp(tx, "resizeTextForBestFit", false); } catch { }
            }

            return _superAiHintTitleText;
        }
        catch
        {
            return _superAiHintTitleText;
        }
    }

    private static void RefreshSuperAiHintTitle()
    {
        var titleTx = ResolveSuperAiHintTitleText();
        if (titleTx == null || IsUnityNull(titleTx))
        {
            return;
        }

        string title;
        if (!_superAiActive)
        {
            title = "AI战斗";
        }
        else if (!Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
        {
            title = "AI战斗 等待战斗";
        }
        else
        {
            title = FormatSuperAiBattleTitle();
        }

        SetText(titleTx, title, 13);
        try { SetProp(titleTx, "color", MakeColor(1f, 0.92f, 0.45f, 1f)); } catch { }

        // 同步游戏窗口标题（CollectTitleSuffix 读 FormatSuperAiBattleTitle）
        if (_superAiActive && title != _superAiLastWindowTitleKey)
        {
            _superAiLastWindowTitleKey = title;
            try { RefreshTitleFromFeature(); } catch { }
        }
    }

    private static void HideSuperAiHintOverlay()
    {
        try
        {
            if (_superAiHintCanvas != null && !IsUnityNull(_superAiHintCanvas))
            {
                SetGoActive(_superAiHintCanvas, false);
            }
        }
        catch
        {
            // ignore
        }
    }

    private static void RefreshSuperAiHintOverlay(string body)
    {
        EnsureSuperAiHintOverlay();
        RefreshSuperAiHintTitle();
        if (_superAiHintText != null && !IsUnityNull(_superAiHintText))
        {
            SetText(_superAiHintText, body ?? "", 12);
        }
    }

    private static string FormatSuperAiHintBoard(int turn)
    {
        var sb = new StringBuilder();
        if (!_superAiIsBossBattle)
        {
            sb.Append("非首领战（battleModeFlag=").Append(GetSuperAiBattleModeFlag())
              .Append("/").Append(FormatSuperAiBattleType(GetSuperAiBattleModeFlag()))
              .Append("，非 BOSS/LASTBOSS）· 不接管");
            return sb.ToString();
        }

        sb.Append("第").Append(turn + 1).Append("回合 · ").Append(FormatSuperAiBattleTitle());
        sb.Append(" · ").Append(FormatSuperAiHandoffShort());
        sb.AppendLine();
        var focus = ResolveSuperAiFocusTier();
        sb.Append("本回合锁定：").Append(FormatSuperAiFocusTier(focus));
        if (_superAiLastFocusAnchorIdx >= 0)
        {
            sb.Append(" → ").Append(FormatSuperAiFocusAnchorShort());
        }

        sb.AppendLine();
        AppendSuperAiRoleSummary(sb);
        if (_superAiPlannedCmds.Count == 0)
        {
            sb.Append("（本回合无说明）");
            return sb.ToString();
        }

        for (var i = 0; i < _superAiPlannedCmds.Count; i++)
        {
            var c = _superAiPlannedCmds[i];
            var tag = c.Forced ? "[强制] " : "";
            if (!string.IsNullOrEmpty(c.Str))
            {
                sb.AppendLine(tag + c.Actor + "  " + c.Str + "  " + c.Label);
            }
            else
            {
                sb.AppendLine(tag + c.Actor + "  " + c.Label);
            }
        }

        return sb.ToString().TrimEnd();
    }

    private static void AppendSuperAiRoleSummary(StringBuilder sb)
    {
        var elite = 0;
        var boss = 0;
        var trash = 0;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Hp <= 0)
            {
                continue;
            }

            if (u.EnemyRole == SuperAiEnemyRole.Elite)
            {
                elite++;
            }
            else if (u.EnemyRole >= SuperAiEnemyRole.Boss1 && u.EnemyRole <= SuperAiEnemyRole.Boss4)
            {
                boss++;
            }
            else if (u.EnemyRole == SuperAiEnemyRole.Trash)
            {
                trash++;
            }
        }

        sb.Append("档位存活 精=").Append(elite).Append(" 首=").Append(boss)
          .Append(" 杂=").Append(trash).AppendLine();
    }

    private static void CollectSuperAiRoundUnits()
    {
        _superAiUnits.Clear();
        try
        {
            var container = FindType("BattleRoleContainer");
            var dic = container?.GetField("BattleRoleDic", BindingFlags.Public | BindingFlags.Static)
                      ?.GetValue(null) as IDictionary;
            if (dic == null)
            {
                return;
            }

            var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
            var allySide = playerIdx < 10;
            foreach (DictionaryEntry kv in dic)
            {
                var role = kv.Value;
                if (role == null)
                {
                    continue;
                }

                var idx = Convert.ToInt32(GetMember(role, "Index") ?? kv.Key ?? -1);
                var roleData = GetMember(role, "RoleData");
                var ch = roleData != null ? GetMember(roleData, "Char") : null;
                if (ch == null)
                {
                    continue;
                }

                var bc = Convert.ToInt64(GetMember(ch, "Bcflag") ?? 0);
                var hp = Convert.ToInt32(GetMember(ch, "Hp") ?? 0);
                var maxHp = Convert.ToInt32(GetMember(ch, "MaxHp") ?? 0);
                var snap = new SuperAiUnitSnap();
                snap.Idx = idx;
                snap.Mine = (allySide && idx < 10) || (!allySide && idx >= 10);
                snap.IsPlayer = (bc & 4L) != 0;
                snap.Name = Convert.ToString(GetMember(ch, "Name") ?? "") ?? "";
                snap.Level = Convert.ToInt32(GetMember(ch, "Level") ?? 0);
                snap.Hp = hp;
                snap.MaxHp = maxHp;
                snap.Mp = Convert.ToInt32(GetMember(ch, "Mp") ?? 0);
                snap.MaxMp = Convert.ToInt32(GetMember(ch, "MaxMp") ?? 0);
                snap.Bc = bc;
                snap.Status = FormatBcStatus(bc);
                snap.Unable = IsSuperAiUnable(bc, hp);
                snap.Suggest = "";
                snap.Uid = "";
                snap.JobName = "";
                snap.JobAncestry = "";
                snap.JobAncestryId = -1;
                snap.AiForceTakeover = false;
                snap.Rec = 0;
                snap.EnemyRole = SuperAiEnemyRole.None;
                snap.StartMaxHp = maxHp;

                if (snap.Mine)
                {
                    FillSuperAiAllyIdentity(ref snap);
                }

                _superAiUnits.Add(snap);
            }

            _superAiUnits.Sort((a, b) =>
            {
                if (a.Mine != b.Mine)
                {
                    return a.Mine ? -1 : 1;
                }

                if (a.IsPlayer != b.IsPlayer)
                {
                    return a.IsPlayer ? -1 : 1;
                }

                return a.Idx.CompareTo(b.Idx);
            });
        }
        catch (Exception ex)
        {
            WriteLog("CollectSuperAiRoundUnits EX: " + RootMessage(ex));
        }
    }

    private static bool IsSuperAiUnable(long bc, int hp)
    {
        if (hp <= 0)
        {
            return true;
        }

        return (bc & 2L) != 0 || (bc & 0x20L) != 0 || (bc & 0x40L) != 0;
    }

    private static void FillSuperAiAllyIdentity(ref SuperAiUnitSnap snap)
    {
        try
        {
            // 人宠同列 ±5（左右分布，不是一字排开）；偷袭前后排对调时不能假定 0~4=人
            var uidIdx = snap.IsPlayer
                ? snap.Idx
                : ResolveSuperAiPairedOwnerIndex(snap.Idx);
            var uid = FindUidByBattleIndex(uidIdx) ?? "";
            snap.Uid = uid;
            if (string.IsNullOrEmpty(uid))
            {
                return;
            }

            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { uid });
            if (player == null)
            {
                return;
            }

            snap.JobName = Convert.ToString(GetMember(player, "JobName") ?? "") ?? "";
            snap.JobAncestry = Convert.ToString(GetMember(player, "JobAncestryName") ?? "") ?? "";
            snap.JobAncestryId = Convert.ToInt32(GetMember(player, "JobAncestry") ?? -1);
            if (snap.IsPlayer)
            {
                snap.Rec = Convert.ToInt32(GetMember(player, "Recovery") ?? 0);
            }
            else
            {
                TryFillAllySystemDetail(ref snap, false, false, uid, snap.Idx);
            }
        }
        catch
        {
            // ignore
        }
    }

    /// <summary>
    /// 同列人宠：Index%5 相同且同侧 decade；宠的主人 Index 优先查 AccountIndexDic 有 uid 的那格。
    /// </summary>
    private static int ResolveSuperAiPairedOwnerIndex(int petOrPlayerIdx)
    {
        var side = (petOrPlayerIdx / 10) * 10;
        var col = petOrPlayerIdx % 5;
        var a = side + col;
        var b = side + col + 5;
        if (!string.IsNullOrEmpty(FindUidByBattleIndex(a)))
        {
            return a;
        }

        if (!string.IsNullOrEmpty(FindUidByBattleIndex(b)))
        {
            return b;
        }

        // 默认：后排人 / 前排宠
        return (petOrPlayerIdx % 10) >= 5 ? petOrPlayerIdx - 5 : petOrPlayerIdx + 5;
    }

    /// <summary>是否同侧同列（人↔宠配对）。</summary>
    private static bool IsSuperAiSameColumnPair(int a, int b)
    {
        if (a < 0 || b < 0 || a == b)
        {
            return false;
        }

        if ((a / 10) != (b / 10))
        {
            return false;
        }

        return (a % 5) == (b % 5);
    }

    private static bool IsSuperAiPriestJob(SuperAiUnitSnap u)
    {
        if (u.JobAncestryId == SuperAiJobPriest)
        {
            return true;
        }

        var a = u.JobAncestry ?? "";
        var j = u.JobName ?? "";
        return a.IndexOf("传教", StringComparison.Ordinal) >= 0
               || j.IndexOf("传教", StringComparison.Ordinal) >= 0;
    }

    private static bool IsSuperAiWizardJob(SuperAiUnitSnap u)
    {
        if (u.JobAncestryId == SuperAiJobWizard)
        {
            return true;
        }

        var a = u.JobAncestry ?? "";
        var j = u.JobName ?? "";
        return a.IndexOf("巫师", StringComparison.Ordinal) >= 0
               || j.IndexOf("巫师", StringComparison.Ordinal) >= 0;
    }

    private static bool IsSuperAiSorcererJob(SuperAiUnitSnap u)
    {
        if (u.JobAncestryId == SuperAiJobSorcerer)
        {
            return true;
        }

        var a = u.JobAncestry ?? "";
        var j = u.JobName ?? "";
        return a.IndexOf("咒术", StringComparison.Ordinal) >= 0
               || j.IndexOf("咒术", StringComparison.Ordinal) >= 0;
    }

    private static bool IsSuperAiPriestWizardSorcerer(SuperAiUnitSnap u)
    {
        return IsSuperAiPriestJob(u) || IsSuperAiWizardJob(u) || IsSuperAiSorcererJob(u);
    }

    private static void FillSuperAiRoundSuggestions()
    {
        FillSuperAiSendableCommands();
    }

    private static void AddSuperAiPlannedCmd(string actor, string str, string label, bool forced = false)
    {
        // 自动出手行允许 Str 为空，只展示说明
        if (!forced && string.IsNullOrEmpty(str) && string.IsNullOrEmpty(label))
        {
            return;
        }

        if (forced && string.IsNullOrEmpty(str))
        {
            return;
        }

        var cmd = new SuperAiPlannedCmd();
        cmd.Actor = actor ?? "";
        cmd.Str = str ?? "";
        cmd.Label = label ?? "";
        cmd.Forced = forced;
        _superAiPlannedCmds.Add(cmd);
    }

    /// <summary>
    /// 官方 AutoFight_PlayerAction / DoVipPlayerAutoFight 入口钩：需强制则代发并 return true。
    /// </summary>
    /// <summary>
    /// 官方 AutoFight_PlayerAction / DoVipPlayerAutoFight 入口钩：
    /// AI 开则先血瓶/菲尔尼等；再「攻击无效重写」（不依赖 AI 也能单独生效）。
    /// </summary>
    public static bool TrySuperAiPlayerAuto()
    {
        if (_superAiActive)
        {
            // 出手前再刷一次锚点，避免 Tick 与 VIP 竞态
            SyncSuperAiVipFocusAnchor();
            if (TrySuperAiHookPlayerForce("PlayerAuto"))
            {
                return true;
            }
        }

        return TryVipAtkInvalidRewriteHook(true, "PlayerAuto");
    }

    /// <summary>官方 AutoFight_PlayerAction2（无宠二动）入口钩。</summary>
    public static bool TrySuperAiPlayerAuto2()
    {
        if (_superAiActive)
        {
            SyncSuperAiVipFocusAnchor();
            if (TrySuperAiHookPlayerForce("PlayerAuto2"))
            {
                return true;
            }
        }

        return TryVipAtkInvalidRewriteHook(true, "PlayerAuto2");
    }

    /// <summary>
    /// 官方 AutoFight_PetAction / DoVipPetAutoFight 入口钩：
    /// AI 开则先战栗/集火；再攻击无效重写。
    /// </summary>
    public static bool TrySuperAiPetAuto()
    {
        if (_superAiActive)
        {
            SyncSuperAiVipFocusAnchor();
            try
            {
                if (EnsureSuperAiHookContext())
                {
                    SuperAiUnitSnap player;
                    SuperAiUnitSnap pet;
                    bool hasPlayer;
                    bool hasPet;
                    if (TryGetSuperAiSelfUnits(out player, out hasPlayer, out pet, out hasPet)
                        && hasPlayer && hasPet && !pet.Unable)
                    {
                        var ferniPhase = ResolveSuperAiFerniPhase();
                        _superAiFerniPhase = ferniPhase;

                        string forceStr = null;
                        string forceLabel = null;
                        int enemyIdx;
                        string enemyName;
                        string enemyRole;
                        var hasEnemy = TryFindSuperAiPriorityEnemy(
                            out enemyIdx, out enemyName, out enemyRole);

                        if (ferniPhase == SuperAiFerniPhase.Drain && hasEnemy)
                        {
                            int trembleSlot;
                            if (TryGetSuperAiPetSkillSlot(
                                    player.Uid, SuperAiSkillIdTremble, out trembleSlot)
                                && trembleSlot >= 0)
                            {
                                forceStr = "W|" + SuperAiHex(trembleSlot) + "|"
                                           + SuperAiHex(enemyIdx);
                                forceLabel = "战栗袭心→[" + enemyRole + "] "
                                             + enemyName + "#" + enemyIdx;
                            }
                        }

                        if (forceStr == null
                            && (ferniPhase == SuperAiFerniPhase.Focus
                                || ferniPhase == SuperAiFerniPhase.Cleanup)
                            && TryBuildSuperAiFerniPhaseAttackCmd(
                                player, true, ferniPhase, out forceStr, out forceLabel))
                        {
                            // 二/三阶段宠打菲尔尼或收尾士官长；人物走 VIP（攻防序只写锚点）
                        }

                        if (forceStr == null
                            && IsSuperAiQiankunPetMode()
                            && TryBuildSuperAiQiankunPetCmd(
                                player, out forceStr, out forceLabel))
                        {
                            // 金银角/声望/牛鬼：乾坤 → 四系基础魔 → 普攻
                        }

                        if (!string.IsNullOrEmpty(forceStr))
                        {
                            var bm = GetManagerInstance("BattleManager");
                            var uid = Convert.ToString(
                                GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
                            if (SendSuperAiBattleCmd(bm, uid, forceStr))
                            {
                                WriteLog("SuperAI HOOK pet " + forceStr + " · " + forceLabel);
                                return true;
                            }

                            WriteLog("SuperAI HOOK pet FAIL " + forceStr);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                WriteLog("TrySuperAiPetAuto EX: " + RootMessage(ex));
            }
        }

        return TryVipAtkInvalidRewriteHook(false, "PetAuto");
    }

    /// <summary>
    /// 攻击无效重写（独立于 AI）：VIP 开着且列表有 59 时，给无攻无 buff 友方强制套；
    /// 无人可套则 return false，其余 VIP 技能照常。
    /// AI 已开时不介入（牛鬼攻无走 PartyInvalid；百人/普通首领交给自动/VIP，避免巫师一直攻无）。
    /// </summary>
    private static bool TryVipAtkInvalidRewriteHook(bool forPlayer, string tag)
    {
        try
        {
            if (!_superAiVipType14Rewrite)
            {
                return false;
            }

            // AI 接管时：攻无只留给牛鬼特例；勿用 VIP 重写污染百人 A 瓶等逻辑
            if (_superAiActive)
            {
                return false;
            }

            if (!Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
            {
                return false;
            }

            CollectSuperAiRoundUnits();
            SuperAiUnitSnap player;
            SuperAiUnitSnap pet;
            bool hasPlayer;
            bool hasPet;
            if (!TryGetSuperAiSelfUnits(out player, out hasPlayer, out pet, out hasPet) || !hasPlayer)
            {
                return false;
            }

            if (forPlayer)
            {
                if (player.Unable)
                {
                    return false;
                }
            }
            else
            {
                if (!hasPet || pet.Unable)
                {
                    return false;
                }
            }

            string forceStr;
            string forceLabel;
            if (!TryBuildVipAtkInvalidCmd(player, forPlayer, out forceStr, out forceLabel))
            {
                return false;
            }

            var bm = GetManagerInstance("BattleManager");
            var uid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
            if (!SendSuperAiBattleCmd(bm, uid, forceStr))
            {
                WriteLog("VIP atkInvalid HOOK FAIL " + tag + " " + forceStr);
                return false;
            }

            WriteLog("VIP atkInvalid HOOK " + tag + " " + forceStr + " · " + forceLabel);
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("TryVipAtkInvalidRewriteHook EX " + tag + ": " + RootMessage(ex));
            return false;
        }
    }

    private static bool TrySuperAiHookPlayerForce(string tag)
    {
        try
        {
            if (!EnsureSuperAiHookContext())
            {
                return false;
            }

            SuperAiUnitSnap player;
            SuperAiUnitSnap pet;
            bool hasPlayer;
            bool hasPet;
            if (!TryGetSuperAiSelfUnits(out player, out hasPlayer, out pet, out hasPet) || !hasPlayer)
            {
                return false;
            }

            if (player.Unable)
            {
                return false;
            }

            var ferniPhase = ResolveSuperAiFerniPhase();
            _superAiFerniPhase = ferniPhase;
            EnsureSuperAiPotionPlan();

            // 传教只补血；非传教里最靠前的一人在还有人没挂上时放攻无/魔无，优先于血瓶。
            var forceStr = "";
            var forceLabel = "";
            _partyInvalidLiveSend = true;
            bool built;
            try
            {
                built = TryBuildSuperAiPriestHealPlayerCmd(player, out forceStr, out forceLabel)
                        || TryBuildSuperAiPartyInvalidPlayerCmd(player, out forceStr, out forceLabel)
                        || TryBuildSuperAiPotionCmd(player, hasPet, pet, out forceStr, out forceLabel)
                        || TryBuildSuperAiFerniDrainPlayerCmd(player, ferniPhase, out forceStr, out forceLabel)
                        || TryBuildSuperAiBullGhostPlayerCmd(player, out forceStr, out forceLabel)
                        || TryBuildSuperAiGoldSilverPlayerCmd(player, out forceStr, out forceLabel);
            }
            finally
            {
                _partyInvalidLiveSend = false;
            }

            if (!built)
            {
                return false;
            }

            var bm = GetManagerInstance("BattleManager");
            var uid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
            if (!SendSuperAiBattleCmd(bm, uid, forceStr))
            {
                WriteLog("SuperAI HOOK player FAIL " + tag + " " + forceStr);
                return false;
            }

            if (!string.IsNullOrEmpty(_partyInvalidArmedStr) && forceStr == _partyInvalidArmedStr)
            {
                _partyInvalidEmittedBattle = _partyInvalidClaimBattle;
                _partyInvalidEmittedTurn = _partyInvalidClaimTurn;
                _partyInvalidEmittedSkill = _partyInvalidClaimSkill;
                _partyInvalidArmedStr = "";
            }

            WriteLog("SuperAI HOOK player " + tag + " " + forceStr + " · " + forceLabel);
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("TrySuperAiHookPlayerForce EX " + tag + ": " + RootMessage(ex));
            return false;
        }
    }

    /// <summary>
    /// 钩子上下文：AI 开着、开战信息齐、本场是首领战。到号时若 Tick 还在等 1s，这里直接定档。
    /// </summary>
    private static bool EnsureSuperAiHookContext()
    {
        if (!_superAiActive || _superAiTakeoverFailed)
        {
            return false;
        }

        if (!Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
        {
            return false;
        }

        var battleIndex = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BattleIndex") ?? -1);
        if (battleIndex < 0)
        {
            return false;
        }

        if (battleIndex != _superAiClassifiedBattleIndex || !_superAiStartInfoReady)
        {
            CollectSuperAiRoundUnits();
            if (!SuperAiRoundStartInfoReady())
            {
                return false;
            }

            _superAiStartInfoReady = true;
            _superAiWaitBattleIndex = battleIndex;
            ClassifySuperAiBattle(battleIndex);
            WriteLog("SuperAI HOOK classify battle=" + battleIndex
                     + " boss=" + _superAiIsBossBattle + " spec=" + _superAiSpecialRuleId);
        }
        else
        {
            CollectSuperAiRoundUnits();
            ApplySuperAiEnemyRolesToUnits();
        }

        if (!_superAiIsBossBattle)
        {
            return false;
        }

        SyncSuperAiVipFocusAnchor();
        return true;
    }

    private static bool IsSuperAiAutoBattleOn()
    {
        try
        {
            var bm = GetManagerInstance("BattleManager");
            return bm != null && Convert.ToBoolean(GetMember(bm, "IsAutoBattle") ?? false);
        }
        catch
        {
            return false;
        }
    }

    /// <summary>
    /// hotfix Tip 钩：PVP 拦截提示且开关开时，改为切换官方自动战斗并吞掉提示。
    /// </summary>
    public static bool TryHandlePvpAutoBlockedTip()
    {
        if (!AllowPvpAutoBattle)
        {
            return false;
        }

        try
        {
            var on = !IsSuperAiAutoBattleOn();
            _pvpAutoHold = on;
            if (IsInBattleNow())
            {
                DispatchBattleAutoOperation(on);
            }
            else
            {
                var bm = GetManagerInstance("BattleManager");
                if (bm != null)
                {
                    SetMember(bm, "IsAutoBattle", on);
                }
            }

            WriteLog("PvpAutoBlockedTip handled allow=true -> IsAutoBattle=" + on);
            Tip(on ? "PVP自动战斗已开启" : "PVP自动战斗已关闭");
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("TryHandlePvpAutoBlockedTip EX: " + RootMessage(ex));
            return false;
        }
    }

    /// <summary>供 IL / 外部查询：是否允许 PVP 自动。</summary>
    public static bool IsPvpAutoAllowed()
    {
        return AllowPvpAutoBattle;
    }

    private static void TickPvpAutoHold()
    {
        if (!AllowPvpAutoBattle || !_pvpAutoHold)
        {
            return;
        }

        if (!IsInBattleNow())
        {
            return;
        }

        if (GetBattleModeFlagInt() != 2)
        {
            return;
        }

        if (IsSuperAiAutoBattleOn())
        {
            return;
        }

        var now = NowMs();
        if (now - _lastPvpAutoHoldMs < 400)
        {
            return;
        }

        _lastPvpAutoHoldMs = now;
        DispatchBattleAutoOperation(true);
        WriteLog("PvpAutoHold: re-enable after official force-off");
    }

    /// <summary>
    /// 若官方自动战斗关着则打开。战斗外只写 IsAutoBattle（勿 Dispatch，场外 AutoFight 会立刻清掉）。
    /// </summary>
    private static void EnsureOfficialAutoBattleOn(string reason, string openedTip = null)
    {
        try
        {
            var bm = GetManagerInstance("BattleManager");
            if (bm == null)
            {
                return;
            }

            if (Convert.ToBoolean(GetMember(bm, "IsAutoBattle") ?? false))
            {
                return;
            }

            if (IsInBattleNow())
            {
                DispatchBattleAutoOperation(true);
            }
            else
            {
                SetMember(bm, "IsAutoBattle", true);
            }

            WriteLog("EnsureOfficialAutoBattleOn: " + reason);
            Tip(string.IsNullOrEmpty(openedTip) ? "护航战斗：已打开自动战斗" : openedTip);
        }
        catch (Exception ex)
        {
            WriteLog("EnsureOfficialAutoBattleOn EX: " + RootMessage(ex));
        }
    }

    private static int GetBattleModeFlagInt()
    {
        try
        {
            var flag = GetStaticMember("BattleDataHolder", "battleModeFlag");
            if (flag == null)
            {
                return 0;
            }

            return Convert.ToInt32(flag);
        }
        catch
        {
            return 0;
        }
    }

    private static void DispatchBattleAutoOperation(bool enable)
    {
        try
        {
            var bm = GetManagerInstance("BattleManager");
            if (bm == null)
            {
                return;
            }

            var onEvent = GetMember(bm, "OnEvent");
            if (onEvent == null)
            {
                SetMember(bm, "IsAutoBattle", enable);
                return;
            }

            MethodInfo dispatch = null;
            foreach (var m in onEvent.GetType().GetMethods(
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
            {
                if (m.Name != "Dispatch")
                {
                    continue;
                }

                var ps = m.GetParameters();
                if (ps.Length == 2)
                {
                    dispatch = m;
                    break;
                }
            }

            if (dispatch == null)
            {
                SetMember(bm, "IsAutoBattle", enable);
                return;
            }

            var evt = EnumValue("BATTLE_TYPE_EVENT", "AUTO_OPERATION", 16);
            dispatch.Invoke(onEvent, new object[] { evt, enable });
        }
        catch (Exception ex)
        {
            WriteLog("DispatchBattleAutoOperation EX: " + RootMessage(ex));
            try
            {
                var bm = GetManagerInstance("BattleManager");
                if (bm != null)
                {
                    SetMember(bm, "IsAutoBattle", enable);
                }
            }
            catch
            {
                // ignore
            }
        }
    }

    /// <summary>VIP 自动技开关：kind 0=人物 1=宠（GetAutoSkillSwitch==1）。</summary>
    private static bool IsSuperAiVipAutoSwitchOn(string uid, int kind)
    {
        if (string.IsNullOrEmpty(uid))
        {
            return false;
        }

        try
        {
            var mgr = GetManagerInstance("BattleAutoSkillManager");
            if (mgr == null)
            {
                return false;
            }

            MethodInfo method = null;
            foreach (var m in mgr.GetType().GetMethods(
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
            {
                if (m.Name != "GetAutoSkillSwitch" || m.GetParameters().Length != 2)
                {
                    continue;
                }

                method = m;
                break;
            }

            if (method == null)
            {
                return false;
            }

            return Convert.ToInt32(method.Invoke(mgr, new object[] { uid, kind }) ?? 0) == 1;
        }
        catch
        {
            return false;
        }
    }

    private static string FormatSuperAiHandoffShort()
    {
        if (!IsSuperAiAutoBattleOn())
        {
            return "未开自动·不代发";
        }

        var uid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
        if (IsSuperAiVipAutoSwitchOn(uid, 0) || IsSuperAiVipAutoSwitchOn(uid, 1))
        {
            return "VIP自动出手";
        }

        return "普通自动出手";
    }

    private static bool SendSuperAiBattleCmd(object battleMgr, string uid, string cmd)
    {
        if (battleMgr == null || string.IsNullOrEmpty(cmd))
        {
            return false;
        }

        try
        {
            if (cmd.Length >= 2 && (cmd[0] == 'S' || cmd[0] == 's') && cmd[1] == '|')
            {
                SetStaticMember("BattleDataHolder", "skillUsed", true);
                try
                {
                    var pam = GetMember(battleMgr, "PlayerActionMagics") as IDictionary;
                    if (pam != null && !string.IsNullOrEmpty(uid))
                    {
                        pam[uid] = true;
                    }
                }
                catch
                {
                    // ignore
                }
            }

            var send = battleMgr.GetType().GetMethod(
                "SendBattleCommond",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                null,
                new[] { typeof(string) },
                null);
            if (send == null)
            {
                return false;
            }

            send.Invoke(battleMgr, new object[] { cmd });
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("SendSuperAiBattleCmd EX: " + RootMessage(ex));
            return false;
        }
    }

    private static string SuperAiHex(int n)
    {
        return n.ToString("X");
    }

    /// <summary>
    /// 本客户端（CurrentAccount 人物+宠）规划可实际 SendBattleCommond 的包。
    /// 敌方/队友/发不出的动作一律不写。
    /// </summary>
    /// <summary>
    /// 是否接管：看官方战斗类型 <c>battleModeFlag</c> 是否为 BOSS_BATTLE / LASTBOSS_BATTLE。
    /// 场内分档仍按 MaxHp：&lt;3000 杂兵；最高=首领1；其余 ≥1W 或 ≥首领1×60%→首领2–4；其余≥3000=精英。
    /// 特殊 AI：仅用开场敌名关键字，每个关键字须匹配不同单位。
    /// </summary>
    private static void ClassifySuperAiBattle(int battleIndex)
    {
        _superAiEnemyRoleByIdx.Clear();
        _superAiStartEnemyNames.Clear();
        _superAiIsBossBattle = false;
        _superAiIsHighPressure = false;
        _superAiSpecialRuleId = "";
        _superAiSpecialRuleTitle = "";
        _superAiFerniPhase = SuperAiFerniPhase.None;
        _superAiGoldSilverPhase = SuperAiGoldSilverPhase.None;
        _superAiClassifiedBattleIndex = battleIndex;

        var battleType = GetSuperAiBattleModeFlag();
        _superAiIsBossBattle = IsSuperAiBossBattleType(battleType);

        var enemies = new List<SuperAiUnitSnap>();
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine)
            {
                continue;
            }

            enemies.Add(u);
            if (!string.IsNullOrEmpty(u.Name))
            {
                _superAiStartEnemyNames.Add(u.Name);
            }
        }

        if (enemies.Count == 0)
        {
            WriteLog("SuperAI classify battle=" + battleIndex
                     + " type=" + battleType + " empty-enemy bossType=" + _superAiIsBossBattle);
            ApplySuperAiEnemyRolesToUnits();
            return;
        }

        enemies.Sort((a, b) =>
        {
            var c = b.MaxHp.CompareTo(a.MaxHp);
            return c != 0 ? c : a.Idx.CompareTo(b.Idx);
        });

        // 特殊规则必须在「非首领提前 return」之前匹配；命中则强制接管（牛鬼等可能不是 BOSS_BATTLE 类型）
        TryMatchSuperAiSpecialRule();
        if (!_superAiIsBossBattle && _superAiSpecialRuleId.Length > 0)
        {
            _superAiIsBossBattle = true;
            WriteLog("SuperAI special forces takeover id=" + _superAiSpecialRuleId
                     + " type=" + battleType + "(" + FormatSuperAiBattleType(battleType) + ")");
        }

        if (!_superAiIsBossBattle)
        {
            for (var i = 0; i < enemies.Count; i++)
            {
                _superAiEnemyRoleByIdx[enemies[i].Idx] = SuperAiEnemyRole.Trash;
            }

            WriteLog("SuperAI classify battle=" + battleIndex
                     + " NOT-boss type=" + battleType + " (" + FormatSuperAiBattleType(battleType) + ")"
                     + " maxHp=" + enemies[0].MaxHp);
            ApplySuperAiEnemyRolesToUnits();
            return;
        }

        // 首领战 / 特殊强制接管：场内按 MaxHp 定档（高压仍仅特殊 AI 另开）
        _superAiIsHighPressure = false;
        var boss1 = enemies[0];
        _superAiEnemyRoleByIdx[boss1.Idx] = SuperAiEnemyRole.Boss1;
        var used = new HashSet<int> { boss1.Idx };
        var ratioCut = (int)Math.Ceiling(boss1.MaxHp * SuperAiBossHpRatioOfBoss1);

        var bossCandidates = new List<SuperAiUnitSnap>();
        for (var i = 0; i < enemies.Count; i++)
        {
            var e = enemies[i];
            if (used.Contains(e.Idx))
            {
                continue;
            }

            if (e.MaxHp >= SuperAiBossHpFloor || e.MaxHp >= ratioCut)
            {
                bossCandidates.Add(e);
            }
        }

        bossCandidates.Sort((a, b) =>
        {
            var c = b.MaxHp.CompareTo(a.MaxHp);
            return c != 0 ? c : a.Idx.CompareTo(b.Idx);
        });

        var bossRoles = new[]
        {
            SuperAiEnemyRole.Boss2, SuperAiEnemyRole.Boss3, SuperAiEnemyRole.Boss4
        };
        for (var i = 0; i < bossCandidates.Count && i < bossRoles.Length; i++)
        {
            _superAiEnemyRoleByIdx[bossCandidates[i].Idx] = bossRoles[i];
            used.Add(bossCandidates[i].Idx);
        }

        for (var i = 0; i < enemies.Count; i++)
        {
            var e = enemies[i];
            if (used.Contains(e.Idx))
            {
                continue;
            }

            _superAiEnemyRoleByIdx[e.Idx] = e.MaxHp >= SuperAiTrashMaxHp
                ? SuperAiEnemyRole.Elite
                : SuperAiEnemyRole.Trash;
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdFerni)
        {
            _superAiIsHighPressure = true;
        }

        ApplySuperAiEnemyRolesToUnits();

        var sb = new StringBuilder();
        sb.Append("SuperAI classify battle=").Append(battleIndex)
          .Append(" type=").Append(battleType).Append("(").Append(FormatSuperAiBattleType(battleType)).Append(")")
          .Append(" boss1Hp=").Append(boss1.MaxHp)
          .Append(" ratioCut=").Append(ratioCut)
          .Append(" spec=").Append(_superAiSpecialRuleId.Length > 0 ? _superAiSpecialRuleId : "-");
        WriteLog(sb.ToString());
        for (var i = 0; i < enemies.Count; i++)
        {
            SuperAiEnemyRole role;
            _superAiEnemyRoleByIdx.TryGetValue(enemies[i].Idx, out role);
            WriteLog("  #" + enemies[i].Idx + " " + enemies[i].Name
                     + " maxHp=" + enemies[i].MaxHp + " → " + FormatSuperAiEnemyRole(role));
        }
    }

