    private static string FormatSuperAiWaitRemainSec(long remainMs)
    {
        if (remainMs < 0)
        {
            remainMs = 0;
        }

        return ((remainMs + 99) / 100 / 10.0).ToString("0.0");
    }

    private static int CountSuperAiEnemies()
    {
        var n = 0;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            if (!_superAiUnits[i].Mine)
            {
                n++;
            }
        }

        return n;
    }

    /// <summary>
    /// 开战信息就绪：有敌方、敌名齐、MaxHp 已刷出（定档/特殊 AI/战斗类型共用这一套）。
    /// </summary>
    private static bool SuperAiRoundStartInfoReady()
    {
        var enemies = 0;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine)
            {
                continue;
            }

            enemies++;
            if (string.IsNullOrEmpty(u.Name) || u.MaxHp <= 0)
            {
                return false;
            }
        }

        return enemies > 0;
    }

    /// <summary>官方 BATTLE_TYPE：BOSS_BATTLE=5 / LASTBOSS_BATTLE=6 → 接管。</summary>
    private static bool IsSuperAiBossBattleType(int battleType)
    {
        return battleType == BattleTypeBoss || battleType == BattleTypeLastBoss;
    }

    private static string FormatSuperAiBattleType(int battleType)
    {
        switch (battleType)
        {
            case 0: return "NONE";
            case 1: return "P_vs_E";
            case 2: return "P_vs_P";
            case 3: return "WATCH";
            case 4: return "ANCHORAGE";
            case BattleTypeBoss: return "BOSS_BATTLE";
            case BattleTypeLastBoss: return "LASTBOSS_BATTLE";
            case 7: return "DP_BATTLE";
            case 8: return "PVP_WATCH";
            case 9: return "REPLAY_BATTLE";
            default: return "type" + battleType;
        }
    }

    private static void ApplySuperAiEnemyRolesToUnits()
    {
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine)
            {
                u.EnemyRole = SuperAiEnemyRole.None;
            }
            else
            {
                SuperAiEnemyRole role;
                u.EnemyRole = _superAiEnemyRoleByIdx.TryGetValue(u.Idx, out role)
                    ? role
                    : SuperAiEnemyRole.Trash;
                if (u.StartMaxHp <= 0)
                {
                    u.StartMaxHp = u.MaxHp;
                }
            }

            _superAiUnits[i] = u;
        }
    }

    private static void TryMatchSuperAiSpecialRule()
    {
        _superAiSpecialRuleId = "";
        _superAiSpecialRuleTitle = "";
        for (var r = 0; r < SuperAiSpecialRules.Length; r++)
        {
            var rule = SuperAiSpecialRules[r];
            if (rule.Keywords == null || rule.Keywords.Length == 0)
            {
                continue;
            }

            if (!MatchSuperAiStartKeywords(rule.Keywords))
            {
                continue;
            }

            _superAiSpecialRuleId = rule.Id ?? "";
            _superAiSpecialRuleTitle = rule.Title ?? rule.Id ?? "";
            WriteLog("SuperAI special match id=" + _superAiSpecialRuleId
                     + " title=" + _superAiSpecialRuleTitle);
            return;
        }
    }

    /// <summary>每个关键字必须命中不同开场敌名（含「杀熊者热砂」单名不能满足「杀熊者」+「热砂」）。</summary>
    private static bool MatchSuperAiStartKeywords(string[] keywords)
    {
        if (keywords == null || keywords.Length == 0 || _superAiStartEnemyNames.Count == 0)
        {
            return false;
        }

        var used = new bool[_superAiStartEnemyNames.Count];
        for (var k = 0; k < keywords.Length; k++)
        {
            var kw = keywords[k];
            if (string.IsNullOrEmpty(kw))
            {
                return false;
            }

            var hit = false;
            for (var i = 0; i < _superAiStartEnemyNames.Count; i++)
            {
                if (used[i])
                {
                    continue;
                }

                var name = _superAiStartEnemyNames[i];
                if (name != null && name.IndexOf(kw, StringComparison.Ordinal) >= 0)
                {
                    used[i] = true;
                    hit = true;
                    break;
                }
            }

            if (!hit)
            {
                return false;
            }
        }

        return true;
    }

    private static string FormatSuperAiEnemyRole(SuperAiEnemyRole role)
    {
        switch (role)
        {
            case SuperAiEnemyRole.Trash: return "杂兵";
            case SuperAiEnemyRole.Elite: return "精英";
            case SuperAiEnemyRole.Boss1: return "首领1";
            case SuperAiEnemyRole.Boss2: return "首领2";
            case SuperAiEnemyRole.Boss3: return "首领3";
            case SuperAiEnemyRole.Boss4: return "首领4";
            default: return "-";
        }
    }

    /// <summary>
    /// 档内站位序：前排再后排，同排上→下（站位图上=左视觉一侧）。
    /// 敌方在 10–19 时序：18,16,15,17,19 再 13,11,10,12,14；我方在对面则减 10。
    /// </summary>
    private static int SuperAiEliteScanRank(int battleIdx, bool enemyHighSide)
    {
        var local = enemyHighSide ? battleIdx - 10 : battleIdx;
        // 上→下 前排
        switch (local)
        {
            case 8: return 0;
            case 6: return 1;
            case 5: return 2;
            case 7: return 3;
            case 9: return 4;
            case 3: return 5;
            case 1: return 6;
            case 0: return 7;
            case 2: return 8;
            case 4: return 9;
            default: return 100 + battleIdx;
        }
    }

    /// <summary>
    /// 本回合锁定的攻击档。
    /// 默认：杂兵→精英→首领。杀熊者模式：首领→杂兵→精英（先 Boss 再打小的）。
    /// </summary>
    private enum SuperAiFocusTier : byte
    {
        None = 0,
        Trash = 1,
        Elite = 2,
        Boss = 3
    }

    private static SuperAiFocusTier ResolveSuperAiFocusTier()
    {
        var hasTrash = false;
        var hasElite = false;
        var hasBoss = false;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0)
            {
                continue;
            }

            if (u.EnemyRole == SuperAiEnemyRole.Trash)
            {
                hasTrash = true;
            }
            else if (u.EnemyRole == SuperAiEnemyRole.Elite)
            {
                hasElite = true;
            }
            else if (u.EnemyRole >= SuperAiEnemyRole.Boss1 && u.EnemyRole <= SuperAiEnemyRole.Boss4)
            {
                hasBoss = true;
            }
        }

        // 杀熊者：先集火 Boss，再打小的
        if (_superAiSpecialRuleId == SuperAiSpecialIdKillbear)
        {
            if (hasBoss)
            {
                return SuperAiFocusTier.Boss;
            }

            if (hasTrash)
            {
                return SuperAiFocusTier.Trash;
            }

            if (hasElite)
            {
                return SuperAiFocusTier.Elite;
            }

            return SuperAiFocusTier.None;
        }

        if (hasTrash)
        {
            return SuperAiFocusTier.Trash;
        }

        if (hasElite)
        {
            return SuperAiFocusTier.Elite;
        }

        if (hasBoss)
        {
            return SuperAiFocusTier.Boss;
        }

        return SuperAiFocusTier.None;
    }

    private static string FormatSuperAiFocusTier(SuperAiFocusTier tier)
    {
        switch (tier)
        {
            case SuperAiFocusTier.Trash: return "杂兵";
            case SuperAiFocusTier.Elite: return "精英";
            case SuperAiFocusTier.Boss: return "首领";
            default: return "-";
        }
    }

    private static bool SuperAiRoleInFocusTier(SuperAiEnemyRole role, SuperAiFocusTier tier)
    {
        switch (tier)
        {
            case SuperAiFocusTier.Trash:
                return role == SuperAiEnemyRole.Trash;
            case SuperAiFocusTier.Elite:
                return role == SuperAiEnemyRole.Elite;
            case SuperAiFocusTier.Boss:
                return role >= SuperAiEnemyRole.Boss1 && role <= SuperAiEnemyRole.Boss4;
            default:
                return false;
        }
    }

    /// <summary>档内优先级：越小越先。杂兵/精英按站位；首领按 1→2→3→4。</summary>
    private static int SuperAiTargetPriorityInTier(SuperAiUnitSnap u, bool enemyHighSide, SuperAiFocusTier tier)
    {
        if (!SuperAiRoleInFocusTier(u.EnemyRole, tier))
        {
            return int.MaxValue;
        }

        if (tier == SuperAiFocusTier.Boss)
        {
            switch (u.EnemyRole)
            {
                case SuperAiEnemyRole.Boss1: return 0;
                case SuperAiEnemyRole.Boss2: return 1;
                case SuperAiEnemyRole.Boss3: return 2;
                case SuperAiEnemyRole.Boss4: return 3;
                default: return 9;
            }
        }

        return SuperAiEliteScanRank(u.Idx, enemyHighSide);
    }

    private static void FillSuperAiSendableCommands()
    {
        _superAiPlannedCmds.Clear();
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            u.Suggest = "";
            _superAiUnits[i] = u;
        }

        if (!_superAiIsBossBattle)
        {
            return;
        }

        SuperAiUnitSnap player;
        SuperAiUnitSnap pet;
        bool hasPlayer;
        bool hasPet;
        if (!TryGetSuperAiSelfUnits(out player, out hasPlayer, out pet, out hasPet) || !hasPlayer)
        {
            return;
        }

        var ferniPhase = ResolveSuperAiFerniPhase();
        _superAiFerniPhase = ferniPhase;

        int enemyIdx;
        string enemyName;
        string enemyRole;
        var hasEnemy = TryFindSuperAiPriorityEnemy(out enemyIdx, out enemyName, out enemyRole);
        EnsureSuperAiPotionPlan();
        var potBagCount = ScanSuperAiHpPotions(player.Uid).Count;
        AddSuperAiPlannedCmd("信息", "",
            "背包血瓶=" + potBagCount
            + " · 攻防序=" + (_superAiRewriteAtkDef ? "开" : "关")
            + " · 攻无重写=" + (_superAiVipType14Rewrite ? "开(自己→己宠→友→友宠)" : "关")
            + (hasEnemy && _superAiRewriteAtkDef
                ? (" · 锚点[" + enemyRole + "] " + enemyName + "#" + enemyIdx)
                : " · 无锚点")
            + " · " + FormatSuperAiHandoffShort()
            + (_superAiPotionPlanNote.Length > 0 ? "\n" + _superAiPotionPlanNote : ""),
            false);

        var playerActor = "人 " + (player.Name ?? "?");
        if (player.Unable)
        {
            AddSuperAiPlannedCmd(playerActor, "", "无法行动·交给自动", false);
            player.Suggest = "auto";
        }
        else
        {
            string forceStr;
            string forceLabel;
            if (TryBuildSuperAiPriestHealPlayerCmd(player, out forceStr, out forceLabel))
            {
                AddSuperAiPlannedCmd(playerActor, forceStr, "强制·" + forceLabel, true);
                player.Suggest = forceStr;
            }
            else if (TryBuildSuperAiPartyInvalidPlayerCmd(player, out forceStr, out forceLabel))
            {
                AddSuperAiPlannedCmd(playerActor, forceStr, "强制·" + forceLabel, true);
                player.Suggest = forceStr;
            }
            else if (TryBuildSuperAiPotionCmd(player, hasPet, pet, out forceStr, out forceLabel))
            {
                AddSuperAiPlannedCmd(playerActor, forceStr, "强制·" + forceLabel, true);
                player.Suggest = forceStr;
            }
            else if (TryBuildSuperAiFerniDrainPlayerCmd(player, ferniPhase, out forceStr, out forceLabel))
            {
                AddSuperAiPlannedCmd(playerActor, forceStr, "强制·" + forceLabel, true);
                player.Suggest = forceStr;
            }
            else if (TryBuildSuperAiBullGhostPlayerCmd(player, out forceStr, out forceLabel))
            {
                AddSuperAiPlannedCmd(playerActor, forceStr, "强制·" + forceLabel, true);
                player.Suggest = forceStr;
            }
            else if (TryBuildSuperAiGoldSilverPlayerCmd(player, out forceStr, out forceLabel))
            {
                AddSuperAiPlannedCmd(playerActor, forceStr, "强制·" + forceLabel, true);
                player.Suggest = forceStr;
            }
            // AI 开着时不做 VIP 攻无重写（避免百人巫师一直攻无；牛鬼走 PartyInvalid）
            else
            {
                var handoff = ferniPhase != SuperAiFerniPhase.None
                    ? "VIP/自动出手"
                    : "自动出手";
                AddSuperAiPlannedCmd(playerActor, "",
                    handoff + (hasEnemy ? (" →#" + enemyIdx) : ""),
                    false);
                player.Suggest = "auto";
            }
        }

        WriteBackSuperAiUnit(player);

        if (!hasPet)
        {
            return;
        }

        var petActor = "宠 " + (pet.Name ?? "?");
        if (pet.Unable)
        {
            AddSuperAiPlannedCmd(petActor, "", "无法行动·交给自动", false);
            pet.Suggest = "auto";
        }
        else
        {
            string petForce = null;
            string petLabel = null;
            int trembleSlot;
            if (ferniPhase == SuperAiFerniPhase.Drain
                && hasEnemy
                && TryGetSuperAiPetSkillSlot(player.Uid, SuperAiSkillIdTremble, out trembleSlot)
                && trembleSlot >= 0)
            {
                petForce = "W|" + SuperAiHex(trembleSlot) + "|" + SuperAiHex(enemyIdx);
                AddSuperAiPlannedCmd(petActor, petForce,
                    "强制·战栗袭心→[" + enemyRole + "] " + enemyName + "#" + enemyIdx,
                    true);
                pet.Suggest = petForce;
            }
            else if ((ferniPhase == SuperAiFerniPhase.Focus || ferniPhase == SuperAiFerniPhase.Cleanup)
                     && TryBuildSuperAiFerniPhaseAttackCmd(player, true, ferniPhase, out petForce, out petLabel))
            {
                AddSuperAiPlannedCmd(petActor, petForce, "强制·" + petLabel, true);
                pet.Suggest = petForce;
            }
            else if (IsSuperAiQiankunPetMode()
                     && TryBuildSuperAiQiankunPetCmd(player, out petForce, out petLabel))
            {
                AddSuperAiPlannedCmd(petActor, petForce, "强制·" + petLabel, true);
                pet.Suggest = petForce;
            }
            else
            {
                AddSuperAiPlannedCmd(petActor, "",
                    ferniPhase == SuperAiFerniPhase.Drain
                        ? ("自动出手（无战栗）" + (hasEnemy ? (" →#" + enemyIdx) : ""))
                        : ("自动出手" + (hasEnemy ? (" →#" + enemyIdx) : "")),
                    false);
                pet.Suggest = "auto";
            }
        }

        WriteBackSuperAiUnit(pet);
    }

    private static void WriteBackSuperAiUnit(SuperAiUnitSnap snap)
    {
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            if (_superAiUnits[i].Idx == snap.Idx)
            {
                _superAiUnits[i] = snap;
                return;
            }
        }
    }

    private static bool TryGetSuperAiSelfUnits(
        out SuperAiUnitSnap player, out bool hasPlayer,
        out SuperAiUnitSnap pet, out bool hasPet)
    {
        player = default(SuperAiUnitSnap);
        pet = default(SuperAiUnitSnap);
        hasPlayer = false;
        hasPet = false;
        var uid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount") ?? "") ?? "";
        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);

        // 1) 优先 battlePlayerIndex（官方「自己」）
        if (playerIdx >= 0)
        {
            for (var i = 0; i < _superAiUnits.Count; i++)
            {
                var u = _superAiUnits[i];
                if (u.Idx == playerIdx && u.IsPlayer)
                {
                    player = u;
                    hasPlayer = true;
                    break;
                }
            }
        }

        // 2) CurrentAccount uid 校验/回退（防 Index 与账号错位时「自己」指到队友）
        if (uid.Length > 0)
        {
            if (hasPlayer
                && !string.IsNullOrEmpty(player.Uid)
                && !string.Equals(player.Uid, uid, StringComparison.Ordinal))
            {
                WriteLog("SuperAI self mismatch idx#" + player.Idx
                         + " uid=" + TailUid(player.Uid) + " acct=" + TailUid(uid)
                         + " → resolve by uid");
                hasPlayer = false;
            }

            if (!hasPlayer)
            {
                for (var i = 0; i < _superAiUnits.Count; i++)
                {
                    var u = _superAiUnits[i];
                    if (u.IsPlayer && string.Equals(u.Uid, uid, StringComparison.Ordinal))
                    {
                        player = u;
                        hasPlayer = true;
                        playerIdx = u.Idx;
                        break;
                    }
                }
            }
        }

        if (!hasPlayer)
        {
            return false;
        }

        // 己宠：同侧同列（Index%5），左右竖列配对，不是 Abs==5 的一字假设之外再校验 IsPlayer
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.IsPlayer || !u.Mine)
            {
                continue;
            }

            if (!IsSuperAiSameColumnPair(player.Idx, u.Idx))
            {
                continue;
            }

            // 优先 uid 同号；否则同列第一只宠
            if (!string.IsNullOrEmpty(uid)
                && !string.IsNullOrEmpty(u.Uid)
                && string.Equals(u.Uid, uid, StringComparison.Ordinal))
            {
                pet = u;
                hasPet = true;
                break;
            }

            if (!hasPet)
            {
                pet = u;
                hasPet = true;
            }
        }

        return true;
    }

    private static bool TryFindSuperAiPriorityEnemy(out int idx, out string name, out string roleLabel)
    {
        idx = -1;
        name = "";
        roleLabel = "";

        // AI百人：优先名单只改锚点（仍交给 VIP 出手）
        if (_superAiDojoMode)
        {
            EnsureSuperAiDojoPriorityLoaded();
            if (TryFindSuperAiDojoPriorityEnemy(out idx, out name, out roleLabel))
            {
                return true;
            }
        }

        var ferniPhase = ResolveSuperAiFerniPhase();
        _superAiFerniPhase = ferniPhase;
        if (ferniPhase != SuperAiFerniPhase.None)
        {
            return TryFindSuperAiFerniPhaseEnemy(ferniPhase, out idx, out name, out roleLabel);
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdGoldSilver)
        {
            return TryFindSuperAiGoldSilverEnemy(out idx, out name, out roleLabel);
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdRepChallenge)
        {
            return TryFindSuperAiRepChallengeEnemy(out idx, out name, out roleLabel);
        }

        if (_superAiSpecialRuleId == SuperAiSpecialIdBullGhost
            && TryFindSuperAiBullGhostXingXiong(out idx, out name, out roleLabel))
        {
            return true;
        }

        var focus = ResolveSuperAiFocusTier();
        if (focus == SuperAiFocusTier.None)
        {
            return false;
        }

        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var enemyHighSide = playerIdx < 10;
        var bestPri = int.MaxValue;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0)
            {
                continue;
            }

            var pri = SuperAiTargetPriorityInTier(u, enemyHighSide, focus);
            if (pri >= int.MaxValue)
            {
                continue;
            }

            if (pri < bestPri || (pri == bestPri && (idx < 0 || u.Idx < idx)))
            {
                bestPri = pri;
                idx = u.Idx;
                name = u.Name ?? "?";
                roleLabel = FormatSuperAiEnemyRole(u.EnemyRole);
            }
        }

        return idx >= 0;
    }

    /// <summary>声望挑战：按固定集火序取当前应打的存活敌人。</summary>
    private static bool TryFindSuperAiRepChallengeEnemy(out int idx, out string name, out string roleLabel)
    {
        idx = -1;
        name = "";
        roleLabel = "";
        if (_superAiSpecialRuleId != SuperAiSpecialIdRepChallenge || !_superAiIsBossBattle)
        {
            return false;
        }

        string kw;
        if (!TryPeekSuperAiRepChallengeFocusKw(out kw) || string.IsNullOrEmpty(kw))
        {
            return false;
        }

        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var enemyHighSide = playerIdx < 10;
        var bestPri = int.MaxValue;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0 || !SuperAiUnitNameHas(u, kw))
            {
                continue;
            }

            var sidePri = SuperAiEliteScanRank(u.Idx, enemyHighSide);
            if (sidePri < bestPri || (sidePri == bestPri && (idx < 0 || u.Idx < idx)))
            {
                bestPri = sidePri;
                idx = u.Idx;
                name = u.Name ?? "?";
                roleLabel = "声望-" + kw;
            }
        }

        return idx >= 0;
    }

    /// <summary>返回集火序中第一个仍有存活单位的关键字。</summary>
    private static bool TryPeekSuperAiRepChallengeFocusKw(out string kw)
    {
        kw = "";
        if (_superAiSpecialRuleId != SuperAiSpecialIdRepChallenge)
        {
            return false;
        }

        for (var k = 0; k < SuperAiRepChallengeFocusOrder.Length; k++)
        {
            var cand = SuperAiRepChallengeFocusOrder[k];
            for (var i = 0; i < _superAiUnits.Count; i++)
            {
                var u = _superAiUnits[i];
                if (u.Mine || u.Unable || u.Hp <= 0)
                {
                    continue;
                }

                if (SuperAiUnitNameHas(u, cand))
                {
                    kw = cand;
                    return true;
                }
            }
        }

        return false;
    }

    /// <summary>金银角阶段：仍有非双王杂兵 → 清杂；否则双王比血。</summary>
    private static SuperAiGoldSilverPhase ResolveSuperAiGoldSilverPhase()
    {
        if (_superAiSpecialRuleId != SuperAiSpecialIdGoldSilver || !_superAiIsBossBattle)
        {
            return SuperAiGoldSilverPhase.None;
        }

        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0)
            {
                continue;
            }

            if (!IsSuperAiGoldOrSilverKing(u))
            {
                return SuperAiGoldSilverPhase.ClearAdds;
            }
        }

        return SuperAiGoldSilverPhase.DuoHighestHp;
    }

    private static bool IsSuperAiGoldOrSilverKing(SuperAiUnitSnap u)
    {
        return SuperAiUnitNameHas(u, SuperAiEnemyNameGoldKing)
               || SuperAiUnitNameHas(u, SuperAiEnemyNameSilverKing);
    }

    /// <summary>牛鬼：先集火名含「星雄」的存活敌人；没有则交给普通首领锚点。</summary>
    private static bool TryFindSuperAiBullGhostXingXiong(out int idx, out string name, out string roleLabel)
    {
        idx = -1;
        name = "";
        roleLabel = "";
        if (_superAiSpecialRuleId != SuperAiSpecialIdBullGhost || !_superAiIsBossBattle)
        {
            return false;
        }

        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var enemyHighSide = playerIdx < 10;
        var bestPri = int.MaxValue;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0 || !SuperAiUnitNameHas(u, SuperAiEnemyNameXingXiong))
            {
                continue;
            }

            var sidePri = SuperAiEliteScanRank(u.Idx, enemyHighSide);
            if (sidePri < bestPri || (sidePri == bestPri && (idx < 0 || u.Idx < idx)))
            {
                bestPri = sidePri;
                idx = u.Idx;
                name = u.Name ?? "?";
                roleLabel = "星雄";
            }
        }

        return idx >= 0;
    }

    /// <summary>
    /// 金银角目标：先集火非金/银角杂兵（站位序）；杂兵清完后打双王中当前血更高者。
    /// </summary>
    private static bool TryFindSuperAiGoldSilverEnemy(out int idx, out string name, out string roleLabel)
    {
        idx = -1;
        name = "";
        roleLabel = "";
        var phase = ResolveSuperAiGoldSilverPhase();
        _superAiGoldSilverPhase = phase;
        if (phase == SuperAiGoldSilverPhase.None)
        {
            return false;
        }

        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var enemyHighSide = playerIdx < 10;

        if (phase == SuperAiGoldSilverPhase.ClearAdds)
        {
            var bestPri = int.MaxValue;
            for (var i = 0; i < _superAiUnits.Count; i++)
            {
                var u = _superAiUnits[i];
                if (u.Mine || u.Unable || u.Hp <= 0 || IsSuperAiGoldOrSilverKing(u))
                {
                    continue;
                }

                var sidePri = SuperAiEliteScanRank(u.Idx, enemyHighSide);
                if (sidePri < bestPri || (sidePri == bestPri && (idx < 0 || u.Idx < idx)))
                {
                    bestPri = sidePri;
                    idx = u.Idx;
                    name = u.Name ?? "?";
                    roleLabel = "金银角清杂";
                }
            }

            return idx >= 0;
        }

        // 双王比血：取活着的金/银角中 Hp 更高；并列取 MaxHp 更高，再 Index
        var bestHp = -1;
        var bestMax = -1;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0 || !IsSuperAiGoldOrSilverKing(u))
            {
                continue;
            }

            if (u.Hp > bestHp
                || (u.Hp == bestHp && u.MaxHp > bestMax)
                || (u.Hp == bestHp && u.MaxHp == bestMax && (idx < 0 || u.Idx < idx)))
            {
                bestHp = u.Hp;
                bestMax = u.MaxHp;
                idx = u.Idx;
                name = u.Name ?? "?";
                roleLabel = SuperAiUnitNameHas(u, SuperAiEnemyNameGoldKing) ? "金角比血" : "银角比血";
            }
        }

        return idx >= 0;
    }

    private static SuperAiFerniPhase ResolveSuperAiFerniPhase()
    {
        if (_superAiSpecialRuleId != SuperAiSpecialIdFerni || !_superAiIsBossBattle)
        {
            return SuperAiFerniPhase.None;
        }

        // 一阶段：仍有活着且蓝≥70 的士官长，且场上至少有一只宠会战栗（否则抽不了蓝，直接跳二阶段）
        if (SuperAiAnySergeant(u => u.Hp > 0 && !u.Unable && u.Mp >= SuperAiFerniDrainMpThreshold)
            && SuperAiTeamHasTremble())
        {
            return SuperAiFerniPhase.Drain;
        }

        // 二阶段：菲尔尼仍存活（含：有士官长高蓝但全队无战栗 → 无法抽蓝，直接集火）
        int ferniIdx;
        string ferniName;
        if (TryFindSuperAiNamedEnemy(SuperAiEnemyNameFerni, out ferniIdx, out ferniName))
        {
            return SuperAiFerniPhase.Focus;
        }

        // 三阶段：收尾击杀剩余士官长
        return SuperAiFerniPhase.Cleanup;
    }

    /// <summary>场上是否有会战栗的出战宠（人物死了但宠仍在也算）。</summary>
    private static bool SuperAiTeamHasTremble()
    {
        var seen = new HashSet<string>();
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine || u.Hp <= 0)
            {
                continue;
            }

            var uid = u.Uid;
            if (string.IsNullOrEmpty(uid))
            {
                continue;
            }

            if (!seen.Add(uid))
            {
                continue;
            }

            int slot;
            if (TryGetSuperAiPetSkillSlot(uid, SuperAiSkillIdTremble, out slot) && slot >= 0)
            {
                return true;
            }
        }

        WriteLog("SuperAI Ferni: team has no tremble → skip drain phase");
        return false;
    }

    private static bool TryFindSuperAiFerniPhaseEnemy(
        SuperAiFerniPhase phase, out int idx, out string name, out string roleLabel)
    {
        idx = -1;
        name = "";
        roleLabel = "";
        switch (phase)
        {
            case SuperAiFerniPhase.Drain:
                if (TryFindSuperAiSergeant(true, out idx, out name))
                {
                    roleLabel = "士官长抽蓝";
                    return true;
                }

                return false;
            case SuperAiFerniPhase.Focus:
                if (TryFindSuperAiNamedEnemy(SuperAiEnemyNameFerni, out idx, out name))
                {
                    roleLabel = "菲尔尼";
                    return true;
                }

                return false;
            case SuperAiFerniPhase.Cleanup:
                if (TryFindSuperAiSergeant(false, out idx, out name))
                {
                    roleLabel = "士官长收尾";
                    return true;
                }

                return false;
            default:
                return false;
        }
    }

    private static bool SuperAiUnitNameHas(SuperAiUnitSnap u, string keyword)
    {
        return !string.IsNullOrEmpty(keyword)
               && u.Name != null
               && u.Name.IndexOf(keyword, StringComparison.Ordinal) >= 0;
    }

    /// <summary>AI百人优先名单：按配置顺序取第一个场上存活且名含关键词的敌人。</summary>
    private static bool TryFindSuperAiDojoPriorityEnemy(out int idx, out string name, out string roleLabel)
    {
        idx = -1;
        name = "";
        roleLabel = "";
        if (!_superAiDojoMode || _superAiDojoPriorityKeywords == null || _superAiDojoPriorityKeywords.Length == 0)
        {
            return false;
        }

        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var enemyHighSide = playerIdx < 10;
        for (var k = 0; k < _superAiDojoPriorityKeywords.Length; k++)
        {
            var kw = _superAiDojoPriorityKeywords[k];
            if (string.IsNullOrEmpty(kw))
            {
                continue;
            }

            var bestRank = int.MaxValue;
            var bestIdx = -1;
            string bestName = null;
            for (var i = 0; i < _superAiUnits.Count; i++)
            {
                var u = _superAiUnits[i];
                if (u.Mine || u.Unable || u.Hp <= 0 || !SuperAiUnitNameHas(u, kw))
                {
                    continue;
                }

                var rank = SuperAiEliteScanRank(u.Idx, enemyHighSide);
                if (rank < bestRank || (rank == bestRank && (bestIdx < 0 || u.Idx < bestIdx)))
                {
                    bestRank = rank;
                    bestIdx = u.Idx;
                    bestName = u.Name ?? kw;
                }
            }

            if (bestIdx >= 0)
            {
                idx = bestIdx;
                name = bestName ?? kw;
                roleLabel = "百人优先-" + kw;
                return true;
            }
        }

        return false;
    }

    /// <summary>当前应优先的百人关键词（仅窥探，不写锚点）。</summary>
    private static bool TryPeekSuperAiDojoPriorityKw(out string keyword)
    {
        keyword = "";
        int idx;
        string name;
        string role;
        if (!TryFindSuperAiDojoPriorityEnemy(out idx, out name, out role))
        {
            return false;
        }

        if (!string.IsNullOrEmpty(role) && role.StartsWith("百人优先-", StringComparison.Ordinal))
        {
            keyword = role.Substring("百人优先-".Length);
            return keyword.Length > 0;
        }

        keyword = name ?? "";
        return keyword.Length > 0;
    }

    private static void EnsureSuperAiDojoPriorityLoaded()
    {
        if (_superAiDojoPriorityLoaded)
        {
            return;
        }

        _superAiDojoPriorityLoaded = true;
        try
        {
            var bytes = LoadBytes(SuperAiDojoPriorityAsset);
            if (bytes == null || bytes.Length == 0)
            {
                foreach (var path in EnumerateHotfixAssetPaths(
                             SuperAiDojoPriorityFileName, SuperAiDojoPriorityAsset))
                {
                    if (!File.Exists(path))
                    {
                        continue;
                    }

                    bytes = File.ReadAllBytes(path);
                    if (bytes != null && bytes.Length > 0)
                    {
                        WriteLog("SuperAI dojoPriority disk " + path);
                        break;
                    }
                }
            }

            if (bytes == null || bytes.Length == 0)
            {
                _superAiDojoPriorityKeywords = SuperAiDojoPriorityDefaults;
                WriteLog("SuperAI dojoPriority=defaults (no config)");
                return;
            }

            var text = Encoding.UTF8.GetString(bytes);
            var list = ParseSuperAiDojoPriorityJson(text);
            if (list != null && list.Length > 0)
            {
                _superAiDojoPriorityKeywords = list;
                WriteLog("SuperAI dojoPriority loaded n=" + list.Length
                         + " [" + string.Join(",", list) + "]");
            }
            else
            {
                _superAiDojoPriorityKeywords = SuperAiDojoPriorityDefaults;
                WriteLog("SuperAI dojoPriority=defaults (parse empty)");
            }
        }
        catch (Exception ex)
        {
            _superAiDojoPriorityKeywords = SuperAiDojoPriorityDefaults;
            WriteLog("SuperAI dojoPriority EX: " + RootMessage(ex));
        }
    }

    /// <summary>解析 {"priority":["盖美拉",...]}；失败返回 null。</summary>
    private static string[] ParseSuperAiDojoPriorityJson(string text)
    {
        if (string.IsNullOrEmpty(text))
        {
            return null;
        }

        var key = "\"priority\"";
        var keyAt = text.IndexOf(key, StringComparison.OrdinalIgnoreCase);
        if (keyAt < 0)
        {
            return null;
        }

        var bracket = text.IndexOf('[', keyAt);
        if (bracket < 0)
        {
            return null;
        }

        var end = text.IndexOf(']', bracket + 1);
        if (end < 0)
        {
            return null;
        }

        var inner = text.Substring(bracket + 1, end - bracket - 1);
        var items = new List<string>();
        var i = 0;
        while (i < inner.Length)
        {
            var q1 = inner.IndexOf('"', i);
            if (q1 < 0)
            {
                break;
            }

            var q2 = inner.IndexOf('"', q1 + 1);
            if (q2 < 0)
            {
                break;
            }

            var s = inner.Substring(q1 + 1, q2 - q1 - 1).Trim();
            if (s.Length > 0)
            {
                items.Add(s);
            }

            i = q2 + 1;
        }

        return items.Count > 0 ? items.ToArray() : null;
    }

    private static bool SuperAiAnySergeant(Func<SuperAiUnitSnap, bool> pred)
    {
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || !SuperAiUnitNameHas(u, SuperAiEnemyNameSergeant))
            {
                continue;
            }

            if (pred(u))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>找士官长：drainMpOnly=true 时仅蓝≥70（绝对值）；按站位扫描序依次。</summary>
    private static bool TryFindSuperAiSergeant(bool drainMpOnly, out int idx, out string name)
    {
        idx = -1;
        name = "";
        var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
        var enemyHighSide = playerIdx < 10;
        var bestPri = int.MaxValue;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Mine || u.Unable || u.Hp <= 0
                || !SuperAiUnitNameHas(u, SuperAiEnemyNameSergeant))
            {
                continue;
            }

            if (drainMpOnly && u.Mp < SuperAiFerniDrainMpThreshold)
            {
                continue;
            }

            var pri = SuperAiEliteScanRank(u.Idx, enemyHighSide);
            if (pri > bestPri || (pri == bestPri && idx >= 0 && u.Idx >= idx))
            {
                continue;
            }

            bestPri = pri;
            idx = u.Idx;
            name = u.Name ?? "";
        }

        return idx >= 0;
    }

