            }

            bestPri = pri;
            idx = u.Idx;
            name = u.Name ?? "";
        }

        return idx >= 0;
    }

    private static bool IsSuperAiQiankunPetMode()
    {
        return _superAiSpecialRuleId == SuperAiSpecialIdGoldSilver
               || _superAiSpecialRuleId == SuperAiSpecialIdRepChallenge
               || _superAiSpecialRuleId == SuperAiSpecialIdBullGhost;
