    /// <summary>一阶段人物：骑士之誉 → 按技 Target 选友/己或抽蓝士官长。</summary>
    private static bool TryBuildSuperAiKnightHonorCmd(
        SuperAiUnitSnap player, out string str, out string label)
    {
        str = "";
        label = "";
        int skillIndex;
        int techIndex;
        int targetFlags;
        string skillName;
        if (!TryResolveSuperAiKnightHonorSkill(
                player.Uid, player.Mp, out skillIndex, out techIndex, out targetFlags, out skillName))
        {
            return false;
        }

        int targetIdx;
        string targetName;
        var wantsEnemy = (targetFlags & BtTargetInEnemy) != 0;
        var wantsFriend = (targetFlags & BtTargetInFriend) != 0;
        var wantsMe = (targetFlags & BtTargetInMe) != 0;
        if (wantsEnemy && !wantsFriend && !wantsMe)
        {
            string role;
            if (!TryFindSuperAiFerniPhaseEnemy(
                    SuperAiFerniPhase.Drain, out targetIdx, out targetName, out role))
            {
                WriteLog("SuperAI knight honor: enemy-target but no sergeant");
                return false;
            }

            str = "S|" + SuperAiHex(skillIndex) + "|" + SuperAiHex(techIndex) + "|"
                  + SuperAiHex(targetIdx);
            label = skillName + "→[" + role + "] " + targetName + "#" + targetIdx;
            return true;
        }

        if (!TryPickSuperAiKnightHonorTarget(player, wantsMe, wantsFriend, out targetIdx, out targetName))
        {
            WriteLog("SuperAI knight honor: found skill but no valid ally target flags=0x"
                     + targetFlags.ToString("X"));
            return false;
        }

        str = "S|" + SuperAiHex(skillIndex) + "|" + SuperAiHex(techIndex) + "|"
              + SuperAiHex(targetIdx);
        label = skillName + "→" + (targetName ?? "?") + "#" + targetIdx;
        return true;
    }

    /// <summary>
    /// 找骑士之誉：SkillId=1005 或名称含「骑士之誉」；优先 Use+Flg，否则仅 Use。
    /// </summary>
    private static bool TryResolveSuperAiKnightHonorSkill(
        string uid, int currentMp,
        out int skillIndex, out int techIndex, out int targetFlags, out string skillName)
    {
        skillIndex = -1;
        techIndex = -1;
        targetFlags = 0;
        skillName = "骑士之誉";
        if (string.IsNullOrEmpty(uid))
        {
            return false;
        }

        try
        {
            var slots = new List<KeyValuePair<int, object>>();
            if (!TryGetPlayerMagicSlots(uid, slots))
            {
                WriteLog("SuperAI knight honor: MagicDatas null uid=" + uid);
                return false;
            }

            for (var pass = 0; pass < 2; pass++)
            {
                for (var si = 0; si < slots.Count; si++)
                {
                    var slotIndex = slots[si].Key;
                    var magic = slots[si].Value;
                    if (magic == null || Convert.ToInt32(GetMember(magic, "useFlag") ?? 0) != 1)
                    {
                        continue;
                    }

                    var sid = Convert.ToInt32(GetMember(magic, "skillId") ?? GetMember(magic, "SkillId") ?? 0);
                    var mname = Convert.ToString(GetMember(magic, "Name") ?? GetMember(magic, "name") ?? "") ?? "";
                    var idOk = sid == SuperAiSkillIdKnightHonor;
                    var nameOk = mname.IndexOf("骑士之誉", StringComparison.Ordinal) >= 0;
                    if (!idOk && !nameOk)
                    {
                        var techsProbe = GetMember(magic, "techs") as IList;
                        if (techsProbe != null)
                        {
                            for (var pi = 0; pi < techsProbe.Count && !nameOk; pi++)
                            {
                                var t = techsProbe[pi];
                                if (t == null)
                                {
                                    continue;
                                }

                                var tn = Convert.ToString(GetMember(t, "Name") ?? GetMember(t, "name") ?? "") ?? "";
                                if (tn.IndexOf("骑士之誉", StringComparison.Ordinal) >= 0)
                                {
                                    nameOk = true;
                                }
                            }
                        }
                    }

                    if (!idOk && !nameOk)
                    {
                        continue;
                    }

                    if (Convert.ToBoolean(GetMember(magic, "forgetInBatlle") ?? false)
                        || Convert.ToBoolean(GetMember(magic, "isCD") ?? false))
                    {
                        WriteLog("SuperAI knight honor: skill sid=" + sid + " forget/CD");
                        continue;
                    }

                    var techs = GetMember(magic, "techs") as IList;
                    if (techs == null)
                    {
                        continue;
                    }

                    var bestLv = -1;
                    var bestTechIndex = -1;
                    var bestFlags = 0;
                    var bestName = string.IsNullOrEmpty(mname) ? "骑士之誉" : mname;
                    for (var ti = 0; ti < techs.Count; ti++)
                    {
                        var tech = techs[ti];
                        if (tech == null)
                        {
                            continue;
                        }

                        var use = Convert.ToBoolean(GetMember(tech, "Use") ?? GetMember(tech, "use") ?? false);
                        var flg = Convert.ToBoolean(GetMember(tech, "Flg") ?? GetMember(tech, "flg") ?? false);
                        if (!use || (pass == 0 && !flg))
                        {
                            continue;
                        }

                        var fp = Convert.ToInt32(GetMember(tech, "Fp") ?? GetMember(tech, "fp") ?? 0);
                        if (currentMp < fp)
                        {
                            continue;
                        }

                        var lv = Convert.ToInt32(GetMember(tech, "Level") ?? GetMember(tech, "level") ?? (ti + 1));
                        if (lv < bestLv)
                        {
                            continue;
                        }

                        bestLv = lv;
                        bestTechIndex = Convert.ToInt32(GetMember(tech, "Index") ?? GetMember(tech, "index") ?? ti);
                        bestFlags = Convert.ToInt32(GetMember(tech, "Target") ?? GetMember(tech, "target") ?? 0);
                        var tn = Convert.ToString(GetMember(tech, "Name") ?? GetMember(tech, "name") ?? "") ?? "";
                        if (tn.Length > 0)
                        {
                            bestName = tn;
                        }
                    }

                    if (bestTechIndex < 0)
                    {
                        continue;
                    }

                    skillIndex = slotIndex;
                    techIndex = bestTechIndex;
                    targetFlags = bestFlags;
                    skillName = bestName;
                    if (targetFlags == 0)
                    {
                        targetFlags = BtTargetInMe | BtTargetInFriend;
                    }

                    WriteLog("SuperAI knight honor OK sid=" + sid + " magic#" + slotIndex
                             + " tech=" + techIndex + " flags=0x" + targetFlags.ToString("X")
                             + " pass=" + pass + " name=" + skillName);
                    return true;
                }
            }

            WriteLog("SuperAI knight honor: not in Magic list uid=" + uid + " mp=" + currentMp);
        }
        catch (Exception ex)
        {
            WriteLog("TryResolveSuperAiKnightHonorSkill EX: " + RootMessage(ex));
        }

        return false;
    }

    /// <summary>
    /// 仅接管 VIP「攻击无效」(SkillId=59)：不看血量；
    /// 目标序 自己→己宠→队友人→队友宠；本客户端本场已套过的尽量跳过，实在重复则套自己。
    /// 技能栏位/等级取自已学攻无（与 VIP 同一套）。反弹等仍走官方。
    /// </summary>
    private static bool TryBuildVipAtkInvalidCmd(
        SuperAiUnitSnap ownerPlayer, bool forPlayer, out string str, out string label)
    {
        str = "";
        label = "";
        if (!_superAiVipType14Rewrite || ownerPlayer.Unable || string.IsNullOrEmpty(ownerPlayer.Uid))
        {
            return false;
        }

        var kind = forPlayer ? 0 : 1;
        if (!IsSuperAiVipAutoSwitchOn(ownerPlayer.Uid, kind))
        {
            return false;
        }

        if (!VipListHasAtkInvalid(ownerPlayer.Uid, forPlayer))
        {
            return false;
        }

        SuperAiUnitSnap selfPlayer;
        SuperAiUnitSnap selfPet;
        bool hasPlayer;
        bool hasPet;
        TryGetSuperAiSelfUnits(out selfPlayer, out hasPlayer, out selfPet, out hasPet);

        int targetIdx;
        string targetName;
        if (!TryPickVipAtkInvalidTarget(
                forPlayer, selfPlayer, hasPlayer, selfPet, hasPet,
                out targetIdx, out targetName, true))
        {
            return false;
        }

        if (forPlayer)
        {
            int skillIndex;
            int techIndex;
            if (!TryGetSuperAiPlayerSkillIndices(
                    ownerPlayer.Uid, SuperAiSkillIdAtkInvalid, ownerPlayer.Mp,
                    out skillIndex, out techIndex))
            {
                return false;
            }

            str = "S|" + SuperAiHex(skillIndex) + "|" + SuperAiHex(techIndex) + "|"
                  + SuperAiHex(targetIdx);
            label = "攻击无效→" + (targetName ?? "?") + "#" + targetIdx;
            ClaimVipAtkInvalidTarget(targetIdx);
            return true;
        }

        int slot;
        if (!TryGetSuperAiPetSkillSlot(ownerPlayer.Uid, SuperAiSkillIdAtkInvalid, out slot)
            || slot < 0)
        {
            return false;
        }

        str = "W|" + SuperAiHex(slot) + "|" + SuperAiHex(targetIdx);
        label = "宠攻击无效→" + (targetName ?? "?") + "#" + targetIdx;
        ClaimVipAtkInvalidTarget(targetIdx);
        return true;
    }

    private static void RefreshVipAtkInvalidClaimBattle()
    {
        var battleIndex = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BattleIndex") ?? -1);
        if (battleIndex != _vipAtkInvalidClaimBattleIndex)
        {
            _vipAtkInvalidClaimBattleIndex = battleIndex;
            _vipAtkInvalidClaimedIdx.Clear();
        }
    }

    private static void ClaimVipAtkInvalidTarget(int targetIdx)
    {
        if (targetIdx < 0)
        {
            return;
        }

        RefreshVipAtkInvalidClaimBattle();
        _vipAtkInvalidClaimedIdx.Add(targetIdx);
    }

    /// <summary>
    /// 攻无目标：无 buff 优先；序 自己→己宠→队友人→队友宠；
    /// 跳过本客户端本场已 claim 的；allowRepeatSelf 时若无人可套则套自己。
    /// </summary>
    private static bool TryPickVipAtkInvalidTarget(
        bool casterIsPlayer,
        SuperAiUnitSnap selfPlayer, bool hasPlayer,
        SuperAiUnitSnap selfPet, bool hasPet,
        out int idx, out string name)
    {
        return TryPickVipAtkInvalidTarget(
            casterIsPlayer, selfPlayer, hasPlayer, selfPet, hasPet,
            BcAtkInvalid, out idx, out name, true);
    }

    private static bool TryPickVipAtkInvalidTarget(
        bool casterIsPlayer,
        SuperAiUnitSnap selfPlayer, bool hasPlayer,
        SuperAiUnitSnap selfPet, bool hasPet,
        out int idx, out string name, bool allowRepeatSelf)
    {
        return TryPickVipAtkInvalidTarget(
            casterIsPlayer, selfPlayer, hasPlayer, selfPet, hasPet,
            BcAtkInvalid, out idx, out name, allowRepeatSelf);
    }

    private static bool TryPickVipAtkInvalidTarget(
        bool casterIsPlayer,
        SuperAiUnitSnap selfPlayer, bool hasPlayer,
        SuperAiUnitSnap selfPet, bool hasPet,
        long needAbsentBcFlag,
        out int idx, out string name, bool allowRepeatSelf)
    {
        idx = -1;
        name = "";
        RefreshVipAtkInvalidClaimBattle();

        var selfIdx = -1;
        var ownPetIdx = -1;
        if (casterIsPlayer)
        {
            if (hasPlayer)
            {
                selfIdx = selfPlayer.Idx;
            }

            if (hasPet)
            {
                ownPetIdx = selfPet.Idx;
            }
        }
        else if (hasPet)
        {
            selfIdx = selfPet.Idx;
        }

        var need = new List<SuperAiUnitSnap>();
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine || u.Hp <= 0 || (u.Bc & 2L) != 0)
            {
                continue;
            }

            if (needAbsentBcFlag != 0 && (u.Bc & needAbsentBcFlag) != 0)
            {
                continue;
            }

            need.Add(u);
        }

        if (TryPickVipAtkInvalidFromList(need, selfIdx, ownPetIdx, true, out idx, out name))
        {
            return true;
        }

        if (allowRepeatSelf && selfIdx >= 0)
        {
            for (var i = 0; i < _superAiUnits.Count; i++)
            {
                var u = _superAiUnits[i];
                if (u.Idx != selfIdx)
                {
                    continue;
                }

                if (u.Hp <= 0 || (u.Bc & 2L) != 0)
                {
                    break;
                }

                idx = u.Idx;
                name = u.Name ?? "?";
                return true;
            }
        }

        return TryPickVipAtkInvalidFromList(need, selfIdx, ownPetIdx, false, out idx, out name);
    }

    private static bool TryPickVipAtkInvalidFromList(
        List<SuperAiUnitSnap> need, int selfIdx, int ownPetIdx, bool skipClaimed,
        out int idx, out string name)
    {
        idx = -1;
        name = "";
        SuperAiUnitSnap best = default(SuperAiUnitSnap);
        var bestRank = int.MaxValue;
        var found = false;
        for (var i = 0; i < need.Count; i++)
        {
            var u = need[i];
            if (skipClaimed && _vipAtkInvalidClaimedIdx.Contains(u.Idx))
            {
                continue;
            }

            var rank = RankVipAtkInvalidTarget(u, selfIdx, ownPetIdx);
            if (!found || rank < bestRank || (rank == bestRank && u.Idx < best.Idx))
            {
                best = u;
                bestRank = rank;
                found = true;
            }
        }

        if (!found)
        {
            return false;
        }

        idx = best.Idx;
        name = best.Name ?? "?";
        return true;
    }

    /// <summary>0自己 1己宠 2队友人 3队友宠。队友人=其它人物；己宠=同列非己（Index%5）。</summary>
    private static int RankVipAtkInvalidTarget(SuperAiUnitSnap u, int selfIdx, int ownPetIdx)
    {
        if (selfIdx >= 0 && u.Idx == selfIdx)
        {
            return 0;
        }

        if (ownPetIdx >= 0 && u.Idx == ownPetIdx)
        {
            return 1;
        }

        // 同列宠但配对漏判时仍当己宠
        if (selfIdx >= 0 && !u.IsPlayer && IsSuperAiSameColumnPair(selfIdx, u.Idx))
        {
            return 1;
        }

        return u.IsPlayer ? 2 : 3;
    }

    /// <summary>VIP 自动技列表是否含攻击无效(59)。</summary>
    private static bool VipListHasAtkInvalid(string uid, bool forPlayer)
    {
        var ids = CollectSuperAiVipType14SkillIds(uid, forPlayer);
        for (var i = 0; i < ids.Count; i++)
        {
            if (ids[i] == SuperAiSkillIdAtkInvalid)
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>兼容旧名：仅攻击无效。</summary>
    private static bool TryBuildSuperAiType14Cmd(
        SuperAiUnitSnap ownerPlayer, bool forPlayer, out string str, out string label)
    {
        return TryBuildVipAtkInvalidCmd(ownerPlayer, forPlayer, out str, out label);
    }

    private static bool TryGetSuperAiType14Flag(int skillId, out long flag, out string name)
    {
        flag = 0;
        name = "";
        switch (skillId)
        {
            case SuperAiSkillIdAtkRebound:
                flag = BcAtkRebound;
                name = "攻击反弹";
                return true;
            case SuperAiSkillIdMagicRebound:
                flag = BcMagicRebound;
                name = "魔法反弹";
                return true;
            case SuperAiSkillIdAtkAbsorb:
                flag = BcAtkAbsorb;
                name = "攻击吸收";
                return true;
            case SuperAiSkillIdMagicAbsorb:
                flag = BcMagicAbsorb;
                name = "魔法吸收";
                return true;
            case SuperAiSkillIdAtkInvalid:
                flag = BcAtkInvalid;
                name = "攻击无效";
                return true;
            case SuperAiSkillIdMagicInvalid:
                flag = BcMagicInvalid;
                name = "魔法无效";
                return true;
            default:
                return false;
        }
    }

    /// <summary>从 VIP 列表取 Type14 六件套 SkillId（保持列表优先级）。</summary>
    private static List<int> CollectSuperAiVipType14SkillIds(string uid, bool forPlayer)
    {
        var list = new List<int>();
        if (string.IsNullOrEmpty(uid))
        {
            return list;
        }

        try
        {
            var mgr = GetManagerInstance("BattleAutoSkillManager");
            if (mgr == null)
            {
                return list;
            }

            MethodInfo getSorted = null;
            foreach (var m in mgr.GetType().GetMethods(
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
            {
                if (m.Name != "GetSortedSkillDataByUid" || m.GetParameters().Length != 2)
                {
                    continue;
                }

                getSorted = m;
                break;
            }

            if (getSorted == null)
            {
                return list;
            }

            // 人物列表用 (uid,uid)；宠列表官方也常按主号 uid 取宠配置
            var raw = getSorted.Invoke(mgr, new object[] { uid, uid }) as IEnumerable;
            if (raw == null)
            {
                return list;
            }

            foreach (var item in raw)
            {
                if (item == null)
                {
                    continue;
                }

                var rawSkillId = Convert.ToInt32(
                    GetMember(item, "SkillId") ?? GetMember(item, "skillId") ?? 0);
                // 宠 VIP 列表 SkillId 字段实际是 TechId（如 5901）；族 ID 才是配置 55–60
                var skillId = forPlayer ? rawSkillId : NormalizeSuperAiSkillFamilyId(rawSkillId);
                long flag;
                string name;
                if (!TryGetSuperAiType14Flag(skillId, out flag, out name))
                {
                    continue;
                }

                // 宠：PetSkills 比 TechId/族；人：Magic 比 SkillId
                if (forPlayer)
                {
                    int si;
                    int ti;
                    if (!TryGetSuperAiPlayerSkillIndices(uid, skillId, int.MaxValue, out si, out ti))
                    {
                        continue;
                    }
                }
                else
                {
                    int slot;
                    if (!TryGetSuperAiPetSkillSlot(uid, rawSkillId, out slot) || slot < 0)
                    {
                        continue;
                    }
                }

                if (!list.Contains(skillId))
                {
                    list.Add(skillId);
                }
            }
        }
        catch (Exception ex)
        {
            WriteLog("CollectSuperAiVipType14SkillIds EX: " + RootMessage(ex));
        }

        return list;
    }

    /// <summary>活人中无对应 buff；优先人/宠后再 Index 升序。</summary>
    private static bool TryPickSuperAiType14Target(long needFlag, out int idx, out string name)
    {
        idx = -1;
        name = "";
        var candidates = new List<SuperAiUnitSnap>();
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine || u.Hp <= 0 || (u.Bc & 2L) != 0)
            {
                continue;
            }

            if ((u.Bc & needFlag) != 0)
            {
                continue;
            }

            candidates.Add(u);
        }

        if (candidates.Count == 0)
        {
            return false;
        }

        candidates.Sort((a, b) =>
        {
            var ap = a.IsPlayer ? 0 : 1;
            var bp = b.IsPlayer ? 0 : 1;
            if (!_superAiVipType14PreferPlayer)
            {
                ap = 1 - ap;
                bp = 1 - bp;
            }

            var c = ap.CompareTo(bp);
            return c != 0 ? c : a.Idx.CompareTo(b.Idx);
        });

        idx = candidates[0].Idx;
        name = candidates[0].Name ?? "?";
        return true;
    }

    /// <summary>骑士之誉友方目标：官方同补血走 LowHP；可含自己（IN_ME）与队友（IN_FRIEND）。</summary>
    private static bool TryPickSuperAiKnightHonorTarget(
        SuperAiUnitSnap self, bool allowSelf, bool allowFriend, out int idx, out string name)
    {
        idx = -1;
        name = "";
        if (!allowSelf && !allowFriend)
        {
            allowSelf = true;
            allowFriend = true;
        }

        var bestPct = 2.0;
        var bestIdx = int.MaxValue;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine || u.Hp <= 0)
            {
                continue;
            }

            var isSelf = u.Idx == self.Idx;
            if (isSelf)
            {
                if (!allowSelf)
                {
                    continue;
                }
            }
            else if (!allowFriend)
            {
                continue;
            }

            var maxHp = u.MaxHp > 0 ? u.MaxHp : 1;
            var pct = (double)u.Hp / maxHp;
            if (pct < bestPct || (Math.Abs(pct - bestPct) < 1e-6 && u.Idx < bestIdx))
            {
                bestPct = pct;
                bestIdx = u.Idx;
                idx = u.Idx;
                name = u.Name ?? "?";
            }
        }

        return idx >= 0;
    }

    private static bool TryGetSuperAiPlayerSkillIndices(
        string uid, int skillId, int currentMp, out int skillIndex, out int techIndex)
    {
        skillIndex = -1;
        techIndex = -1;
        if (string.IsNullOrEmpty(uid) || skillId < 0)
        {
            return false;
        }

        try
        {
            var slots = new List<KeyValuePair<int, object>>();
            if (!TryGetPlayerMagicSlots(uid, slots))
            {
                return false;
            }

            for (var si = 0; si < slots.Count; si++)
            {
                var slotIndex = slots[si].Key;
                var magic = slots[si].Value;
                if (magic == null || Convert.ToInt32(GetMember(magic, "useFlag") ?? 0) != 1)
                {
                    continue;
                }

                var sid = Convert.ToInt32(GetMember(magic, "skillId") ?? GetMember(magic, "SkillId") ?? 0);
                if (sid != skillId)
                {
                    continue;
                }

                if (Convert.ToBoolean(GetMember(magic, "forgetInBatlle") ?? false))
                {
                    continue;
                }

                if (Convert.ToBoolean(GetMember(magic, "isCD") ?? false))
                {
                    continue;
                }

                var techs = GetMember(magic, "techs") as IList;
                if (techs == null)
                {
                    continue;
                }

                var bestLv = -1;
                var bestTechIndex = -1;
                for (var ti = 0; ti < techs.Count; ti++)
                {
                    var tech = techs[ti];
                    if (tech == null)
                    {
                        continue;
                    }

                    var use = Convert.ToBoolean(GetMember(tech, "Use") ?? GetMember(tech, "use") ?? false);
                    var flg = Convert.ToBoolean(GetMember(tech, "Flg") ?? GetMember(tech, "flg") ?? false);
                    if (!use || !flg)
                    {
                        continue;
                    }

                    var fp = Convert.ToInt32(GetMember(tech, "Fp") ?? GetMember(tech, "fp") ?? 0);
                    if (currentMp < fp)
                    {
                        continue;
                    }

                    var lv = Convert.ToInt32(GetMember(tech, "Level") ?? GetMember(tech, "level") ?? (ti + 1));
                    if (lv < bestLv)
                    {
                        continue;
                    }

                    bestLv = lv;
                    bestTechIndex = Convert.ToInt32(GetMember(tech, "Index") ?? GetMember(tech, "index") ?? ti);
                }

                if (bestTechIndex < 0)
                {
                    continue;
                }

                skillIndex = slotIndex;
                techIndex = bestTechIndex;
                return true;
            }
        }
        catch (Exception ex)
        {
            WriteLog("TryGetSuperAiPlayerSkillIndices EX: " + RootMessage(ex));
        }

        return false;
    }

    private static bool TryFindSuperAiLiveEnemy(out int idx, out string name)
    {
        string role;
        return TryFindSuperAiPriorityEnemy(out idx, out name, out role);
    }

    private static bool TryBuildSuperAiPotionCmd(
        SuperAiUnitSnap player, bool hasPet, SuperAiUnitSnap pet,
        out string str, out string label)
    {
        str = "";
        label = "";
        if (player.Unable || player.AiForceTakeover)
        {
            return false;
        }

        EnsureSuperAiPotionPlan();
        int targetIdx;
        if (!_superAiPotionAssignByGiver.TryGetValue(player.Idx, out targetIdx))
        {
            // 自己不是本回合规划的丢药者
            if (ScanSuperAiHpPotions(player.Uid).Count == 0
                && _superAiPrepReady && SuperAiPrepBankHasAny(player.Uid)
                && SuperAiAnyAllyNeedsPotion())
            {
                TryQueueSuperAiPotionBankPull(player.Uid);
            }

            return false;
        }

        SuperAiUnitSnap target;
        if (!TryFindSuperAiUnitByIdx(targetIdx, out target))
        {
            return false;
        }

        var pots = ScanSuperAiHpPotions(player.Uid);
        if (pots.Count == 0)
        {
            if (_superAiPrepReady && SuperAiPrepBankHasAny(player.Uid))
            {
                TryQueueSuperAiPotionBankPull(player.Uid);
                WriteLog("SuperAI potion assigned but bag=0 → bank pull uid=" + player.Uid);
            }

            return false;
        }

        var rec = Math.Max(1, target.Rec);
        var missing = Math.Max(1, target.MaxHp - target.Hp);
        var best = -1;
        var bestScore = int.MaxValue;
        for (var i = 0; i < pots.Count; i++)
        {
            if (pots[i].Type < SuperAiBattleItemMinType)
            {
                continue;
            }

            var heal = pots[i].Power * rec / 100;
            var over = Math.Abs(heal - missing);
            if (over < bestScore)
            {
                bestScore = over;
                best = i;
            }
        }

        if (best < 0 || best >= pots.Count)
        {
            return false;
        }

        var pot = pots[best];
        str = "I|" + SuperAiHex(pot.BagIndex) + "|" + SuperAiHex(target.Idx);
        label = (target.Idx == player.Idx ? "对自己用 " : "投给" + (target.Name ?? "?") + " ")
                + (pot.Name ?? "血瓶");
        return true;
    }

    private static bool SuperAiAnyAllyNeedsPotion()
    {
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            if (SuperAiNeedsPotion(_superAiUnits[i]))
            {
                return true;
            }
        }

        return false;
    }

    private static bool TryFindSuperAiUnitByIdx(int idx, out SuperAiUnitSnap unit)
    {
        unit = default(SuperAiUnitSnap);
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            if (_superAiUnits[i].Idx == idx)
            {
                unit = _superAiUnits[i];
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// 先确定可丢药者（按昨天优先级），再按需瓶者 HP% 从低到高一对一配对。
    /// 同一目标本回合只分到一瓶；同一丢药者只丢一瓶。
    /// </summary>
    private static void EnsureSuperAiPotionPlan()
    {
        var battle = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BattleIndex") ?? -1);
        var turn = GetSuperAiBattleTurn();
        if (battle == _superAiPotionPlanBattle && turn == _superAiPotionPlanTurn)
        {
            return;
        }

        _superAiPotionPlanBattle = battle;
        _superAiPotionPlanTurn = turn;
        _superAiPotionAssignByGiver.Clear();
        _superAiPotionPlanNote = "";

        var rcvCount = CountSuperAiAllyRcvUp();
        var hasPrayer = SuperAiBattleHasPrayerField();

        var givers = new List<SuperAiUnitSnap>();
        var needers = new List<SuperAiUnitSnap>();
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine)
            {
                continue;
            }

            if (SuperAiNeedsPotion(u))
            {
                needers.Add(u);
            }

            if (u.IsPlayer && GetSuperAiPotionGiverTier(u, rcvCount, hasPrayer) < int.MaxValue)
            {
                givers.Add(u);
            }
        }

        if (givers.Count == 0 || needers.Count == 0)
        {
            _superAiPotionPlanNote = "血瓶规划：可丢=" + givers.Count + " 需瓶=" + needers.Count
                                     + " 线" + (int)(GetSuperAiPotionHpThreshold() * 100) + "%";
            return;
        }

        givers.Sort((a, b) =>
        {
            var ta = GetSuperAiPotionGiverTier(a, rcvCount, hasPrayer);
            var tb = GetSuperAiPotionGiverTier(b, rcvCount, hasPrayer);
            var c = ta.CompareTo(tb);
            return c != 0 ? c : a.Idx.CompareTo(b.Idx);
        });
        needers.Sort((a, b) =>
        {
            var c = SuperAiHpRatio(a).CompareTo(SuperAiHpRatio(b));
            return c != 0 ? c : a.Idx.CompareTo(b.Idx);
        });

        var assignedTargets = new HashSet<int>();
        var pairs = new StringBuilder();
        var gi = 0;
        var ni = 0;
        while (gi < givers.Count && ni < needers.Count)
        {
            var g = givers[gi];
            var n = needers[ni];
            if (assignedTargets.Contains(n.Idx))
            {
                ni++;
                continue;
            }

            _superAiPotionAssignByGiver[g.Idx] = n.Idx;
            assignedTargets.Add(n.Idx);
            if (pairs.Length > 0)
            {
                pairs.Append("；");
            }

            pairs.Append((g.Name ?? ("#" + g.Idx)) + "→" + (n.Name ?? ("#" + n.Idx))
                         + "(" + ((int)(SuperAiHpRatio(n) * 100)).ToString() + "%)");
            gi++;
            ni++;
        }

        _superAiPotionPlanNote = "血瓶规划：可丢" + givers.Count + " 需" + needers.Count
                                 + " 线" + (int)(GetSuperAiPotionHpThreshold() * 100) + "%"
                                 + " 配对" + _superAiPotionAssignByGiver.Count
                                 + (pairs.Length > 0 ? "｜" + pairs : "");
        WriteLog("SuperAI potion plan battle=" + battle + " turn=" + turn
                 + " " + _superAiPotionPlanNote);
    }

    /// <summary>普通 45%；高压/百人70–85层 60%；百人86层起 75%。菲尔尼仍走高压 60%。</summary>
    private static float GetSuperAiPotionHpThreshold()
    {
        int dojoLayer;
        if (TryGetAiDojoLayer(out dojoLayer))
        {
            if (dojoLayer >= DojoPotionSuperLayer)
            {
                return SuperAiPotionHpDojoSuper;
            }

            if (dojoLayer >= DojoPotionHighLayer)
            {
                return SuperAiPotionHpHighPressure;
            }
        }

        return _superAiIsHighPressure ? SuperAiPotionHpHighPressure : SuperAiPotionHpLowPressure;
    }

    private static float SuperAiHpRatio(SuperAiUnitSnap u)
    {
        if (u.MaxHp <= 0)
        {
            return 1f;
        }

        return u.Hp / (float)u.MaxHp;
    }

    private static bool SuperAiNeedsPotion(SuperAiUnitSnap u)
    {
        if (!u.Mine || u.MaxHp <= 0 || u.Hp <= 0)
        {
            return false;
        }

        if (u.AiForceTakeover)
        {
            return false;
        }

        // 死亡不算需求；被控仍可能需要被丢药（Unable 仍可进目标）
        if ((u.Bc & 2L) != 0)
        {
            return false;
        }

        return SuperAiHpRatio(u) < GetSuperAiPotionHpThreshold();
    }

    private static bool TryPickSuperAiPotionTarget(out SuperAiUnitSnap target)
    {
        target = default(SuperAiUnitSnap);
        var bestRatio = 2f;
        var found = false;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!SuperAiNeedsPotion(u))
            {
                continue;
            }

            var r = SuperAiHpRatio(u);
            if (!found || r < bestRatio || (Math.Abs(r - bestRatio) < 0.0001f && u.Idx < target.Idx))
            {
                target = u;
                bestRatio = r;
                found = true;
            }
        }

        return found;
    }

    private static int CountSuperAiAllyRcvUp()
    {
        var n = 0;
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (!u.Mine || u.Hp <= 0 || (u.Bc & 2L) != 0)
            {
                continue;
            }

            if ((u.Bc & BcRcvUp) != 0)
            {
                n++;
            }
        }

        return n;
    }

    private static bool SuperAiBattleHasPrayerField()
    {
        try
        {
            var bm = GetManagerInstance("BattleManager");
            if (bm == null)
            {
                return false;
            }

            var flag = GetMember(bm, "m_PropertyIndex");
            if (flag == null)
            {
                return false;
            }

            var v = Convert.ToInt32(flag);
            // BC_FIELD_FLAG: EARTH=1 WATER=2 FIRE=4 WIND=8
            return (v & (1 | 2 | 4 | 8)) != 0;
        }
        catch
        {
            return false;
        }
    }

    /// <summary>
    /// 丢药优先级（越小越优先；MaxValue=无资格）。
    /// 0 传巫咒蓝&lt;100；1 巫师且场上恢≥5；2 咒术且有祈祷；3 非传巫咒；4 传教蓝&gt;100。
    /// 需丢恢的巫师 / 需丢祈祷的咒术 / 被控死 / 无瓶 / AI强制接管 → 无资格。
    /// </summary>
    private static int GetSuperAiPotionGiverTier(SuperAiUnitSnap u, int rcvCount, bool hasPrayer)
    {
        if (!u.Mine || !u.IsPlayer)
        {
            return int.MaxValue;
        }

        if (u.Unable || u.Hp <= 0 || (u.Bc & 2L) != 0 || u.AiForceTakeover)
        {
            return int.MaxValue;
        }

        if (string.IsNullOrEmpty(u.Uid) || ScanSuperAiHpPotions(u.Uid).Count == 0)
        {
            return int.MaxValue;
        }

        var priest = IsSuperAiPriestJob(u);
        var wizard = IsSuperAiWizardJob(u);
        var sorcerer = IsSuperAiSorcererJob(u);

        // AI百人：传教不丢血瓶（交给补血/自动），避免污染 A 瓶分工
        if (priest && _superAiDojoMode)
        {
            return int.MaxValue;
        }

        if (priest || wizard || sorcerer)
        {
            if (u.Mp < SuperAiPotionLowMpPriority)
            {
                return 0;
            }
        }

        if (wizard)
        {
            if (rcvCount >= SuperAiWizardRcvPreferCount)
            {
                return 1;
            }

            // 恢不足：应丢恢复，不参与丢瓶
            return int.MaxValue;
        }

        if (sorcerer)
        {
            if (hasPrayer)
            {
                return 2;
            }

            // 无祈祷：应丢祈祷，不参与丢瓶
            return int.MaxValue;
        }

        if (!priest && !wizard && !sorcerer)
        {
            return 3;
        }

        // 传教蓝≥100
        if (priest && u.Mp > SuperAiPotionLowMpPriority)
        {
            return 4;
        }

        // 传教蓝==100：归入低蓝档之外，按传教低优先
        if (priest)
        {
            return 4;
        }

        return int.MaxValue;
    }

    private static bool IsSuperAiBestPotionGiver(
        SuperAiUnitSnap self, int selfTier, int rcvCount, bool hasPrayer)
    {
        for (var i = 0; i < _superAiUnits.Count; i++)
        {
            var u = _superAiUnits[i];
            if (u.Idx == self.Idx)
            {
                continue;
            }

            var t = GetSuperAiPotionGiverTier(u, rcvCount, hasPrayer);
            if (t < selfTier)
            {
                return false;
            }

            if (t == selfTier && u.Idx < self.Idx)
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// 宠技能族 ID：配置 SkillId（如战栗 6）；VIP 宠列表存的是 TechId（如 601），族=TechId/100。
    /// </summary>
    private static int NormalizeSuperAiSkillFamilyId(int id)
    {
        return id >= 100 ? id / 100 : id;
    }

    /// <summary>
    /// 宠 PetSkills 是否对上目标技能。官方 VIP：人物比 SkillId，宠比 TechId；护卫用 TechId/100==7。
    /// </summary>
    private static bool SuperAiPetTechMatchesWant(object tech, int wantId)
    {
        if (tech == null || wantId < 0)
        {
            return false;
        }

        var skillId = Convert.ToInt32(GetMember(tech, "SkillId") ?? GetMember(tech, "skillId") ?? 0);
        var techId = Convert.ToInt32(GetMember(tech, "TechId") ?? GetMember(tech, "techId") ?? 0);
        var wantFamily = NormalizeSuperAiSkillFamilyId(wantId);

        if (skillId == wantId || techId == wantId)
        {
            return true;
        }

        if (wantFamily > 0)
        {
            if (skillId == wantFamily)
            {
                return true;
            }

            if (techId > 0 && techId / 100 == wantFamily)
            {
                return true;
            }
        }

        // 战栗：名称兜底（个别数据 SkillId/TechId 编码异常）
        if (wantFamily == SuperAiSkillIdTremble)
        {
            var tname = Convert.ToString(GetMember(tech, "Name") ?? GetMember(tech, "name") ?? "") ?? "";
            if (tname.IndexOf("战栗", StringComparison.Ordinal) >= 0)
            {
                return true;
            }
        }

        if (wantFamily == SuperAiSkillIdQiankun)
        {
            var tname = Convert.ToString(GetMember(tech, "Name") ?? GetMember(tech, "name") ?? "") ?? "";
            if (tname.IndexOf("乾坤", StringComparison.Ordinal) >= 0)
            {
                return true;
            }
        }

        return false;
    }

    private static bool TryGetSuperAiPetSkillSlot(string uid, int wantSkillId, out int slot)
    {
        slot = -1;
        if (string.IsNullOrEmpty(uid) || wantSkillId < 0)
        {
            return false;
        }

        try
        {
            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { uid });
            var battlePetId = player != null ? Convert.ToInt32(GetMember(player, "battlePetID") ?? -1) : -1;
            if (battlePetId < 0)
            {
                return false;
            }

            var getPets = FindType("PlayerDataHolder")?.GetMethod(
                "GetPetDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var pets = getPets?.Invoke(null, new object[] { uid }) as IList;
            if (pets == null || battlePetId >= pets.Count || pets[battlePetId] == null)
            {
                return false;
            }

            var pd = GetMember(pets[battlePetId], "data");
            var skills = GetMember(pd, "PetSkills") as IList;
            if (skills == null)
            {
                return false;
            }

            for (var i = 0; i < skills.Count; i++)
            {
                var tech = skills[i];
                if (tech == null)
                {
                    continue;
                }

                var use = Convert.ToBoolean(GetMember(tech, "Use") ?? GetMember(tech, "use") ?? false);
                if (!use)
                {
                    continue;
                }

                if (SuperAiPetTechMatchesWant(tech, wantSkillId))
                {
                    slot = i;
                    return true;
                }
            }
        }
        catch (Exception ex)
        {
            WriteLog("TryGetSuperAiPetSkillSlot EX: " + RootMessage(ex));
        }

        return false;
    }

    // 旧 AssignSuperAiPotionSuggestions / ApplyPotionSuggest 已由 TryBuildSuperAiPotionCmd 通用优先级取代。

    private static List<SuperAiPotion> ScanSuperAiHpPotions(string uid)
    {
        var list = new List<SuperAiPotion>();
        if (string.IsNullOrEmpty(uid))
        {
            return list;
        }

        try
        {
            var getItems = FindType("PlayerDataHolder")?.GetMethod(
                "GetItemDatasFromUid",
                BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var items = getItems?.Invoke(null, new object[] { uid }) as IList;
            if (items == null)
            {
                return list;
            }

            for (var i = 8; i < items.Count && i <= 67; i++)
            {
                var it = items[i];
                if (it == null || Convert.ToInt32(GetMember(it, "useFlag") ?? 0) != 1)
                {
                    continue;
                }

                var data = GetMember(it, "data");
                SuperAiPotion pot;
                if (!TryParseSuperAiHpPotion(data, i, out pot))
                {
                    continue;
                }

                // 已知生命力回复药道具号：强制可投（Type 偶发未刷齐）
                if (pot.Type < SuperAiBattleItemMinType)
                {
                    if (IsSuperAiHpPotionItemId(pot.ItemId))
                    {
                        pot.Type = SuperAiBattleItemMinType;
                    }
                    else
                    {
                        continue;
                    }
                }

                list.Add(pot);
            }
        }
        catch (Exception ex)
        {
            WriteLog("ScanSuperAiHpPotions EX: " + RootMessage(ex));
        }

        return list;
    }

    private static bool TryGetSuperAiHpPotionPowerByItemId(int itemId, out int power)
    {
        power = 0;
        for (var i = 0; i < SuperAiHpPotionItemIds.Length; i++)
        {
            if (SuperAiHpPotionItemIds[i] == itemId)
            {
                power = SuperAiHpPotionPowers[i];
                return true;
            }
        }

        return false;
    }

    private static bool IsSuperAiHpPotionItemId(int itemId)
    {
        int p;
        return TryGetSuperAiHpPotionPowerByItemId(itemId, out p);
    }

    /// <summary>
    /// 优先按道具号 15611–15615 识别；回血量 = Power × 回复 / 100。
    /// </summary>
    private static bool TryParseSuperAiHpPotion(object data, int bagIndex, out SuperAiPotion pot)
    {
        pot = new SuperAiPotion();
        if (data == null)
        {
            return false;
        }

        var itemId = Convert.ToInt32(GetMember(data, "Id") ?? GetProp(data, "Id") ?? 0);
        int power;
        if (!TryGetSuperAiHpPotionPowerByItemId(itemId, out power))
        {
            // 兼容旧名匹配（无 Id 时）
            var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
            var secret = Convert.ToString(GetMember(data, "Secretname") ?? "") ?? "";
            var label = Convert.ToString(GetMember(data, "Label") ?? "") ?? "";
            var raw = secret.Length > 0 ? secret : name;
            if (raw.IndexOf(SuperAiPotionNamePrefix, StringComparison.Ordinal) < 0
                && name.IndexOf(SuperAiPotionNamePrefix, StringComparison.Ordinal) < 0)
            {
                return false;
            }

            power = ParseTrailingNumber(raw);
            if (power <= 0)
            {
                power = ParseTrailingNumber(name);
            }

            if (power <= 0)
            {
                power = ParseTrailingNumber(label);
            }

            if (power <= 0)
            {
                return false;
            }
        }

        var shown = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
        if (string.IsNullOrEmpty(shown) || shown.IndexOf(SuperAiPotionNamePrefix, StringComparison.Ordinal) < 0)
        {
            shown = SuperAiPotionNamePrefix + power;
        }

        pot.Name = shown;
        pot.Power = power;
        pot.ItemId = itemId;
        pot.Count = Math.Max(1, Convert.ToInt32(GetMember(data, "Pile") ?? 1));
        pot.BagIndex = bagIndex;
        pot.Type = Convert.ToInt32(GetMember(data, "Type") ?? 0);
        return true;
    }

    private static int ParseTrailingNumber(string s)
    {
        if (string.IsNullOrEmpty(s))
        {
            return 0;
        }

        var i = s.Length - 1;
        while (i >= 0 && s[i] >= '0' && s[i] <= '9')
        {
            i--;
        }

        if (i == s.Length - 1)
        {
            return 0;
        }

        var num = 0;
        for (var k = i + 1; k < s.Length; k++)
        {
            num = num * 10 + (s[k] - '0');
        }

        return num;
    }

    private static int[] NewSuperAiPotionCountArray()
    {
        return new int[SuperAiHpPotionItemIds.Length];
    }

    private static int SuperAiHpPotionTierIndex(int itemId)
    {
        for (var i = 0; i < SuperAiHpPotionItemIds.Length; i++)
        {
            if (SuperAiHpPotionItemIds[i] == itemId)
            {
                return i;
            }
        }

        return -1;
    }

    private static bool SuperAiPrepBankHasAny(string uid)
    {
        if (string.IsNullOrEmpty(uid))
        {
            return false;
        }

        List<int[]> rows;
        if (_superAiPrepBankRows.TryGetValue(uid, out rows) && rows != null && rows.Count > 0)
        {
            return true;
        }

        int[] counts;
        if (_superAiPrepBankCounts.TryGetValue(uid, out counts) && counts != null)
        {
            for (var i = 0; i < counts.Length; i++)
            {
                if (counts[i] > 0)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private static void TryQueueSuperAiPotionBankPull(string uid)
    {
        if (!_superAiPrepReady || string.IsNullOrEmpty(uid) || !SuperAiPrepBankHasAny(uid))
        {
            return;
        }

        if (_superAiBankPullActive)
        {
            return;
        }

        // 战斗中也可取超银
        StartSuperAiPotionBankPull(uid);
    }

    private static void StartSuperAiPotionBankPull(string uid)
    {
        _superAiBankPullActive = true;
        _superAiBankPullUid = uid ?? "";
        _superAiBankPullPhase = 1;
        _superAiBankPullWaitMs = NowMs();
        _superAiBankPullWhTabDone = false;
        _superAiBankPullLastWhOpenMs = 0;
        ClearAccountBankItemCache();
        Tip("AI血瓶：从账号银行取生命力回复药…");
        WriteLog("SuperAI potion bank-pull start uid=" + uid
                 + " inBattle=" + Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false));
    }

    private static void TickSuperAiPotionBankPull()
    {
        if (!_superAiBankPullActive)
        {
            return;
        }

        var uid = _superAiBankPullUid;
        var now = NowMs();
        if (string.IsNullOrEmpty(uid))
        {
            _superAiBankPullActive = false;
            return;
        }

        // 背包已有则结束
        if (ScanSuperAiHpPotions(uid).Count > 0)
        {
            Tip("AI血瓶：背包已有生命力回复药");
            FinishSuperAiPotionBankPull(true);
            return;
        }

        if (_superAiBankPullPhase == 1)
        {
            // 备战缓存已有仓格：战斗中直接取，不必先开 UI
            int cachedIdx;
            int cachedItem;
            if (TryPickSuperAiBankPotionRow(uid, out cachedIdx, out cachedItem)
                && TrySendAccountBankTakeNum(uid, cachedIdx, 1))
            {
                WriteLog("SuperAI potion bank-take(fast) idx=" + cachedIdx + " item=" + cachedItem);
                _superAiBankPullPhase = 3;
                _superAiBankPullWaitMs = now;
                return;
            }

            ClearAccountBankItemCache();
            TryOpenAccountItemWarehouseUi(uid);
            TrySwitchChildWareHouseToAccountTab(uid);
            _superAiBankPullPhase = 2;
            _superAiBankPullWaitMs = now;
            return;
        }

        if (_superAiBankPullPhase == 2)
        {
            var waited = now - _superAiBankPullWaitMs;
            if (waited > 8000)
            {
                Tip("AI血瓶：账号银行回包超时");
                FinishSuperAiPotionBankPull(false);
                return;
            }

            if (waited > 400)
            {
                var child = FindExistingUiByType("ChildWareHousePanel", "FindChildPanelByType");
                if (child == null)
                {
                    if (now - _superAiBankPullLastWhOpenMs >= 1500)
                    {
                        _superAiBankPullLastWhOpenMs = now;
                        TryOpenAccountItemWarehouseUi(uid);
                    }
                }
                else if (!_superAiBankPullWhTabDone)
                {
                    if (TrySwitchChildWareHouseToAccountTab(uid))
                    {
                        _superAiBankPullWhTabDone = true;
                    }
                }
            }

            IList update;
            if (!TryGetAccountBankUpdateItems(out update) || update.Count == 0)
            {
                return;
            }

            // 刷新缓存行，取最小一瓶（15611→…→15615）
            CacheSuperAiBankPotionsFromUpdate(uid, update);
            int bankIndex;
            int itemId;
            if (!TryPickSuperAiBankPotionRow(uid, out bankIndex, out itemId))
            {
                Tip("AI血瓶：账号银行无生命力回复药");
                FinishSuperAiPotionBankPull(false);
                return;
            }

            if (!TrySendAccountBankTakeNum(uid, bankIndex, 1))
            {
                Tip("AI血瓶：取药发包失败");
                FinishSuperAiPotionBankPull(false);
                return;
            }

            WriteLog("SuperAI potion bank-take idx=" + bankIndex + " item=" + itemId);
            _superAiBankPullPhase = 3;
            _superAiBankPullWaitMs = now;
            return;
        }

        if (_superAiBankPullPhase == 3)
        {
            if (now - _superAiBankPullWaitMs < 600)
            {
                return;
            }

            TrySendAccountBankClose(uid);
            if (ScanSuperAiHpPotions(uid).Count > 0)
            {
                Tip("AI血瓶：已从账号银行取出");
                DecrementSuperAiPrepBankCache(uid);
                FinishSuperAiPotionBankPull(true);
            }
            else if (now - _superAiBankPullWaitMs > 3000)
            {
                Tip("AI血瓶：取药后背包仍空");
                FinishSuperAiPotionBankPull(false);
            }
        }
    }

    private static void FinishSuperAiPotionBankPull(bool ok)
    {
        _superAiBankPullActive = false;
        _superAiBankPullUid = "";
        _superAiBankPullPhase = 0;
        WriteLog("SuperAI potion bank-pull end ok=" + ok);
    }

    private static bool TryPickSuperAiBankPotionRow(string uid, out int bankIndex, out int itemId)
    {
        bankIndex = -1;
        itemId = 0;
        List<int[]> rows;
        if (!_superAiPrepBankRows.TryGetValue(uid, out rows) || rows == null)
        {
            return false;
        }

        // 优先小瓶
        for (var t = 0; t < SuperAiHpPotionItemIds.Length; t++)
        {
            var want = SuperAiHpPotionItemIds[t];
            for (var i = 0; i < rows.Count; i++)
            {
                var row = rows[i];
                if (row == null || row.Length < 3 || row[0] != want || row[2] <= 0)
                {
                    continue;
                }

                itemId = row[0];
                bankIndex = row[1];
                return bankIndex >= 0;
            }
        }

        return false;
    }

    private static void DecrementSuperAiPrepBankCache(string uid)
    {
        List<int[]> rows;
        if (_superAiPrepBankRows.TryGetValue(uid, out rows) && rows != null)
        {
            for (var t = 0; t < SuperAiHpPotionItemIds.Length; t++)
            {
                var want = SuperAiHpPotionItemIds[t];
                for (var i = 0; i < rows.Count; i++)
                {
                    var row = rows[i];
                    if (row == null || row.Length < 3 || row[0] != want || row[2] <= 0)
                    {
                        continue;
                    }

                    row[2]--;
                    int[] counts;
                    if (_superAiPrepBankCounts.TryGetValue(uid, out counts) && counts != null
                        && t < counts.Length && counts[t] > 0)
                    {
                        counts[t]--;
                    }

                    return;
                }
            }
        }
    }

    private static void CacheSuperAiBankPotionsFromUpdate(string uid, IList update)
    {
        var counts = NewSuperAiPotionCountArray();
        var rows = new List<int[]>();
        if (update != null)
        {
            for (var i = 0; i < update.Count; i++)
            {
                var row = update[i];
                if (row == null)
                {
                    continue;
                }

                var itemId = Convert.ToInt32(GetMember(row, "Itemid") ?? GetProp(row, "Itemid") ?? 0);
                var tier = SuperAiHpPotionTierIndex(itemId);
                if (tier < 0)
                {
                    continue;
                }

                var bankIndex = Convert.ToInt32(GetMember(row, "Index") ?? GetProp(row, "Index") ?? -1);
                var pile = Convert.ToInt32(GetMember(row, "Pile") ?? GetProp(row, "Pile") ?? 0);
                if (pile <= 0 || bankIndex < 0)
                {
                    continue;
                }

                counts[tier] += pile;
                rows.Add(new[] { itemId, bankIndex, pile });
            }
        }

        _superAiPrepBankCounts[uid] = counts;
        _superAiPrepBankRows[uid] = rows;
    }

    private static int[] CountSuperAiBagPotionsById(string uid)
    {
        var counts = NewSuperAiPotionCountArray();
        try
        {
            var getItems = FindType("PlayerDataHolder")?.GetMethod(
                "GetItemDatasFromUid",
                BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var items = getItems?.Invoke(null, new object[] { uid }) as IList;
            if (items == null)
            {
                return counts;
            }

            for (var i = 8; i < items.Count && i <= 67; i++)
            {
                var it = items[i];
                if (it == null || Convert.ToInt32(GetMember(it, "useFlag") ?? 0) != 1)
                {
                    continue;
                }

                var data = GetMember(it, "data");
                if (data == null)
                {
                    continue;
                }

                var itemId = Convert.ToInt32(GetMember(data, "Id") ?? GetProp(data, "Id") ?? 0);
                var tier = SuperAiHpPotionTierIndex(itemId);
                if (tier < 0)
                {
                    continue;
                }

                counts[tier] += Math.Max(1, Convert.ToInt32(GetMember(data, "Pile") ?? 1));
            }
        }
        catch (Exception ex)
        {
            WriteLog("CountSuperAiBagPotionsById EX: " + RootMessage(ex));
        }

        return counts;
    }

    private static void StartSuperAiPrep()
    {
        if (_superAiPrepActive)
        {
            Tip("备战准备进行中…");
            return;
        }

        if (Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
        {
            Tip("备战准备：请先退出战斗");
            return;
        }

        _superAiPrepUids.Clear();
        _superAiPrepBagCounts.Clear();
        _superAiPrepBankCounts.Clear();
        _superAiPrepBankRows.Clear();
        _superAiPrepReady = false;
        var uids = CollectTeamOrMultiUids();
        if (uids == null || uids.Count == 0)
        {
            var main = GetMainPlayerUidSafe();
            if (!string.IsNullOrEmpty(main))
            {
                uids = new List<string> { main };
            }
        }

        if (uids == null || uids.Count == 0)
        {
            Tip("备战准备：无角色");
            return;
        }

        for (var i = 0; i < uids.Count; i++)
        {
            if (!string.IsNullOrEmpty(uids[i]))
            {
                _superAiPrepUids.Add(uids[i]);
            }
        }

        _superAiPrepActive = true;
        _superAiPrepPhase = 1;
        _superAiPrepUidIndex = 0;
        _superAiPrepWaitMs = NowMs();
        _superAiPrepNote = "扫描背包…";
        Tip("备战准备：开始扫描生命力回复药库存");
        WriteLog("SuperAI prep start n=" + _superAiPrepUids.Count);
        if (_tab == TabSuperAi)
        {
            try { SetText(_superAiStatusText, FormatSuperAiStatus(), 13); } catch { }
        }
    }

    private static void TickSuperAiPrep()
    {
        if (!_superAiPrepActive)
        {
            return;
        }

        if (Convert.ToBoolean(GetStaticMember("BattleDataHolder", "IsInBattle") ?? false))
        {
            _superAiPrepNote = "战斗中，备战暂停（请退战）";
            return;
        }

        var now = NowMs();
        if (_superAiPrepUidIndex < 0 || _superAiPrepUidIndex >= _superAiPrepUids.Count)
        {
            FinishSuperAiPrep();
            return;
        }

        var uid = _superAiPrepUids[_superAiPrepUidIndex];
        if (_superAiPrepPhase == 1)
        {
            _superAiPrepBagCounts[uid] = CountSuperAiBagPotionsById(uid);
            ClearAccountBankItemCache();
            TryOpenAccountItemWarehouseUi(uid);
            TrySwitchChildWareHouseToAccountTab(uid);
            _superAiPrepPhase = 2;
            _superAiPrepWaitMs = now;
            _superAiPrepNote = "扫银行 " + FormatBaptismPlayerShort(uid) + "…";
            return;
        }

        if (_superAiPrepPhase == 2)
        {
            var waited = now - _superAiPrepWaitMs;
            if (waited > 8000)
            {
                _superAiPrepBankCounts[uid] = NewSuperAiPotionCountArray();
                _superAiPrepBankRows[uid] = new List<int[]>();
                WriteLog("SuperAI prep bank timeout uid=" + uid);
                _superAiPrepUidIndex++;
                _superAiPrepPhase = 1;
                _superAiPrepWaitMs = now;
                return;
            }

            if (waited > 400)
            {
                var child = FindExistingUiByType("ChildWareHousePanel", "FindChildPanelByType");
                if (child != null)
                {
                    TrySwitchChildWareHouseToAccountTab(uid);
                }
                else if (waited > 1200 && waited < 1400)
                {
                    TryOpenAccountItemWarehouseUi(uid);
                }
            }

            IList update;
            if (!TryGetAccountBankUpdateItems(out update) || update.Count == 0)
            {
                return;
            }

            CacheSuperAiBankPotionsFromUpdate(uid, update);
            TrySendAccountBankClose(uid);
            WriteLog("SuperAI prep uid=" + uid
                     + " bag=" + FormatSuperAiPotionCounts(_superAiPrepBagCounts[uid])
                     + " bank=" + FormatSuperAiPotionCounts(_superAiPrepBankCounts[uid]));
            _superAiPrepUidIndex++;
            _superAiPrepPhase = 1;
            _superAiPrepWaitMs = now;
            if (_superAiPrepUidIndex >= _superAiPrepUids.Count)
            {
                FinishSuperAiPrep();
            }
        }
    }

    private static string FormatSuperAiPotionCounts(int[] counts)
    {
        if (counts == null)
        {
            return "-";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < SuperAiHpPotionPowers.Length && i < counts.Length; i++)
        {
            if (i > 0)
            {
                sb.Append(' ');
            }

            sb.Append(SuperAiHpPotionPowers[i]).Append('×').Append(counts[i]);
        }

        return sb.ToString();
    }

    private static void FinishSuperAiPrep()
    {
        _superAiPrepActive = false;
        _superAiPrepPhase = 0;
        _superAiPrepReady = true;
        var sb = new StringBuilder();
        sb.AppendLine("备战准备完成（回血=药力×回复/100）");
        for (var i = 0; i < _superAiPrepUids.Count; i++)
        {
            var uid = _superAiPrepUids[i];
            int[] bag;
            int[] bank;
            _superAiPrepBagCounts.TryGetValue(uid, out bag);
            _superAiPrepBankCounts.TryGetValue(uid, out bank);
            sb.Append(FormatBaptismPlayerShort(uid))
              .Append(" 包[").Append(FormatSuperAiPotionCounts(bag)).Append(']')
              .Append(" 银[").Append(FormatSuperAiPotionCounts(bank)).Append(']')
              .AppendLine();
        }

        _superAiPrepNote = sb.ToString().TrimEnd();
        Tip("备战准备已完成");
        WriteLog("SuperAI prep done\n" + _superAiPrepNote);
        if (_tab == TabSuperAi && _superAiStatusText != null && !IsUnityNull(_superAiStatusText))
        {
            try { SetText(_superAiStatusText, FormatSuperAiStatus(), 13); } catch { }
        }
    }

    /// <summary>模拟决策占位：不发包、不改 Auto 配置。</summary>
    private static string SimulateSuperAiDecision(string dump)
    {
        return dump ?? "";
    }

    private static bool TryBuildSuperAiBattlefieldDump(out string dump, out string key)
    {
        dump = "";
        key = "";
        try
        {
            var sb = new StringBuilder(4096);
            var uid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount")
                                      ?? GetStaticMember("PlayerDataHolder", "MainPlayerUid") ?? "") ?? "";
            var battleIndex = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BattleIndex") ?? -1);
            var playerMp = Convert.ToInt32(GetStaticMember("BattleDataHolder", "PlayerMp") ?? 0);
            var playerIdx = Convert.ToInt32(GetStaticMember("BattleDataHolder", "battlePlayerIndex") ?? -1);
            var acountN = 0;
            try
            {
                var list = GetStaticMember("BattleDataHolder", "AcountList") as ICollection;
                acountN = list != null ? list.Count : 0;
            }
            catch
            {
                // ignore
            }

            var fieldPray = ReadBattleFieldPrayFlags();
            var melee = CheckEquippedMelee(uid);
            string selfName;
            string selfJob;
            ReadSuperAiSelfIdentity(uid, out selfName, out selfJob);
            sb.AppendLine("uid=" + uid + " name=" + selfName + " job=" + selfJob
                          + " battleIndex=" + battleIndex + " playerIdx=" + playerIdx
                          + " PlayerMp=" + playerMp);
            sb.AppendLine("AcountList=" + acountN
                          + " weaponMelee=" + melee.Melee + " weapon=" + melee.WeaponDesc);
            sb.AppendLine("fieldPray=" + fieldPray + "  // VIP type11: 无地水火风场才可放属性祈祷类");
            AppendSuperAiBattleMeta(sb, uid);
            AppendSuperAiBagItems(sb, uid);
            AppendSuperAiOwnStats(sb, uid);
            AppendSuperAiSkills(sb, uid);
            AppendSuperAiPetSkills(sb, uid);
            var unitsKey = AppendSuperAiBattleUnits(sb, playerIdx);

            dump = sb.ToString();
            key = battleIndex + "|" + playerMp + "|" + fieldPray + "|" + unitsKey;
            return dump.Length > 0;
        }
        catch (Exception ex)
        {
            WriteLog("TryBuildSuperAiBattlefieldDump EX: " + RootMessage(ex));
            return false;
        }
    }

    /// <summary>普通 Auto 配置 / BP 武器旗 / VIP 集火等（探索结论补全）。</summary>
    private static void AppendSuperAiBattleMeta(StringBuilder sb, string uid)
    {
        try
        {
            var bm = GetManagerInstance("BattleManager");
            var isAuto = bm != null && Convert.ToBoolean(GetMember(bm, "IsAutoBattle") ?? false);
            var bp = Convert.ToInt32(GetStaticMember("BattleDataHolder", "BPFlag") ?? 0);
            // WEAPON_DIRECT=0x80 BOW=0x100 BOOMERANG=0x200 KNIFE=0x400
            var wparts = new List<string>();
            if ((bp & 0x80) != 0) wparts.Add("DIRECT");
            if ((bp & 0x100) != 0) wparts.Add("BOW");
            if ((bp & 0x200) != 0) wparts.Add("BOOMERANG");
            if ((bp & 0x400) != 0) wparts.Add("KNIFE");
            sb.AppendLine("IsAutoBattle=" + isAuto + " BPFlag=0x" + bp.ToString("X")
                          + " bpWeapon=" + (wparts.Count > 0 ? string.Join("+", wparts.ToArray()) : "none"));

            // 普通 Auto：Config[0]=人物1动 Config[1]=人物2动；Type 0/1攻 2守 3技
            if (bm != null)
            {
                var configs = GetMember(bm, "PlayerAutoConfigs") as IDictionary;
                if (configs != null && configs.Contains(uid))
                {
                    var auto = configs[uid];
                    var cfgList = GetMember(auto, "Config") as IList;
                    if (cfgList != null)
                    {
                        for (var i = 0; i < cfgList.Count && i < 2; i++)
                        {
                            var c = cfgList[i];
                            if (c == null)
                            {
                                continue;
                            }

                            var typ = Convert.ToInt32(GetMember(c, "Type") ?? -1);
                            var typName = typ == 2 ? "守" : (typ == 3 ? "技" : "攻");
                            sb.AppendLine("normalAuto Config[" + i + "] type=" + typ + "(" + typName + ")"
                                          + " skill=" + GetMember(c, "Skillindex")
                                          + " tech=" + GetMember(c, "Techindex"));
                        }
                    }
                }
                else
                {
                    sb.AppendLine("normalAuto Config=(missing)");
                }
            }

            var asm = GetManagerInstance("BattleAutoSkillManager");
            if (asm != null)
            {
                var focus = Convert.ToInt32(GetMember(asm, "focusFireIndex") ?? -1);
                var guardN = 0;
                try
                {
                    var gd = GetMember(asm, "needGuardDict") as IDictionary;
                    guardN = gd != null ? gd.Count : 0;
                }
                catch
                {
                    // ignore
                }

                sb.AppendLine("vipMeta focusFireIndex=" + focus + " needGuardDict=" + guardN
                              + " (官方字段；AI 用 SeqChapterAiBattleTarget.Index，不写 focusFire)");
            }
        }
        catch (Exception ex)
        {
            sb.AppendLine("battleMeta err=" + RootMessage(ex));
        }
    }

    private static void AppendSuperAiPetSkills(StringBuilder sb, string uid)
    {
        sb.AppendLine("petSkills:");
        try
        {
            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { uid });
            var battlePetId = player != null ? Convert.ToInt32(GetMember(player, "battlePetID") ?? -1) : -1;
            if (battlePetId < 0)
            {
                sb.AppendLine("  (no battle pet)");
                return;
            }

            var getPets = FindType("PlayerDataHolder")?.GetMethod(
                "GetPetDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var pets = getPets?.Invoke(null, new object[] { uid }) as IList;
            if (pets == null || battlePetId >= pets.Count || pets[battlePetId] == null)
            {
                sb.AppendLine("  (pet missing)");
                return;
            }

            var pd = GetMember(pets[battlePetId], "data");
            var skills = GetMember(pd, "PetSkills") as IEnumerable;
            if (skills == null)
            {
                sb.AppendLine("  (no PetSkills)");
                return;
            }

            var n = 0;
            foreach (var tech in skills)
            {
                if (tech == null)
                {
                    continue;
                }

                var use = Convert.ToBoolean(GetMember(tech, "Use") ?? GetMember(tech, "use") ?? false);
                if (!use)
                {
                    continue;
                }

                var skillId = Convert.ToInt32(GetMember(tech, "SkillId") ?? GetMember(tech, "skillId") ?? 0);
                var techId = Convert.ToInt32(GetMember(tech, "TechId") ?? GetMember(tech, "techId") ?? 0);
                var lv = Convert.ToInt32(GetMember(tech, "Level") ?? GetMember(tech, "level") ?? 0);
                var fp = Convert.ToInt32(GetMember(tech, "Fp") ?? GetMember(tech, "fp") ?? 0);
                var tname = Convert.ToString(GetMember(tech, "Name") ?? GetMember(tech, "name") ?? "") ?? "";
                var memo = Convert.ToString(GetMember(tech, "Memo") ?? GetMember(tech, "memo") ?? "") ?? "";
                var autoType = ReadSkillAutoType(skillId);
                sb.Append("  ").Append(tname).Append(" skill=").Append(skillId)
                    .Append(" tech=").Append(techId).Append(" L").Append(lv)
                    .Append(" fp=").Append(fp).Append(" autoType=").Append(autoType);
                if (memo.Length > 0)
                {
                    sb.Append(" effect=").Append(TrimDiag(memo, 40));
                }

                sb.AppendLine();
                n++;
                if (n >= 30)
                {
                    sb.AppendLine("  ...(cap 30)");
                    break;
                }
            }

            if (n == 0)
            {
                sb.AppendLine("  (none usable)");
            }
        }
        catch (Exception ex)
        {
            sb.AppendLine("  petSkills err=" + RootMessage(ex));
        }
    }

    private static string ReadBattleFieldPrayFlags()
    {
        try
        {
            // BattleProcesser.m_PropertyIndex ← Proto_SC_BattleChar.BCFIELDFLAG（属性祈祷场）
            object proc = null;
            try
            {
                var gmType = FindType("GameManagerHotfix");
                var mono = FindType("MonoSingleton`1");
                if (gmType != null && mono != null)
                {
                    var closed = mono.MakeGenericType(gmType);
                    var inst = closed.GetProperty("instance", BindingFlags.Public | BindingFlags.Static)
                               ?.GetValue(null, null)
                               ?? closed.GetField("instance", BindingFlags.Public | BindingFlags.Static)
                                   ?.GetValue(null);
                    proc = GetMember(inst, "battleProcesser");
                }
            }
            catch
            {
                // ignore
            }

            if (proc == null)
            {
                return "?";
            }

            var f = proc.GetType().GetField("m_PropertyIndex",
                BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
            if (f == null)
            {
                return "?";
            }

            var v = Convert.ToInt32(f.GetValue(proc) ?? 0);
            // BC_FIELD_FLAG: EARTH=1 WATER=2 FIRE=4 WIND=8 SILENCE=16 END=32
            if (v == 0)
            {
                return "none";
            }

            if (v == 32)
            {
                return "END";
            }

            var parts = new List<string>();
            if ((v & 1) != 0) parts.Add("地");
            if ((v & 2) != 0) parts.Add("水");
            if ((v & 4) != 0) parts.Add("火");
            if ((v & 8) != 0) parts.Add("风");
            if ((v & 16) != 0) parts.Add("沉默");
            return parts.Count > 0 ? string.Join("+", parts.ToArray()) + "(raw=" + v + ")" : ("raw=" + v);
        }
        catch
        {
            return "?";
        }
    }

    private struct SuperAiWeaponInfo
    {
        public bool Melee;
        public string WeaponDesc;
    }

    /// <summary>对齐 BattleRoleSelector.CheckMelee：槽 2/3，Type 4/5/6 为远程。</summary>
    private static SuperAiWeaponInfo CheckEquippedMelee(string uid)
    {
        var info = new SuperAiWeaponInfo { Melee = true, WeaponDesc = "无" };
        try
        {
            var getItems = FindType("PlayerDataHolder")?.GetMethod(
                "GetItemDatasFromUid",
                BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var itemList = getItems?.Invoke(null, new object[] { uid }) as IList;
            if (itemList == null || itemList.Count <= 3)
            {
                return info;
            }

            var parts = new List<string>();
            for (var slot = 2; slot <= 3; slot++)
            {
                var it = itemList[slot];
                if (it == null)
                {
                    continue;
                }

                var useFlag = Convert.ToInt32(GetMember(it, "useFlag") ?? 0);
                if (useFlag != 1)
                {
                    continue;
                }

                var data = GetMember(it, "data");
                if (data == null)
                {
                    continue;
                }

                var type = Convert.ToInt32(GetMember(data, "Type") ?? 0);
                var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
                parts.Add("slot" + slot + ":" + name + "(t=" + type + ")");
                if (type == 4 || type == 5 || type == 6)
                {
                    info.Melee = false;
                }
            }

            if (parts.Count > 0)
            {
                info.WeaponDesc = string.Join(";", parts.ToArray());
            }
        }
        catch (Exception ex)
        {
            info.WeaponDesc = "err:" + RootMessage(ex);
        }

        return info;
    }

    private static void AppendSuperAiBagItems(StringBuilder sb, string uid)
    {
        sb.Append("bagHpPotions:");
        try
        {
            var getItems = FindType("PlayerDataHolder")?.GetMethod(
                "GetItemDatasFromUid",
                BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var itemList = getItems?.Invoke(null, new object[] { uid }) as IEnumerable;
            var n = 0;
            if (itemList != null)
            {
                foreach (var it in itemList)
                {
                    if (it == null || Convert.ToInt32(GetMember(it, "useFlag") ?? 0) != 1)
                    {
                        continue;
                    }

                    var data = GetMember(it, "data");
                    if (data == null)
                    {
                        continue;
                    }

                    var type = Convert.ToInt32(GetMember(data, "Type") ?? 0);
                    var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
                    // 43 常见血瓶类；名称兜底
                    var isHp = type == 43 || type == 23
                               || name.IndexOf("血", StringComparison.Ordinal) >= 0
                               || name.IndexOf("生命", StringComparison.Ordinal) >= 0;
                    if (!isHp)
                    {
                        continue;
                    }

                    var pile = Convert.ToInt32(GetMember(data, "Pile") ?? GetMember(it, "pile") ?? 1);
                    sb.Append(" [").Append(name).Append(" t=").Append(type).Append(" x").Append(pile).Append("]");
                    n++;
                    if (n >= 12)
                    {
                        break;
                    }
                }
            }

            if (n == 0)
            {
                sb.Append(" (无)");
            }
        }
        catch (Exception ex)
        {
            sb.Append(" err=").Append(RootMessage(ex));
        }

        sb.AppendLine();
    }

    private static void ReadSuperAiSelfIdentity(string uid, out string name, out string job)
    {
        name = "?";
        job = "?";
        try
        {
            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { uid });
            if (player == null)
            {
                return;
            }

            name = Convert.ToString(GetMember(player, "name") ?? "") ?? "?";
            var jobName = Convert.ToString(GetMember(player, "JobName") ?? "") ?? "";
            var ancestry = Convert.ToString(GetMember(player, "JobAncestryName") ?? "") ?? "";
            var jobId = Convert.ToInt32(GetMember(player, "Job") ?? -1);
            var ancestryId = Convert.ToInt32(GetMember(player, "JobAncestry") ?? -1);
            if (jobName.Length == 0 && ancestry.Length == 0)
            {
                job = "id=" + jobId + "/ancestry=" + ancestryId;
            }
            else if (ancestry.Length > 0 && ancestry != jobName)
            {
                job = ancestry + "/" + jobName + "(job=" + jobId + ",anc=" + ancestryId + ")";
            }
            else
            {
                job = (jobName.Length > 0 ? jobName : ancestry) + "(job=" + jobId + ",anc=" + ancestryId + ")";
            }
        }
        catch
        {
            // keep ?
        }
    }

    private static void AppendSuperAiOwnStats(StringBuilder sb, string uid)
    {
        try
        {
            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { uid });
            if (player != null)
            {
                var name = Convert.ToString(GetMember(player, "name") ?? "") ?? "";
                var jobName = Convert.ToString(GetMember(player, "JobName") ?? "") ?? "";
                var ancestry = Convert.ToString(GetMember(player, "JobAncestryName") ?? "") ?? "";
                sb.AppendLine("selfOutBattleStat name=" + name
                              + " job=" + jobName
                              + " jobAncestry=" + ancestry
                              + " jobId=" + GetMember(player, "Job")
                              + " ancestryId=" + GetMember(player, "JobAncestry")
                              + " hp=" + GetMember(player, "hp")
                              + "/" + GetMember(player, "maxHp")
                              + " mp=" + GetMember(player, "mp") + "/" + GetMember(player, "maxMp")
                              + " atk=" + GetMember(player, "AttackPower")
                              + " def=" + GetMember(player, "DefencePower")
                              + " agi=" + GetMember(player, "Agility")
                              + " rcv=" + GetMember(player, "Recovery"));
            }

            var battlePetId = player != null ? Convert.ToInt32(GetMember(player, "battlePetID") ?? -1) : -1;
            if (battlePetId >= 0)
            {
                var getPets = FindType("PlayerDataHolder")?.GetMethod(
                    "GetPetDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
                var pets = getPets?.Invoke(null, new object[] { uid }) as IList;
                if (pets != null && battlePetId < pets.Count && pets[battlePetId] != null)
                {
                    var pet = pets[battlePetId];
                    var pd = GetMember(pet, "data") ?? pet;
                    sb.AppendLine("petOutBattleStat name=" + GetMember(pd, "Name")
                                  + " hp=" + GetMember(pd, "Hp") + "/" + GetMember(pd, "MaxHp")
                                  + " mp=" + GetMember(pd, "Mp") + "/" + GetMember(pd, "MaxMp")
                                  + " atk=" + GetMember(pd, "AttackPower")
                                  + " def=" + GetMember(pd, "DefencePower")
                                  + " agi=" + GetMember(pd, "Agility")
                                  + " rcv=" + GetMember(pd, "Recovery"));
                }
            }
        }
        catch (Exception ex)
        {
            sb.AppendLine("ownStats err=" + RootMessage(ex));
        }
    }

    private static void AppendSuperAiSkills(StringBuilder sb, string uid)
    {
        sb.AppendLine("skills(usable, !forget):");
        try
        {
            var slots = new List<KeyValuePair<int, object>>();
            if (!TryGetPlayerMagicSlots(uid, slots))
            {
                sb.AppendLine("  (none)");
                return;
            }

            var n = 0;
            for (var mi = 0; mi < slots.Count; mi++)
            {
                var magic = slots[mi].Value;
                if (magic == null || Convert.ToInt32(GetMember(magic, "useFlag") ?? 0) != 1)
                {
                    continue;
                }

                var forget = Convert.ToBoolean(GetMember(magic, "forgetInBatlle") ?? false);
                var cd = Convert.ToBoolean(GetMember(magic, "isCD") ?? false);
                var skillId = Convert.ToInt32(GetMember(magic, "skillId") ?? 0);
                var name = Convert.ToString(GetMember(magic, "name") ?? GetMember(magic, "Name") ?? "") ?? "";
                var autoType = ReadSkillAutoType(skillId);
                sb.Append("  #").Append(slots[mi].Key).Append(" id=").Append(skillId).Append(" ").Append(name)
                    .Append(" forget=").Append(forget).Append(" cd=").Append(cd)
                    .Append(" autoType=").Append(autoType);
                var techs = GetMember(magic, "techs") as IList;
                if (techs != null)
                {
                    sb.Append(" techs=[");
                    for (var i = 0; i < techs.Count; i++)
                    {
                        var tech = techs[i];
                        if (tech == null)
                        {
                            continue;
                        }

                        var use = Convert.ToBoolean(GetMember(tech, "Use") ?? GetMember(tech, "use") ?? false);
                        var flg = Convert.ToBoolean(GetMember(tech, "Flg") ?? GetMember(tech, "flg") ?? false);
                        var lv = Convert.ToInt32(GetMember(tech, "Level") ?? GetMember(tech, "level") ?? (i + 1));
                        var fp = Convert.ToInt32(GetMember(tech, "Fp") ?? GetMember(tech, "fp") ?? 0);
                        var memo = Convert.ToString(GetMember(tech, "Memo") ?? GetMember(tech, "memo") ?? "") ?? "";
                        var tname = Convert.ToString(GetMember(tech, "Name") ?? GetMember(tech, "name") ?? "") ?? "";
                        if (i > 0)
                        {
                            sb.Append("; ");
                        }

                        sb.Append("L").Append(lv).Append(":").Append(tname)
                            .Append(" fp=").Append(fp).Append(" use=").Append(use).Append(" flg=").Append(flg);
                        if (memo.Length > 0)
                        {
                            sb.Append(" effect=").Append(TrimDiag(memo, 40));
                        }
                    }

                    sb.Append("]");
                }

                sb.AppendLine();
                n++;
                if (n >= 40)
                {
                    sb.AppendLine("  ...(cap 40)");
                    break;
                }
            }

            if (n == 0)
            {
                sb.AppendLine("  (none)");
            }
        }
        catch (Exception ex)
        {
            sb.AppendLine("  skills err=" + RootMessage(ex));
        }
    }

    private static int ReadSkillAutoType(int skillId)
    {
        try
        {
            var cfgMgr = GetManagerInstance("ConfigManager");
            if (cfgMgr == null)
            {
                return -1;
            }

            var getTb = cfgMgr.GetType().GetMethod("GetTbSkillConfig",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            var tb = getTb?.Invoke(cfgMgr, null);
            if (tb == null)
            {
                return -1;
            }

            var get = tb.GetType().GetMethod("Get", new[] { typeof(int) })
                      ?? tb.GetType().GetMethod("get_Item", new[] { typeof(int) });
            var row = get?.Invoke(tb, new object[] { skillId });
            if (row == null)
            {
                return -1;
            }

            return Convert.ToInt32(GetMember(row, "AutoSkillType") ?? -1);
        }
        catch
        {
            return -1;
        }
    }

    private static string AppendSuperAiBattleUnits(StringBuilder sb, int playerIdx)
    {
        var keyParts = new StringBuilder();
        sb.AppendLine("units:");
        _superAiUnits.Clear();
        try
        {
            var container = FindType("BattleRoleContainer");
            var dic = container?.GetField("BattleRoleDic", BindingFlags.Public | BindingFlags.Static)
                      ?.GetValue(null) as IDictionary;
            if (dic == null)
            {
                sb.AppendLine("  (no BattleRoleDic)");
                _superAiUnitsKey = "0";
                return "0";
            }

            var allySide = playerIdx < 10;
            var selfUid = Convert.ToString(GetStaticMember("BattleDataHolder", "CurrentAccount")
                                          ?? GetStaticMember("PlayerDataHolder", "MainPlayerUid") ?? "") ?? "";
            string selfName;
            string selfJob;
            ReadSuperAiSelfIdentity(selfUid, out selfName, out selfJob);
            var enemyEstCount = 0;
            const int enemyEstMax = 10;
            foreach (DictionaryEntry kv in dic)
            {
                var role = kv.Value;
                if (role == null)
                {
                    continue;
                }

                var idx = Convert.ToInt32(GetMember(role, "Index") ?? kv.Key ?? -1);
                var roleData = GetMember(role, "RoleData");
                var ch = roleData != null ? GetMember(roleData, "Char") : null;
                if (ch == null)
                {
                    continue;
                }

                var name = Convert.ToString(GetMember(ch, "Name") ?? "") ?? "";
                var hp = Convert.ToInt32(GetMember(ch, "Hp") ?? 0);
                var maxHp = Convert.ToInt32(GetMember(ch, "MaxHp") ?? 0);
                var mp = Convert.ToInt32(GetMember(ch, "Mp") ?? 0);
                var maxMp = Convert.ToInt32(GetMember(ch, "MaxMp") ?? 0);
                var level = Convert.ToInt32(GetMember(ch, "Level") ?? 0);
                var animId = Convert.ToInt32(GetMember(ch, "AnimationId") ?? 0);
                var bc = Convert.ToInt64(GetMember(ch, "Bcflag") ?? 0);
                var status = FormatBcStatus(bc);
                var isPlayer = (bc & 4L) != 0; // BC_FLAG.PLAYER
                var side = idx < 10 ? "L" : "R";
                var mine = (allySide && idx < 10) || (!allySide && idx >= 10);
                var beUsed = Convert.ToString(GetMember(role, "beUsedSkill") ?? "") ?? "";
                var act2 = (bc & 0x400L) != 0 ? "2ACT" : "1ACT";
                var isSelf = idx == playerIdx && isPlayer;

                var snap = new SuperAiUnitSnap();
                snap.Idx = idx;
                snap.Mine = mine;
                snap.IsPlayer = isPlayer;
                snap.Name = name;
                snap.Level = level;
                snap.Hp = hp;
                snap.MaxHp = maxHp;
                snap.Mp = mp;
                snap.MaxMp = maxMp;
                snap.DetailOk = false;
                snap.Extra = "";

                sb.Append("  [").Append(side).Append(idx).Append(mine ? "*" : "")
                    .Append("] name=").Append(name);
                if (isSelf)
                {
                    sb.Append(" job=").Append(selfJob);
                    snap.Extra = "job=" + selfJob;
                }
                else if (isPlayer)
                {
                    sb.Append(" job=?");
                }

                sb.Append(isPlayer ? " (P)" : " (pet/mon)")
                    .Append(" lv=").Append(level)
                    .Append(" anim=").Append(animId)
                    .Append(" hp=").Append(hp).Append("/").Append(maxHp)
                    .Append(" mp=").Append(mp).Append("/").Append(maxMp)
                    .Append(" ").Append(status)
                    .Append(" ").Append(act2)
                    .Append(" beUsed=").Append(beUsed);
                if ((bc & 0x100000L) != 0)
                {
                    sb.Append(" RCV_UP");
                }

                sb.AppendLine();

                // 我方：系统面板属性（血蓝已用战斗值）；失败则仅一览血蓝
                if (mine)
                {
                    try
                    {
                        TryFillAllySystemDetail(ref snap, isSelf, isPlayer, selfUid, idx);
                    }
                    catch
                    {
                        // ignore
                    }
                }

                // 敌方非玩家：最多估10；查不到表静默
                if (!mine && !isPlayer && enemyEstCount < enemyEstMax
                    && maxHp > 0 && level > 0 && !string.IsNullOrEmpty(name))
                {
                    enemyEstCount++;
                    try
                    {
                        var est = BossStatEstimator.EstimateBest(name, animId, 0, level, maxHp, maxMp);
                        if (est.Ok)
                        {
                            snap.DetailOk = true;
                            snap.Rate = est.Rate;
                            snap.Atk = est.Atk;
                            snap.Def = est.Def;
                            snap.Agi = est.Agi;
                            snap.Spirit = est.Spirit;
                            snap.Rec = est.Rec;
                            snap.Extra = "drops=" + est.DropVit + "/" + est.DropStr + "/" + est.DropTgh
                                         + "/" + est.DropQuick + "/" + est.DropMagic + " pen=" + est.MatchPen;
                            var line = BossStatEstimator.FormatOneLine(est);
                            if (!string.IsNullOrEmpty(line))
                            {
                                sb.Append("    ").AppendLine(line);
                            }
                        }
                    }
                    catch
                    {
                        // ignore
                    }
                }

                _superAiUnits.Add(snap);
                keyParts.Append(idx).Append(':').Append(hp).Append('/').Append(mp).Append('/').Append(bc)
                    .Append(';');
            }

            // 敌方优先，再按站位 index
            _superAiUnits.Sort((a, b) =>
            {
                if (a.Mine != b.Mine)
                {
                    return a.Mine ? 1 : -1;
                }

                return a.Idx.CompareTo(b.Idx);
            });
        }
        catch (Exception ex)
        {
            sb.AppendLine("  units err=" + RootMessage(ex));
        }

        _superAiUnitsKey = keyParts.ToString();
        return _superAiUnitsKey;
    }

    /// <summary>5开我方：血蓝用战斗，攻防敏回复从 PlayerData/宠物面板读；读不到就算了。</summary>
    private static void TryFillAllySystemDetail(ref SuperAiUnitSnap snap, bool isSelf, bool isPlayer, string selfUid, int idx)
    {
        if (isPlayer)
        {
            string uid = null;
            if (isSelf)
            {
                uid = selfUid;
            }
            else
            {
                uid = FindUidByBattleIndex(idx);
            }

            if (string.IsNullOrEmpty(uid))
            {
                return;
            }

            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { uid });
            if (player == null)
            {
                return;
            }

            snap.Atk = Convert.ToInt32(GetMember(player, "AttackPower") ?? 0);
            snap.Def = Convert.ToInt32(GetMember(player, "DefencePower") ?? 0);
            snap.Agi = Convert.ToInt32(GetMember(player, "Agility") ?? 0);
            snap.Spirit = Convert.ToInt32(GetMember(player, "Spirit") ?? GetMember(player, "Mental") ?? 0);
            snap.Rec = Convert.ToInt32(GetMember(player, "Recovery") ?? 0);
            snap.DetailOk = snap.Atk > 0 || snap.Def > 0 || snap.Agi > 0;
            return;
        }

        // 己方宠：仅对照当前账号出战宠名字（避免扫全队过重）
        try
        {
            var getPlayer = FindType("PlayerDataHolder")?.GetMethod(
                "GetPlayerFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var player = getPlayer?.Invoke(null, new object[] { selfUid });
            if (player == null)
            {
                return;
            }

            var battlePetId = Convert.ToInt32(GetMember(player, "battlePetID") ?? -1);
            if (battlePetId < 0)
            {
                return;
            }

            var getPets = FindType("PlayerDataHolder")?.GetMethod(
                "GetPetDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
            var pets = getPets?.Invoke(null, new object[] { selfUid }) as IList;
            if (pets == null || battlePetId >= pets.Count || pets[battlePetId] == null)
            {
                return;
            }

            // 仅当名字对得上当前出战宠，避免错挂到别人宠
            var pd = GetMember(pets[battlePetId], "data") ?? pets[battlePetId];
            var pname = Convert.ToString(GetMember(pd, "Name") ?? "") ?? "";
            if (!string.IsNullOrEmpty(pname) && pname != snap.Name)
            {
                return;
            }

            snap.Atk = Convert.ToInt32(GetMember(pd, "AttackPower") ?? 0);
            snap.Def = Convert.ToInt32(GetMember(pd, "DefencePower") ?? 0);
            snap.Agi = Convert.ToInt32(GetMember(pd, "Agility") ?? 0);
            snap.Spirit = Convert.ToInt32(GetMember(pd, "Spirit") ?? GetMember(pd, "Mental") ?? 0);
            snap.Rec = Convert.ToInt32(GetMember(pd, "Recovery") ?? 0);
            snap.DetailOk = snap.Atk > 0 || snap.Def > 0;
            snap.Extra = "出战宠面板";
        }
        catch
        {
            // ignore
        }
    }

    private static string FindUidByBattleIndex(int idx)
    {
        try
        {
            var dic = FindType("BattleRoleContainer")
                ?.GetField("AccountIndexDic", BindingFlags.Public | BindingFlags.Static)
                ?.GetValue(null) as IDictionary;
            if (dic == null)
            {
                return null;
            }

            foreach (DictionaryEntry e in dic)
            {
                if (Convert.ToInt32(e.Value) == idx)
                {
                    return Convert.ToString(e.Key);
                }
            }
        }
        catch
        {
            // ignore
        }

        return null;
    }

    private static string FormatBcStatus(long bc)
    {
        // ABNORMAL_POISON=0x10 SLEEP=0x20 STONE=0x40 INEBRIETY=0x80 CONFUSION=0x100 FORGET=0x200 DEATH=2
        if ((bc & 2L) != 0)
        {
            return "死亡";
        }

        var parts = new List<string>();
        if ((bc & 0x10L) != 0) parts.Add("中毒");
        if ((bc & 0x20L) != 0) parts.Add("睡眠");
        if ((bc & 0x40L) != 0) parts.Add("石化");
        if ((bc & 0x80L) != 0) parts.Add("酒醉");
        if ((bc & 0x100L) != 0) parts.Add("混乱");
        if ((bc & 0x200L) != 0) parts.Add("遗忘");
        return parts.Count == 0 ? "正常" : string.Join("+", parts.ToArray());
    }

    private static void AddScriptColButton(
        Type rtType, string name, string id, float x, float y,
        float r, float g, float b, string label, Action onClick)
    {
        var go = CreateUiChild(_bodyRoot, name, rtType);
        SetAnchoredTop(RequireRect(go, id), x, y, 250f, 38f);
        var img = AddComp(go, "UnityEngine.UI.Image");
        SetColor(img, r, g, b, 1f);
        var lab = CreateUiChild(go, "L", rtType);
        StretchFull(RequireRect(lab, id + "l"));
        SetText(AddText(lab), label, 14);
        BindButton(go, img, onClick);
    }

