    private static string FormatBanshanTestStatus()
    {
        if (!_banshanTestActive)
        {
            return "半山测试: 未启动  卵→60275(20,19) 荷特普(21,19) →1530 循环";
        }

        return "半山测试: 第" + _banshanTestRound + "轮 "
               + BanshanTestPhaseName(_banshanTestPhase) + "  " + (_banshanTestNote ?? "")
               + " 雨格=" + _banshanTestRainBagSlot;
    }

    private static string BanshanTestPhaseName(int phase)
    {
        switch (phase)
        {
            case BanshanTestPhaseUseEgg: return "用卵";
            case BanshanTestPhaseWaitMapEgg: return "等进图";
            case BanshanTestPhaseWaitAfterMap: return "进图后等1秒";
            case BanshanTestPhaseMove: return "走路点";
            case BanshanTestPhaseRainEnsure: return "查冥界之雨";
            case BanshanTestPhaseRainBankWait: return "个人仓取雨";
            case BanshanTestPhaseRainBankDelay: return "取出后0.5秒";
            case BanshanTestPhaseTalk: return "点NPC";
            case BanshanTestPhaseStoreRain: return "对话中盲存雨";
            case BanshanTestPhaseStoreDelay: return "存入后0.5秒";
            case BanshanTestPhaseConfirm: return "点确定收尾";
            case BanshanTestPhaseWaitMapTalk: return "等传送图1530";
            case BanshanTestPhaseLoopWait: return "一轮结束等1秒";
            default: return "准备";
        }
    }

    private static void ToggleBanshanTest()
    {
        if (_banshanTestActive)
        {
            StopBanshanTest("已手动停止");
            return;
        }

        StartBanshanTest();
    }

    private static void StartBanshanTest()
    {
        if (!BanshanTestCheckTeamEggsOrTip())
        {
            return;
        }

        _banshanTestActive = true;
        _banshanTestRound = 1;
        _banshanTestPhase = BanshanTestPhaseUseEgg;
        _banshanTestDelayUntilMs = 0;
        _banshanTestLastNavMs = 0;
        _banshanTestLastLookMs = 0;
        _banshanTestStepTries = 0;
        _banshanTestRainBagSlot = -1;
        _banshanTestNote = "第1轮：全队有卵，队长使用…";
        Tip("半山测试已开启");
        WriteLog("banshan-test start");
        RefreshScriptTabIfVisible();
    }

    /// <summary>全队背包须有饥饿的死神之卵；不足 Tip「测试脚本条件不足」。</summary>
    private static bool BanshanTestCheckTeamEggsOrTip()
    {
        var uids = CollectTeamOrMultiUids();
        if (uids.Count == 0)
        {
            var cap = GetCaptainUid();
            if (!string.IsNullOrEmpty(cap))
            {
                uids.Add(cap);
            }
        }

        if (uids.Count == 0)
        {
            Tip("测试脚本条件不足");
            WriteLog("banshan-test no team uid");
            return false;
        }

        var fails = new List<string>();
        foreach (var uid in uids)
        {
            if (CountBagItemByKeyword(uid, BanshanTestEggKeyword) <= 0)
            {
                fails.Add(FormatBaptismPlayerShort(uid));
            }
        }

        if (fails.Count > 0)
        {
            Tip("测试脚本条件不足");
            WriteLog("banshan-test egg missing: " + string.Join(",", fails.ToArray()));
            return false;
        }

        return true;
    }

    private static void StopBanshanTest(string reason)
    {
        if (!_banshanTestActive)
        {
            Tip("半山测试：未在运行");
            return;
        }

        _banshanTestActive = false;
        _banshanTestPhase = BanshanTestPhaseIdle;
        _banshanTestNote = reason ?? "";
        WriteLog("banshan-test stop reason=" + reason);
        Tip("半山测试：" + (string.IsNullOrEmpty(reason) ? "已停止" : reason));
        RefreshScriptTabIfVisible();
    }

    private static string FormatCrystalChallengeStatus()
    {
        var phase = "就绪";
        switch (_crystalChallengePhase)
        {
            case CrystalChallengeHeal: phase = "法兰治疗"; break;
            case CrystalChallengeWaitInfo: phase = "查次数"; break;
            case CrystalChallengeWaitBattle: phase = "等进战"; break;
            case CrystalChallengeInBattle: phase = "战斗中"; break;
            case CrystalChallengeWaitTown: phase = "等回城"; break;
            case CrystalChallengeStore: phase = "存超银"; break;
        }

        var heal = "";
        if (_crystalChallengePhase == CrystalChallengeHeal && _floraHealActive)
        {
            heal = " " + FloraHealPhaseName(_floraHealPhase);
        }

        return "自动打挑战: 第" + _crystalChallengeRound + "次 "
               + CrystalChallengeLevelText() + " " + phase + heal
               + " 胜" + _crystalChallengeWins
               + "\n" + (_crystalChallengeNote ?? "");
    }

    private static void ToggleCrystalChallenge()
    {
        if (_crystalChallengeActive)
        {
            StopCrystalChallenge("已手动停止");
            return;
        }

        _crystalChallengeLevelId = CrystalChallengeDefaultDifficulty;
        StartCrystalChallenge();
    }

    /// <summary>中控指定水晶之地难度（1=50级 … 2=60级 … 6=100级）后开跑。成功以「已启动」开头。</summary>
    public static string TryStartCrystalChallengeFromControl(int difficulty)
    {
        if (difficulty < 1 || difficulty > CrystalChallengeDifficultyMax)
        {
            SetControlResult(false, "难度无效");
            return "难度无效";
        }

        if (_crystalChallengeActive)
        {
            SetControlResult(false, "自动打挑战已在运行");
            return "自动打挑战已在运行";
        }

        _crystalChallengeStartError = "";
        _crystalChallengeLevelId = difficulty;
        StartCrystalChallenge();
        if (_crystalChallengeActive)
        {
            SetControlResult(false, "进行中 " + CrystalChallengeLevelText());
            return "已启动 " + CrystalChallengeLevelText();
        }

        var err = _crystalChallengeStartError;
        if (string.IsNullOrEmpty(err))
        {
            err = _crystalChallengeNote;
        }

        if (string.IsNullOrEmpty(err))
        {
            err = "未启动";
        }

        SetControlResult(false, err);
        return err;
    }

    /// <summary>难度 1–6 → 「难度2 60级」。</summary>
    private static string CrystalChallengeLevelText()
    {
        var lv = 40 + _crystalChallengeLevelId * 10;
        return "难度" + _crystalChallengeLevelId + " " + lv + "级";
    }

    private static void StartCrystalChallenge()
    {
        if (_floraHealActive || _banshanTestActive || _warpWaitActive || _wildExActive || _fullScriptActive
            || _dojoRunActive || _dojoHellActive || _brawlSignActive || _moneyFarmActive
            || _junkDropActive || _openBookActive || _saveGoldActive)
        {
            _crystalChallengeStartError = "请先停其它脚本";
            Tip("请先停其它脚本");
            return;
        }

        if (IsInBattleNow())
        {
            _crystalChallengeStartError = "战斗中不能开始";
            Tip("自动打挑战：战斗中不能开始");
            return;
        }

        int floor;
        string floorName;
        int mapResId;
        TryGetCurrentMapInfo(out floor, out floorName, out mapResId);
        if (floor != CrystalChallengeCityFloor)
        {
            _crystalChallengeStartError = "须在主城地图1000（当前" + floor + "）";
            Tip("自动打挑战：" + _crystalChallengeStartError);
            return;
        }

        var teamNum = GetEscortTeamNum();
        if (teamNum != CrystalChallengeTeamSize)
        {
            _crystalChallengeStartError = "须5人队伍（当前" + teamNum + "）";
            Tip("自动打挑战：" + _crystalChallengeStartError);
            return;
        }

        if (!IsLocalCaptain())
        {
            _crystalChallengeStartError = "队长才可以确认进入";
            Tip("自动打挑战：" + _crystalChallengeStartError);
            return;
        }

        _crystalChallengeActive = true;
        _crystalChallengeRound = 1;
        _crystalChallengeWins = 0;
        _crystalChallengePrevInBattle = false;
        _crystalChallengeSawForceQuit = false;
        _crystalChallengeInfoSnap = null;
        _crystalChallengeNote = "先法兰治疗";
        WriteLog("crystal-challenge start " + CrystalChallengeLevelText());
        Tip("自动打挑战已开启（" + CrystalChallengeLevelText() + "）");
        CrystalChallengeBeginHeal();
        RefreshScriptTabIfVisible();
        RefreshScriptRunStatus();
    }

    private static void StopCrystalChallenge(string reason)
    {
        if (!_crystalChallengeActive)
        {
            Tip("自动打挑战：未在运行");
            return;
        }

        if (_crystalChallengePhase == CrystalChallengeStore && _crystalStoreUids != null
            && _crystalStoreUidPos >= 0 && _crystalStoreUidPos < _crystalStoreUids.Count)
        {
            TryDismissItemBankAfterStore(_crystalStoreUids[_crystalStoreUidPos]);
        }

        _crystalChallengeActive = false;
        _crystalChallengePhase = CrystalChallengeIdle;
        _crystalChallengeInfoSnap = null;
        _crystalStoreWaiting = false;
        _crystalStoreUids = null;
        _crystalChallengeNote = reason ?? "";
        TryCloseExistingUiPanel("BOSSChallengePanel");
        if (_floraHealActive)
        {
            StopFloraHeal("自动打挑战已停", false);
        }

        var stopText = string.IsNullOrEmpty(reason) ? "已停止" : reason;
        var challengeOk = stopText.IndexOf("没有次数", StringComparison.Ordinal) >= 0;
        SetControlResult(challengeOk, "挑战 " + stopText + " 胜" + _crystalChallengeWins);
        WriteLog("crystal-challenge stop reason=" + reason
                 + " round=" + _crystalChallengeRound + " wins=" + _crystalChallengeWins
                 + " " + CrystalChallengeLevelText());
        Tip((challengeOk ? "自动打挑战成功：" : "自动打挑战失败：") + stopText);
        RefreshScriptTabIfVisible();
        RefreshScriptRunStatus();
    }

    private static void CrystalChallengeBeginHeal()
    {
        _crystalChallengePhase = CrystalChallengeHeal;
        _crystalChallengeNote = "法兰治疗";
        if (_floraHealActive)
        {
            return;
        }

        StartFloraHeal(false);
        if (!_floraHealActive)
        {
            StopCrystalChallenge("法兰治疗未能启动");
        }
    }

    /// <summary>治疗结束后：常规模式 + AI战斗 + 官方自动战斗（不是 AI百人），再查次数并挑战。</summary>
    private static void CrystalChallengePrepareCombat()
    {
        if (_superAiDojoMode)
        {
            _superAiDojoMode = false;
            WriteLog("crystal-challenge clear AI百人");
        }

        if (_battleMode != ModeNormal)
        {
            SelectBattleMode(ModeNormal);
        }

        if (!_superAiActive && IsSuperAiModeAllowed(_battleMode))
        {
            StartSuperAi();
        }

        EnsureOfficialAutoBattleOn("自动打挑战", "自动打挑战：已打开自动战斗");
        WriteLog("crystal-challenge combat mode=" + _battleMode + " ai=" + _superAiActive);
    }

    private static void CrystalChallengeBeginFetch(bool thenHeal)
    {
        _crystalChallengePhase = CrystalChallengeWaitInfo;
        _crystalChallengeFetchThenHeal = thenHeal;
        _crystalChallengeSinceMs = NowMs();
        _crystalChallengeNote = thenHeal ? "战胜，查剩余次数" : "查水晶之地次数";
        var uid = GetCaptainUid();
        try
        {
            if (!string.IsNullOrEmpty(uid))
            {
                SetStaticMember("PlayerDataHolder", "SelectPlayerUid", uid);
            }
        }
        catch
        {
            // ignore
        }

        // 打开挑战后第一页就是水晶，不要再点切页。切页回调会再开一层子界面，叠住后就打不开第二次。
        // 已经开着就复用，只发一次「获取数据」。
        if (!IsUiPanelLikelyOpen("BOSSChallengePanel"))
        {
            TryOpenUiPanelBare("BOSSChallengePanel");
        }

        object info;
        int dungeonId;
        int remain;
        _crystalChallengeInfoSnap = TryReadCrystalChallengeInfo(out info, out dungeonId, out remain) ? info : null;
        if (!TrySendCrystalAndSwMsg("获取数据", CrystalChallengeDungeonId, 0, uid))
        {
            StopCrystalChallenge("获取水晶数据失败");
        }
    }

    private static void CrystalChallengeOnInfo(int remain)
    {
        WriteLog("crystal-challenge remain=" + remain + " thenHeal=" + _crystalChallengeFetchThenHeal);
        if (remain <= 0)
        {
            StopCrystalChallenge("没有次数了");
            return;
        }

        if (_crystalChallengeFetchThenHeal)
        {
            TryCloseExistingUiPanel("BOSSChallengePanel");
            _crystalChallengeRound++;
            CrystalChallengeBeginHeal();
            RefreshScriptRunStatus();
            return;
        }

        int floor;
        string floorName;
        int mapResId;
        TryGetCurrentMapInfo(out floor, out floorName, out mapResId);
        if (floor != CrystalChallengeCityFloor)
        {
            StopCrystalChallenge("不在主城（当前" + floor + "）");
            return;
        }

        var teamNum = GetEscortTeamNum();
        if (teamNum != CrystalChallengeTeamSize)
        {
            StopCrystalChallenge("队伍不是5人（当前" + teamNum + "）");
            return;
        }

        if (!IsLocalCaptain())
        {
            StopCrystalChallenge("队长才可以确认进入");
            return;
        }

        CrystalChallengePrepareCombat();
        var uid = GetCaptainUid();
        if (!TrySendCrystalAndSwMsg(
                "挑战BOSS", CrystalChallengeDungeonId, _crystalChallengeLevelId, uid))
        {
            StopCrystalChallenge("挑战发包失败");
            return;
        }

        TryCloseExistingUiPanel("BOSSChallengePanel");
        _crystalChallengePhase = CrystalChallengeWaitBattle;
        _crystalChallengeSinceMs = NowMs();
        _crystalChallengePrevInBattle = false;
        _crystalChallengeSawForceQuit = false;
        _crystalChallengeNote = "已发" + CrystalChallengeLevelText() + "，等进战";
        WriteLog("crystal-challenge enter dungeon=" + CrystalChallengeDungeonId
                 + " levelId=" + _crystalChallengeLevelId + " round=" + _crystalChallengeRound);
        RefreshScriptRunStatus();
    }

    /// <summary>战胜回城后：每个号的非绑定初级水晶石存超银。每格最多 3 次，还在就放弃。</summary>
    private static void CrystalChallengeBeginStore()
    {
        StopTaskNavigation(false);
        _crystalStoreUids = CollectTeamOrMultiUids();
        _crystalStoreGaveUp = new HashSet<string>();
        _crystalStoreUidPos = 0;
        _crystalStoreIndex = -1;
        _crystalStoreTries = 0;
        _crystalStoreWaiting = false;
        _crystalStoreSinceMs = NowMs();
        _crystalStorePut = 0;
        _crystalStoreSkip = 0;
        _crystalChallengePhase = CrystalChallengeStore;
        _crystalChallengeNote = "存非绑定初级水晶石到超银";
        WriteLog("crystal-challenge store begin uids=" + (_crystalStoreUids == null ? 0 : _crystalStoreUids.Count));
        RefreshScriptRunStatus();
    }

    private static void TickCrystalChallengeStore(long now)
    {
        if (_crystalStoreUids == null)
        {
            _crystalStoreUids = CollectTeamOrMultiUids();
        }

        if (_crystalStoreGaveUp == null)
        {
            _crystalStoreGaveUp = new HashSet<string>();
        }

        if (_crystalStoreWaiting)
        {
            if (now - _crystalStoreSinceMs < CrystalChallengeStoreWaitMs)
            {
                _crystalChallengeNote = FormatCrystalChallengeStoreNote();
                RefreshScriptRunStatus();
                return;
            }

            var uid = _crystalStoreUids[_crystalStoreUidPos];
            if (CrystalChallengeSlotStillStone(uid, _crystalStoreIndex))
            {
                if (_crystalStoreTries >= CrystalChallengeStoreMaxTries)
                {
                    _crystalStoreSkip++;
                    _crystalStoreGaveUp.Add(uid + "#" + _crystalStoreIndex);
                    WriteLog("crystal store give up uid尾" + TailUid(uid)
                             + " idx=" + _crystalStoreIndex + " tries=" + _crystalStoreTries);
                    _crystalStoreWaiting = false;
                    _crystalStoreIndex = -1;
                }
                else
                {
                    CrystalChallengeSendStore(uid, _crystalStoreIndex, _crystalStoreTries + 1);
                    _crystalStoreTries++;
                    _crystalStoreSinceMs = now;
                    _crystalChallengeNote = FormatCrystalChallengeStoreNote();
                    RefreshScriptRunStatus();
                    return;
                }
            }
            else
            {
                _crystalStorePut++;
                WriteLog("crystal store ok uid尾" + TailUid(uid)
                         + " idx=" + _crystalStoreIndex + " try=" + _crystalStoreTries);
                _crystalStoreWaiting = false;
                _crystalStoreIndex = -1;
            }
        }

        while (_crystalStoreUidPos < _crystalStoreUids.Count)
        {
            var uid = _crystalStoreUids[_crystalStoreUidPos];
            int idx;
            if (TryFindCrystalChallengeStone(uid, out idx))
            {
                CrystalChallengeSendStore(uid, idx, 1);
                _crystalStoreIndex = idx;
                _crystalStoreTries = 1;
                _crystalStoreWaiting = true;
                _crystalStoreSinceMs = now;
                _crystalChallengeNote = FormatCrystalChallengeStoreNote();
                RefreshScriptRunStatus();
                return;
            }

            TryDismissItemBankAfterStore(uid);
            _crystalStoreUidPos++;
        }

        WriteLog("crystal store done put=" + _crystalStorePut + " giveup=" + _crystalStoreSkip);
        _crystalChallengeNote = "超银存入" + _crystalStorePut + " 放弃" + _crystalStoreSkip;
        _crystalStoreWaiting = false;
        _crystalStoreUids = null;
        CrystalChallengeBeginFetch(true);
    }

    private static string FormatCrystalChallengeStoreNote()
    {
        var n = _crystalStoreUids == null ? 0 : _crystalStoreUids.Count;
        var who = Math.Min(_crystalStoreUidPos + 1, Math.Max(n, 1));
        return "存超银 号" + who + "/" + n
               + " 格" + _crystalStoreIndex
               + " 第" + _crystalStoreTries + "/" + CrystalChallengeStoreMaxTries + "次"
               + " 已存" + _crystalStorePut + " 放弃" + _crystalStoreSkip;
    }

    private static void CrystalChallengeSendStore(string uid, int index, int tryNo)
    {
        TryOpenRemoteAccountItemBank(uid);
        if (!TrySendAccountBankPutItems(uid, new List<int> { index }))
        {
            WriteLog("crystal store send fail uid尾" + TailUid(uid) + " idx=" + index + " try=" + tryNo);
            return;
        }

        WriteLog("crystal store send uid尾" + TailUid(uid) + " idx=" + index + " try=" + tryNo);
    }

    private static bool TryFindCrystalChallengeStone(string uid, out int index)
    {
        index = -1;
        var items = GetItemDatasFromUid(uid);
        if (items == null)
        {
            return false;
        }

        var start = Math.Min(8, items.Count);
        for (var i = start; i < items.Count; i++)
        {
            var item = items[i];
            if (item == null || Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
            {
                continue;
            }

            var data = GetMember(item, "data");
            if (!IsUnboundBeginnerCrystal(data))
            {
                continue;
            }

            var idx = Convert.ToInt32(GetMember(data, "Index") ?? i);
            if (_crystalStoreGaveUp != null && _crystalStoreGaveUp.Contains(uid + "#" + idx))
            {
                continue;
            }

            index = idx;
            return true;
        }

        return false;
    }

    /// <summary>该格是否还是初级水晶石。读不到背包时当作还在，避免当成已经存进。</summary>
    private static bool CrystalChallengeSlotStillStone(string uid, int index)
    {
        var items = GetItemDatasFromUid(uid);
        if (items == null)
        {
            return true;
        }

        var start = Math.Min(8, items.Count);
        for (var i = start; i < items.Count; i++)
        {
            var item = items[i];
            if (item == null || Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
            {
                continue;
            }

            var data = GetMember(item, "data");
            if (data == null || !ItemDataMatchesKeyword(data, CrystalChallengeStoneKeyword))
            {
                continue;
            }

            var idx = Convert.ToInt32(GetMember(data, "Index") ?? i);
            if (idx == index)
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsUnboundBeginnerCrystal(object data)
    {
        if (data == null || !ItemDataMatchesKeyword(data, CrystalChallengeStoneKeyword))
        {
            return false;
        }

        var flg = Convert.ToInt32(GetMember(data, "Flg") ?? 0);
        return (flg & CrystalChallengeBindFlag) == 0;
    }

    private static void TickCrystalChallenge()
    {
        if (!_crystalChallengeActive)
        {
            return;
        }

        var now = NowMs();
        if (_crystalChallengePhase == CrystalChallengeStore)
        {
            TickCrystalChallengeStore(now);
            return;
        }

        if (_crystalChallengePhase == CrystalChallengeHeal)
        {
            if (_floraHealActive)
            {
                _crystalChallengeNote = "法兰治疗中 " + FloraHealPhaseName(_floraHealPhase);
                RefreshScriptRunStatus();
                return;
            }

            if (!_floraHealLastOk)
            {
                StopCrystalChallenge("法兰治疗失败");
                return;
            }

            CrystalChallengeBeginFetch(false);
            return;
        }

        if (_crystalChallengePhase == CrystalChallengeWaitInfo)
        {
            object info;
            int dungeonId;
            int remain;
            var got = TryReadCrystalChallengeInfo(out info, out dungeonId, out remain);
            if (got && dungeonId == CrystalChallengeDungeonId
                && !ReferenceEquals(info, _crystalChallengeInfoSnap))
            {
                CrystalChallengeOnInfo(remain);
                return;
            }

            if (now - _crystalChallengeSinceMs >= CrystalChallengeInfoWaitMs)
            {
                if (got && dungeonId == CrystalChallengeDungeonId)
                {
                    CrystalChallengeOnInfo(remain);
                    return;
                }

                WriteLog("crystal-challenge info timeout got=" + got
                         + " dung=" + dungeonId + " remain=" + remain
                         + " child=" + (FindCrystalAndSwPanel() != null));
                StopCrystalChallenge("没读到水晶之地次数");
            }

            return;
        }

        var inBattle = IsInBattleNow();
        if (_crystalChallengePhase == CrystalChallengeWaitBattle || _crystalChallengePhase == CrystalChallengeInBattle)
        {
                if (inBattle)
                {
                    if (!_crystalChallengePrevInBattle)
                    {
                        _crystalChallengeSawForceQuit = false;
                        EnsureOfficialAutoBattleOn("自动打挑战进战", "自动打挑战：已打开自动战斗");
                        WriteLog("crystal-challenge battle enter round=" + _crystalChallengeRound);
                    }

                _crystalChallengePhase = CrystalChallengeInBattle;
                _crystalChallengePrevInBattle = true;
                if (IsForceQuitBattleNow())
                {
                    _crystalChallengeSawForceQuit = true;
                }

                _crystalChallengeNote = "战斗中";
                RefreshScriptRunStatus();
                return;
            }

            if (_crystalChallengePrevInBattle || _crystalChallengePhase == CrystalChallengeInBattle)
            {
                _crystalChallengePrevInBattle = false;
                if (_crystalChallengeSawForceQuit || IsForceQuitBattleNow())
                {
                    StopCrystalChallenge("战败");
                    return;
                }

                _crystalChallengeWins++;
                _crystalChallengeNote = "战胜，等回到法兰再查次数";
                WriteLog("crystal-challenge win wins=" + _crystalChallengeWins);
                _crystalChallengePhase = CrystalChallengeWaitTown;
                _crystalChallengeSinceMs = now;
                _crystalChallengePrevInBattle = false;
                RefreshScriptRunStatus();
                return;
            }

            TryConfirmMessageBoxPanel();
            if (now - _crystalChallengeSinceMs >= CrystalChallengeEnterWaitMs)
            {
                StopCrystalChallenge("未进入水晶挑战");
                return;
            }

            _crystalChallengeNote = "等进战…";
            RefreshScriptRunStatus();
            return;
        }

        if (_crystalChallengePhase == CrystalChallengeWaitTown)
        {
            if (inBattle)
            {
                _crystalChallengePhase = CrystalChallengeInBattle;
                _crystalChallengePrevInBattle = true;
                _crystalChallengeNote = "战斗中";
                RefreshScriptRunStatus();
                return;
            }

            int townFloor;
            string townName;
            int townRes;
            TryGetCurrentMapInfo(out townFloor, out townName, out townRes);
            var waited = now - _crystalChallengeSinceMs;
            if (townFloor == CrystalChallengeCityFloor && waited >= 1500)
            {
                CrystalChallengeBeginStore();
                return;
            }

            if (waited >= 12000)
            {
                WriteLog("crystal-challenge town wait give up floor=" + townFloor);
                CrystalChallengeBeginStore();
                return;
            }

            _crystalChallengeNote = "战胜，等回法兰再查次数 现" + townFloor + " " + townName;
            RefreshScriptRunStatus();
        }
    }

    private static object FindCrystalAndSwPanel()
    {
        var parent = GetUiPanel("BOSSChallengePanel");
        if (parent != null)
        {
            var child = GetMember(parent, "m_CrystalAndSwPanel");
            if (child != null)
            {
                return child;
            }
        }

        return GetUiPanel("CrystalAndSwPanel");
    }

    private static bool TryReadCrystalChallengeInfo(out object info, out int dungeonId, out int remain)
    {
        info = null;
        dungeonId = 0;
        remain = -1;
        try
        {
            var panel = FindCrystalAndSwPanel();
            if (panel == null)
            {
                return false;
            }

            info = GetMember(panel, "m_Info");
            if (info == null)
            {
                return false;
            }

            dungeonId = Convert.ToInt32(GetMember(info, "DungeonId") ?? GetMember(info, "dungeonId_") ?? 0);
            remain = Convert.ToInt32(GetMember(info, "TodayRemain") ?? GetMember(info, "todayRemain_") ?? -1);
            return dungeonId > 0;
        }
        catch (Exception ex)
        {
            WriteLog("crystal-challenge read info EX " + RootMessage(ex));
            return false;
        }
    }

    private static bool TrySendCrystalAndSwMsg(string type, int dungeonId, int layerId, string uid)
    {
        try
        {
            if (string.IsNullOrEmpty(uid))
            {
                return false;
            }

            var mgr = GetManagerInstance("BountyOfferedManager");
            if (mgr == null)
            {
                return false;
            }

            var send = mgr.GetType().GetMethod(
                "SendCrystalAndSwMsg",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                null,
                new[] { typeof(string), typeof(int), typeof(int), typeof(string) },
                null);
            if (send == null)
            {
                return false;
            }

            send.Invoke(mgr, new object[] { type, dungeonId, layerId, uid });
            WriteLog("crystal-challenge send " + type + " dung=" + dungeonId + " layer=" + layerId);
            return true;
        }
        catch (Exception ex)
        {
            WriteLog("crystal-challenge send EX " + RootMessage(ex));
            return false;
        }
    }

    private static void TickBanshanTest()
    {
        if (!_banshanTestActive)
        {
            return;
        }

        var now = NowMs();
        if (_banshanTestDelayUntilMs > 0 && now < _banshanTestDelayUntilMs)
        {
            return;
        }

        var uid = GetCaptainUid();
        if (string.IsNullOrEmpty(uid))
        {
            uid = GetMainPlayerUidSafe();
        }

        if (string.IsNullOrEmpty(uid))
        {
            StopBanshanTest("无队长/主控");
            return;
        }

        int floor;
        string floorName;
        int mapRes;
        TryGetCurrentMapInfo(out floor, out floorName, out mapRes);
        int x;
        int y;
        TryGetPlayerXY(out x, out y);

        switch (_banshanTestPhase)
        {
            case BanshanTestPhaseUseEgg:
                if (!TryUseBagItemByKeyword(uid, BanshanTestEggKeyword))
                {
                    StopBanshanTest("队长使用卵失败");
                    return;
                }

                _banshanTestPhase = BanshanTestPhaseWaitMapEgg;
                _banshanTestNote = "已用卵，等进图" + BanshanTestMapAfterEgg;
                _banshanTestStepTries = 0;
                WriteLog("banshan-test used egg");
                break;

            case BanshanTestPhaseWaitMapEgg:
                if (floor == BanshanTestMapAfterEgg)
                {
                    _banshanTestPhase = BanshanTestPhaseWaitAfterMap;
                    _banshanTestDelayUntilMs = now + BanshanTestMapWaitMs;
                    _banshanTestNote = "已进图，等1秒";
                    WriteLog("banshan-test entered map " + floor);
                    return;
                }

                _banshanTestStepTries++;
                if (_banshanTestStepTries > 40)
                {
                    StopBanshanTest("等进图超时 现图" + floor);
                    return;
                }

                _banshanTestNote = "等进图" + BanshanTestMapAfterEgg + " 现" + floor;
                _banshanTestDelayUntilMs = now + 400;
                break;

            case BanshanTestPhaseWaitAfterMap:
                _banshanTestPhase = BanshanTestPhaseMove;
                _banshanTestLastNavMs = 0;
                _banshanTestNote = "去(" + BanshanTestMoveX + "," + BanshanTestMoveY + ")";
                break;

            case BanshanTestPhaseMove:
                if (floor != BanshanTestMapAfterEgg)
                {
                    _banshanTestPhase = BanshanTestPhaseWaitMapEgg;
                    _banshanTestNote = "掉图了，再等进图";
                    break;
                }

                if (Math.Abs(x - BanshanTestMoveX) <= 1 && Math.Abs(y - BanshanTestMoveY) <= 1)
                {
                    _banshanTestPhase = BanshanTestPhaseRainEnsure;
                    _banshanTestStepTries = 0;
                    _banshanTestNote = "已到点，查冥界之雨";
                    break;
                }

                if (_banshanTestLastNavMs <= 0 || now - _banshanTestLastNavMs >= BanshanTestNavRetryMs)
                {
                    string how;
                    if (TryNavigateTo(BanshanTestMapAfterEgg, BanshanTestMoveX, BanshanTestMoveY, out how)
                        || TryWalkTo(BanshanTestMoveX, BanshanTestMoveY))
                    {
                        _banshanTestLastNavMs = now;
                        _banshanTestNote = "走路 " + how + " 现" + x + "," + y;
                    }
                    else
                    {
                        _banshanTestLastNavMs = now;
                        _banshanTestNote = "导航失败 现" + x + "," + y;
                    }
                }
                else
                {
                    _banshanTestNote = "走路中 现" + x + "," + y;
                }

                break;

            case BanshanTestPhaseRainEnsure:
                if (CountBagItemByKeyword(uid, BanshanTestRainKeyword) > 0)
                {
                    _banshanTestRainBagSlot = FindBagItemSlotByKeyword(uid, BanshanTestRainKeyword);
                    _banshanTestPhase = BanshanTestPhaseTalk;
                    _banshanTestLastLookMs = 0;
                    _banshanTestStepTries = 0;
                    _banshanTestNote = "背包已有雨，记格=" + _banshanTestRainBagSlot + "，点NPC";
                    WriteLog("banshan-test rain in bag slot=" + _banshanTestRainBagSlot);
                    break;
                }

                ClearPersonalBankItemCache(uid);
                TryOpenRemotePersonalItemBank(uid);
                _banshanTestPhase = BanshanTestPhaseRainBankWait;
                _banshanTestStepTries = 0;
                _banshanTestDelayUntilMs = now + 400;
                _banshanTestNote = "背包无雨，开个人仓库…";
                break;

            case BanshanTestPhaseRainBankWait:
                {
                    var bank = CountPersonalBankItemByKeyword(uid, BanshanTestRainKeyword);
                    if (bank < 0)
                    {
                        _banshanTestStepTries++;
                        if (_banshanTestStepTries > 25)
                        {
                            TryDismissItemBankAfterStore(uid);
                            StopBanshanTest("读个人仓库超时");
                            return;
                        }

                        if (_banshanTestStepTries % 5 == 0)
                        {
                            TryOpenRemotePersonalItemBank(uid);
                        }

                        _banshanTestNote = "等个人仓库列表…";
                        _banshanTestDelayUntilMs = now + 300;
                        return;
                    }

                    if (bank <= 0)
                    {
                        TryDismissItemBankAfterStore(uid);
                        StopBanshanTest("个人仓库也没有冥界之雨");
                        return;
                    }

                    int bankIdx;
                    if (!TryFindPersonalBankIndexByKeyword(uid, BanshanTestRainKeyword, out bankIdx)
                        || !TrySendPersonalBankTakeNum(uid, bankIdx, 1))
                    {
                        TryDismissItemBankAfterStore(uid);
                        StopBanshanTest("个人仓取出冥界之雨失败");
                        return;
                    }

                    TryDismissItemBankAfterStore(uid);
                    _banshanTestPhase = BanshanTestPhaseRainBankDelay;
                    _banshanTestDelayUntilMs = now + BanshanTestBankOpDelayMs;
                    _banshanTestNote = "已从个人仓取雨，等0.5秒";
                    WriteLog("banshan-test personal bank take rain idx=" + bankIdx);
                    return;
                }

            case BanshanTestPhaseRainBankDelay:
                _banshanTestRainBagSlot = FindBagItemSlotByKeyword(uid, BanshanTestRainKeyword);
                if (_banshanTestRainBagSlot < 0 || CountBagItemByKeyword(uid, BanshanTestRainKeyword) <= 0)
                {
                    StopBanshanTest("取出后背包仍无冥界之雨");
                    return;
                }

                _banshanTestPhase = BanshanTestPhaseTalk;
                _banshanTestLastLookMs = 0;
                _banshanTestStepTries = 0;
                _banshanTestNote = "雨已入包 slot=" + _banshanTestRainBagSlot + "，点NPC";
                WriteLog("banshan-test rain bag slot=" + _banshanTestRainBagSlot);
                break;

            case BanshanTestPhaseTalk:
                if (IsDialoguePanelOpen())
                {
                    _banshanTestPhase = BanshanTestPhaseStoreRain;
                    _banshanTestNote = "对话已开，盲存冥界之雨";
                    break;
                }

                if (_banshanTestLastLookMs > 0 && now - _banshanTestLastLookMs < BanshanTestNpcLookRetryMs)
                {
                    return;
                }

                _banshanTestLastLookMs = now;
                _banshanTestStepTries++;
                if (_banshanTestStepTries > 20)
                {
                    StopBanshanTest("点NPC失败");
                    return;
                }

                if (TryLookNpcAt(BanshanTestNpcX, BanshanTestNpcY)
                    || TryLookNpcByNameNear(BanshanTestNpcName, BanshanTestNpcX, BanshanTestNpcY))
                {
                    _banshanTestNote = "已点NPC，等对话";
                }
                else
                {
                    _banshanTestNote = "未找到NPC " + BanshanTestNpcName + " @"
                                       + BanshanTestNpcX + "," + BanshanTestNpcY;
                }

                break;

            case BanshanTestPhaseStoreRain:
                if (!IsDialoguePanelOpen())
                {
                    _banshanTestPhase = BanshanTestPhaseTalk;
                    _banshanTestNote = "对话关了，再点NPC";
                    break;
                }

                if (CountBagItemByKeyword(uid, BanshanTestRainKeyword) > 0)
                {
                    if (!StoreBagItemsToPersonalBank(uid, BanshanTestRainKeyword))
                    {
                        StopBanshanTest("盲存冥界之雨失败");
                        return;
                    }

                    _banshanTestPhase = BanshanTestPhaseStoreDelay;
                    _banshanTestDelayUntilMs = now + BanshanTestBankOpDelayMs;
                    _banshanTestNote = "已盲存，等0.5秒";
                    WriteLog("banshan-test blind stored rain");
                    return;
                }

                // 已无雨（可能上次存过）→ 直接点确定
                _banshanTestPhase = BanshanTestPhaseConfirm;
                _banshanTestNote = "包里已无雨，点确定";
                break;

            case BanshanTestPhaseStoreDelay:
                _banshanTestPhase = BanshanTestPhaseConfirm;
                _banshanTestNote = "开始点确定直到对话结束";
                break;

            case BanshanTestPhaseConfirm:
                if (!IsDialoguePanelOpen())
                {
                    _banshanTestPhase = BanshanTestPhaseWaitMapTalk;
                    _banshanTestStepTries = 0;
                    _banshanTestNote = "对话结束，等进图" + BanshanTestMapAfterTalk;
                    WriteLog("banshan-test dialogue closed");
                    break;
                }

                TryAutoPickDialogue();
                _banshanTestNote = "点确定中…";
                break;

            case BanshanTestPhaseWaitMapTalk:
                if (floor == BanshanTestMapAfterTalk)
                {
                    _banshanTestPhase = BanshanTestPhaseLoopWait;
                    _banshanTestDelayUntilMs = now + BanshanTestRoundGapMs;
                    _banshanTestNote = "第" + _banshanTestRound + "轮完成→1530，等1秒再开";
                    Tip("半山测试：第" + _banshanTestRound + "轮结束，1秒后继续");
                    WriteLog("banshan-test round done n=" + _banshanTestRound + " map=" + floor);
                    return;
                }

                _banshanTestStepTries++;
                if (_banshanTestStepTries > 50)
                {
                    StopBanshanTest("等传送图超时 现图" + floor);
                    return;
                }

                _banshanTestNote = "等图" + BanshanTestMapAfterTalk + " 现" + floor;
                _banshanTestDelayUntilMs = now + 400;
                break;

            case BanshanTestPhaseLoopWait:
                if (!BanshanTestCheckTeamEggsOrTip())
                {
                    _banshanTestActive = false;
                    _banshanTestPhase = BanshanTestPhaseIdle;
                    _banshanTestNote = "测试脚本条件不足";
                    WriteLog("banshan-test stop: eggs missing between rounds");
                    RefreshScriptTabIfVisible();
                    return;
                }

                _banshanTestRound++;
                _banshanTestRainBagSlot = -1;
                _banshanTestStepTries = 0;
                _banshanTestLastNavMs = 0;
                _banshanTestLastLookMs = 0;
                _banshanTestDelayUntilMs = 0;
                _banshanTestPhase = BanshanTestPhaseUseEgg;
                _banshanTestNote = "第" + _banshanTestRound + "轮：队长用卵…";
                WriteLog("banshan-test next round=" + _banshanTestRound);
                break;
        }
    }

    private static string FormatDojoRunStatus()
    {
        if (!_dojoRunActive)
        {
            return "百人道场: 未启动 目标层" + GetDojoTargetLayer()
                   + "\n开跑先查一次血，低血先治疗再跑；切常规并开AI百人；进9201已达或超过目标则退出道场并停；战败暂停；低血退出→法兰治疗→回城点6重跑";
        }

        var layerPart = _dojoRunLayer > 0 ? ("第" + _dojoRunLayer + "道场") : "层?";
        return "百人道场: " + DojoRunPhaseName(_dojoRunPhase)
               + " " + layerPart + "/" + GetDojoTargetLayer()
               + " 已过" + _dojoRunFloorClear + "层\n"
               + (_dojoRunNote ?? "");
    }

    private static string DojoRunPhaseName(int phase)
    {
        switch (phase)
        {
            case DojoRunReturn: return "回城点6";
            case DojoRunWaitReturn: return "等回城(233,78)";
            case DojoRunNavWarp: return "走(238,64)切图";
            case DojoRunWaitWarp: return "等切1154";
            case DojoRunNavOpen: return "走(39,31)";
            case DojoRunTalkOpen: return "对话开面板";
            case DojoRunEnter: return "点进入道场";
            case DojoRunWaitFloor: return "等进道场图";
            case DojoRunNav: return "走到(15,10)";
            case DojoRunTalk: return "对话道场NPC";
            case DojoRunWaitBattle: return "等进战";
            case DojoRunInBattle: return "战斗中";
            case DojoRunAfterBattle: return "战后等5秒";
            case DojoRunExit: return "退出道场";
            case DojoRunWaitExit: return "等退到1154";
            case DojoRunWaitFloraHeal: return "法兰治疗";
            default: return "就绪";
        }
    }

    private static int GetDojoTargetLayer()
    {
        return _dojoRunTargetLayer > 0 ? _dojoRunTargetLayer : DojoDefaultTargetLayer;
    }

    private static void ReadDojoTargetLayerFromUi()
    {
        try
        {
            if (_dojoRunTargetLayerInput != null)
            {
                var t = ReadInputFieldText(_dojoRunTargetLayerInput);
                if (!string.IsNullOrEmpty(t))
                {
                    _dojoRunTargetLayerStr = t.Trim();
                }
            }
        }
        catch
        {
            // keep cached
        }

        int n;
        if (int.TryParse(_dojoRunTargetLayerStr, out n) && n > 0)
        {
            _dojoRunTargetLayer = n;
        }
        else
        {
            _dojoRunTargetLayer = DojoDefaultTargetLayer;
            _dojoRunTargetLayerStr = DojoDefaultTargetLayer.ToString();
        }
    }

    private static void ToggleDojoRun()
    {
        if (!EnableDojoRunScript)
        {
            Tip("百人道场脚本未开放（傻瓜包暂不带）");
            return;
        }

        if (_dojoRunActive)
        {
            StopDojoRun("手动停止");
            return;
        }

        StartDojoRun();
    }

    /// <summary>中控指定普通百人目标层后开跑。成功以「已启动」开头。</summary>
    public static string TryStartDojoFromControl(int layer)
    {
        if (layer < 1)
        {
            SetControlResult(false, "层数无效");
            return "层数无效";
        }

        if (_dojoRunActive)
        {
            SetControlResult(false, "百人已在运行");
            return "百人已在运行";
        }

        _dojoStartError = "";
        _dojoRunTargetLayer = layer;
        _dojoRunTargetLayerStr = layer.ToString();
        TrySetDojoLayerInput(_dojoRunTargetLayerInput, _dojoRunTargetLayerStr);
        StartDojoRun();
        if (_dojoRunActive)
        {
            SetControlResult(false, "进行中 百人目标" + GetDojoTargetLayer());
            return "已启动 目标层" + GetDojoTargetLayer();
        }

        var err = string.IsNullOrEmpty(_dojoStartError) ? "未启动" : _dojoStartError;
        SetControlResult(false, err);
        return err;
    }

    private static void StartDojoRun()
    {
        if (!EnableDojoRunScript)
        {
            _dojoStartError = "百人道场脚本未开放";
            Tip(_dojoStartError);
            return;
        }

        if (_floraHealActive || _banshanTestActive || _warpWaitActive || _wildExActive || _fullScriptActive
            || _dojoHellActive || _brawlSignActive || _moneyFarmActive || _crystalChallengeActive || _saveGoldActive)
        {
            _dojoStartError = "请先停其它脚本";
            Tip(_dojoStartError);
            return;
        }

        if (IsInBattleNow())
        {
            _dojoStartError = "战斗中不能启动百人道场";
            Tip(_dojoStartError);
            return;
        }

        var uid = GetMainPlayerUidSafe();
        if (string.IsNullOrEmpty(uid))
        {
            _dojoStartError = "未找到角色";
            Tip(_dojoStartError);
            return;
        }

        ReadDojoTargetLayerFromUi();
        SaveDojoLayerForLoginPhone(true);
        PrepareDojoRunCombat();
        TryEnsureDojoHighestBattlePets();
        TrySendLocalAutoBattle("停止挂机");
        StopTaskNavigation(false);
        _dojoRunActive = true;
        _dojoRunFloorClear = 0;
        _dojoRunLayer = 0;
        _dojoRunTalkPicked = false;
        _dojoRunOpenTalkPicked = false;
        _dojoRunSawForceQuit = false;
        _dojoRunPrevInBattle = false;
        _dojoRunExpectExitReenter = false;
        _dojoRunExitThenStop = false;
        _dojoRunAwaitPostBattleMap = false;
        _dojoRunDelayUntilMs = 0;
        _dojoRunLastNavMs = 0;
        _dojoRunLastLookMs = 0;
        _dojoRunLastEnterMs = 0;
        _dojoRunWarpWaitSinceMs = 0;
        _dojoRunReturnSinceMs = 0;
        _dojoRunExitSinceMs = 0;
        _dojoRunReturnTries = 0;
        _dojoRunExitTries = 0;

        int floor;
        string floorName;
        int mapResId;
        TryGetCurrentMapInfo(out floor, out floorName, out mapResId);
        RefreshDojoLayerFromName(floorName);
        string startHp;
        var startLowHp = DojoTeamOrPetHpBelowHalf(out startHp);
        if (IsInsideDojoMap(floor, floorName))
        {
            if (_dojoRunLayer > 0 && _dojoRunLayer >= GetDojoTargetLayer())
            {
                DojoRunBeginExitThenStop(
                    "第" + _dojoRunLayer + "道场已达或超过目标" + GetDojoTargetLayer() + "，退出并停止");
            }
            else if (startLowHp)
            {
                Tip("百人开跑低血，先退出治疗：" + startHp);
                DojoRunBeginExitForHeal("开跑低血(" + startHp + ")退出道场再治疗");
            }
            else
            {
                _dojoRunPhase = DojoRunNav;
                _dojoRunNote = "已在道场 " + FormatDojoLayerLabel() + "，去(15,10)";
            }
        }
        else if (startLowHp)
        {
            Tip("百人开跑低血，先治疗：" + startHp);
            DojoRunBeginFloraThenRestart("开跑低血(" + startHp + ")，先治疗再回城点6");
        }
        else if (floor == DojoWarpTargetFloor)
        {
            _dojoRunPhase = DojoRunNavOpen;
            _dojoRunLastNavMs = 0;
            _dojoRunNote = "已在1154，去(39,31)开面板";
        }
        else
        {
            DojoRunBeginReturn("不在道场，回城点6…");
        }

        Tip("百人道场脚本已启动（目标第" + GetDojoTargetLayer() + "层）");
        WriteLog("dojo-run start floor=" + floor + " name=" + floorName
                 + " layer=" + _dojoRunLayer + " target=" + GetDojoTargetLayer());
        RefreshScriptTabIfVisible();
        RefreshScriptRunStatus();
    }

    private static void StopDojoRun(string reason)
    {
        if (!_dojoRunActive && _dojoRunPhase == DojoRunIdle)
        {
            Tip("百人道场：未在运行");
            return;
        }

        var stopFlora = _dojoRunPhase == DojoRunWaitFloraHeal && _floraHealActive;
        _dojoRunActive = false;
        _dojoRunPhase = DojoRunIdle;
        _dojoRunExpectExitReenter = false;
        _dojoRunExitThenStop = false;
        _dojoRunAwaitPostBattleMap = false;
        _dojoRunNote = string.IsNullOrEmpty(reason) ? "已停止" : reason;
        var dojoOk = (_dojoRunNote ?? "").IndexOf("已达或超过目标", StringComparison.Ordinal) >= 0;
        SetControlResult(dojoOk, "百人 " + _dojoRunNote);
        StopTaskNavigation(false);
        if (stopFlora)
        {
            StopFloraHeal("百人已停止", false);
        }

        Tip((dojoOk ? "百人成功：" : "百人失败：") + _dojoRunNote + "（过" + _dojoRunFloorClear + "层）");
        WriteLog("dojo-run stop " + _dojoRunNote + " clears=" + _dojoRunFloorClear);
        RefreshScriptTabIfVisible();
        RefreshScriptRunStatus();
    }

    /// <summary>
    /// 百人/噩梦开跑或每轮回城前：本机每个角色把最高级宠物设为出战。
    /// 当前出战宠等级已经是最高则不发包。等级相同保留现有出战宠。
    /// </summary>
    private static void TryEnsureDojoHighestBattlePets()
    {
        if (!_dojoAutoHighestBattlePet)
        {
            return;
        }

        try
        {
            var petMgr = GetManagerInstance("PetManager");
            var change = petMgr?.GetType().GetMethod(
                "ChangePetStatus",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                null,
                new[] { typeof(string), typeof(int), typeof(int) },
                null);
            if (petMgr == null || change == null)
            {
                WriteLog("dojo-pet skip: ChangePetStatus missing");
                return;
            }

            var uids = CollectTeamOrMultiUids();
            var changed = 0;
            for (var i = 0; i < uids.Count; i++)
            {
                var uid = uids[i];
                int index;
                int level;
                string name;
                if (!TryPickDojoHighestBattlePet(uid, out index, out level, out name))
                {
                    continue;
                }

                change.Invoke(petMgr, new object[] { uid, index, DojoPetStatusBattle });
                changed++;
                WriteLog("dojo-pet set uid=" + uid + " index=" + index
                         + " lv=" + level + " " + name);
            }

            if (changed > 0)
            {
                Tip("百人出战宠：已设置 " + changed + " 个角色");
            }
        }
        catch (Exception ex)
        {
            WriteLog("dojo-pet EX: " + RootMessage(ex));
        }
    }

    /// <summary>返回需要改的槽位。当前出战已是最高级（含并列）则 false。</summary>
    private static bool TryPickDojoHighestBattlePet(
        string uid, out int index, out int level, out string name)
    {
        index = -1;
        level = -1;
        name = "";
        if (string.IsNullOrEmpty(uid))
        {
            return false;
        }

        var player = GetPlayer(uid);
        if (player == null)
        {
            WriteLog("dojo-pet skip no player uid=" + uid);
            return false;
        }

        var getPets = FindType("PlayerDataHolder")?.GetMethod(
            "GetPetDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic);
        var pets = getPets?.Invoke(null, new object[] { uid }) as IList;
        if (pets == null || pets.Count == 0)
        {
            WriteLog("dojo-pet skip no pets uid=" + uid);
            return false;
        }

        var battleId = Convert.ToInt32(GetMember(player, "battlePetID") ?? -1);
        var best = -1;
        var bestLv = -1;
        string bestName = "";
        var battleLv = -1;
        for (var i = 0; i < pets.Count; i++)
        {
            var pet = pets[i];
            if (pet == null)
            {
                continue;
            }

            if (Convert.ToInt32(GetMember(pet, "useFlag") ?? 0) != 1)
            {
                continue;
            }

            var data = GetMember(pet, "data") ?? pet;
            var lv = Convert.ToInt32(GetMember(data, "Level") ?? GetMember(data, "Lv") ?? 0);
            var petName = Convert.ToString(GetMember(data, "Name") ?? GetMember(data, "FreeName") ?? "") ?? "";
            if (i == battleId)
            {
                battleLv = lv;
            }

            if (lv > bestLv)
            {
                bestLv = lv;
                best = i;
                bestName = petName;
            }
        }

        if (best < 0)
        {
            WriteLog("dojo-pet skip empty uid=" + uid);
            return false;
        }

        if (battleId == best || (battleId >= 0 && battleLv >= 0 && battleLv == bestLv))
        {
            WriteLog("dojo-pet already uid=" + uid + " battle=" + battleId + " lv=" + battleLv);
            return false;
        }

        index = best;
        level = bestLv;
        name = bestName;
        return true;
    }

    /// <summary>开跑：战斗切常规，并打开 AI百人（未开 AI战斗则一并启动）。</summary>
    private static void PrepareDojoRunCombat()
    {
