        SetControlResult(true, "已存超银 n=" + idxs.Count);
        Tip("交易超银存：已存" + idxs.Count + "格");
        WriteLog("trade-bank-store n=" + idxs.Count + " kw=" + keyword);
        return "已存完 n=" + idxs.Count;
    }

