    private static void BuildEscortPickerBody(Type rtType)
    {
        RefreshEscortCandidates();
        var filtered = GetFilteredEscortCandidates();

        var hint = CreateUiChild(_bodyRoot, "PickHint", rtType);
        SetAnchoredTop(RequireRect(hint, "ph"), 0f, -2f, 500f, 36f);
        var hintText = AddText(hint);
        try
        {
            SetProp(hintText, "alignment", EnumValue("UnityEngine.TextAnchor", "UpperLeft", 0));
        }
        catch
        {
            // ignore
        }

        var totalAll = _escortCandidates.Count;
        var total = filtered.Count;
        var pages = total <= 0 ? 1 : (total + EscortPageSize - 1) / EscortPageSize;
        if (_escortPage >= pages)
        {
            _escortPage = Math.Max(0, pages - 1);
        }

        var filterNote = string.IsNullOrEmpty(_escortSearch)
            ? ""
            : (" 搜「" + _escortSearch + "」");
        var modeNote = _escortActive ? "追加到队列" : "点任务加入队列";
        SetText(
            hintText,
            modeNote + "（含未接）共" + totalAll + " / 显" + total + filterNote
            + "｜队列" + _escortQueue.Count + "项",
            12);

        var searchY = -40f;
        _escortSearchInput = CreateInputField(_bodyRoot, rtType, "EscortSearch", 0f, searchY, 300f, 28f, _escortSearch, "任务名或ID");
        var searchBtn = CreateUiChild(_bodyRoot, "SearchBtn", rtType);
        SetAnchoredTop(RequireRect(searchBtn, "sb"), 175f, searchY, 70f, 28f);
        var searchImg = AddComp(searchBtn, "UnityEngine.UI.Image");
        SetColor(searchImg, 0.2f, 0.4f, 0.55f, 1f);
        var searchLab = CreateUiChild(searchBtn, "L", rtType);
        StretchFull(RequireRect(searchLab, "sbl"));
        SetText(AddText(searchLab), "搜索", 12);
        BindButton(searchBtn, searchImg, () =>
        {
            _escortSearch = ReadInputFieldText(_escortSearchInput);
            _escortPage = 0;
            RebuildEscortTab();
        });

        var clearBtn = CreateUiChild(_bodyRoot, "ClearSearch", rtType);
        SetAnchoredTop(RequireRect(clearBtn, "cs"), 235f, searchY, 50f, 28f);
        var clearImg = AddComp(clearBtn, "UnityEngine.UI.Image");
        SetColor(clearImg, 0.35f, 0.3f, 0.3f, 1f);
        var clearLab = CreateUiChild(clearBtn, "L", rtType);
        StretchFull(RequireRect(clearLab, "csl"));
        SetText(AddText(clearLab), "清空", 11);
        BindButton(clearBtn, clearImg, () =>
        {
            _escortSearch = "";
            _escortPage = 0;
            RebuildEscortTab();
        });

        var start = _escortPage * EscortPageSize;
        var y = -74f;
        for (var i = 0; i < EscortPageSize; i++)
        {
            var idx = start + i;
            if (idx >= total)
            {
                break;
            }

            var c = filtered[idx];
            var row = CreateUiChild(_bodyRoot, "Pick" + c.Id + "_" + idx, rtType);
            SetAnchoredTop(RequireRect(row, "pr"), 0f, y, 500f, 28f);
            var img = AddComp(row, "UnityEngine.UI.Image");
            var inQueue = EscortQueueContains(c.Id);
            SetColor(img, inQueue ? 0.22f : 0.16f, inQueue ? 0.32f : 0.22f, inQueue ? 0.28f : 0.3f, 1f);
            var lab = CreateUiChild(row, "L", rtType);
            StretchFull(RequireRect(lab, "pl"));
            var label = AddText(lab);
            try
            {
                SetProp(label, "alignment", EnumValue("UnityEngine.TextAnchor", "MiddleLeft", 3));
            }
            catch
            {
                // ignore
            }

            var title = c.Title ?? "";
            if (title.Length > 18)
            {
                title = title.Substring(0, 18) + "…";
            }

            SetText(label, (inQueue ? "✓" : "+") + "[" + c.Status + "] #" + c.Id + " " + title, 12);
            var missionId = c.Id;
            var missionTitle = c.Title ?? ("#" + c.Id);
            var missionStatus = c.Status ?? "";
            BindButton(row, img, () => EnqueueEscortMission(missionId, missionTitle, missionStatus));
            y -= 32f;
        }

        var barY = -74f - EscortPageSize * 32f - 4f;
        var prev = CreateUiChild(_bodyRoot, "Prev", rtType);
        SetAnchoredTop(RequireRect(prev, "prev"), -160f, barY, 90f, 28f);
        var prevImg = AddComp(prev, "UnityEngine.UI.Image");
        SetColor(prevImg, 0.25f, 0.28f, 0.34f, 1f);
        var prevLab = CreateUiChild(prev, "L", rtType);
        StretchFull(RequireRect(prevLab, "pvl"));
        SetText(AddText(prevLab), "上一页", 12);
        BindButton(prev, prevImg, () =>
        {
            CaptureEscortSearchFromUi();
            if (_escortPage > 0)
            {
                _escortPage--;
                RebuildEscortTab();
            }
        });

        var pageLabGo = CreateUiChild(_bodyRoot, "Page", rtType);
        SetAnchoredTop(RequireRect(pageLabGo, "pg"), 0f, barY, 100f, 28f);
        SetText(AddText(pageLabGo), (_escortPage + 1) + "/" + pages, 12);

        var next = CreateUiChild(_bodyRoot, "Next", rtType);
        SetAnchoredTop(RequireRect(next, "next"), 160f, barY, 90f, 28f);
        var nextImg = AddComp(next, "UnityEngine.UI.Image");
        SetColor(nextImg, 0.25f, 0.28f, 0.34f, 1f);
        var nextLab = CreateUiChild(next, "L", rtType);
        StretchFull(RequireRect(nextLab, "nxl"));
        SetText(AddText(nextLab), "下一页", 12);
        BindButton(next, nextImg, () =>
        {
            CaptureEscortSearchFromUi();
            if (_escortPage + 1 < pages)
            {
                _escortPage++;
                RebuildEscortTab();
            }
        });

        // 队列预览（可点移除未来项）
        barY -= 34f;
        var qHint = CreateUiChild(_bodyRoot, "QHint", rtType);
        SetAnchoredTop(RequireRect(qHint, "qh"), 0f, barY, 500f, 22f);
        SetText(AddText(qHint), "队列（点项可移除未执行的）:", 11);
        barY -= 24f;
        var showN = Math.Min(3, _escortQueue.Count);
        var qStart = Math.Max(0, _escortQueue.Count - showN);
        if (_escortActive && _escortQueueIndex >= 0)
        {
            qStart = Math.Max(0, Math.Min(_escortQueueIndex, _escortQueue.Count - showN));
        }

        for (var qi = 0; qi < showN; qi++)
        {
            var qIdx = qStart + qi;
            if (qIdx >= _escortQueue.Count)
            {
                break;
            }

            var qc = _escortQueue[qIdx];
            var mark = _escortActive && qIdx == _escortQueueIndex
                ? "▶"
                : (_escortActive && qIdx < _escortQueueIndex ? "✓" : (qIdx + 1) + ".");
            var row = CreateUiChild(_bodyRoot, "Q" + qIdx, rtType);
            SetAnchoredTop(RequireRect(row, "qr"), 0f, barY, 500f, 24f);
            var qImg = AddComp(row, "UnityEngine.UI.Image");
            SetColor(qImg, 0.14f, 0.18f, 0.22f, 1f);
            var qLab = CreateUiChild(row, "L", rtType);
            StretchFull(RequireRect(qLab, "ql"));
            var t = qc.Title ?? "";
            if (t.Length > 16)
            {
                t = t.Substring(0, 16) + "…";
            }

            SetText(AddText(qLab), mark + " #" + qc.Id + " " + t, 11);
            var removeIdx = qIdx;
            BindButton(row, qImg, () => RemoveEscortQueueAt(removeIdx));
            barY -= 26f;
        }

        barY -= 4f;
        if (!_escortActive)
        {
            var startBtn = CreateUiChild(_bodyRoot, "StartQ", rtType);
            SetAnchoredTop(RequireRect(startBtn, "sq"), -110f, barY, 180f, 32f);
            var startImg = AddComp(startBtn, "UnityEngine.UI.Image");
            SetColor(startImg, 0.2f, 0.48f, 0.28f, 1f);
            var startLab = CreateUiChild(startBtn, "L", rtType);
            StretchFull(RequireRect(startLab, "sql"));
            SetText(AddText(startLab), "开始队列护航", 13);
            BindButton(startBtn, startImg, StartEscortQueue);

            var clearQ = CreateUiChild(_bodyRoot, "ClearQ", rtType);
            SetAnchoredTop(RequireRect(clearQ, "cq"), 110f, barY, 140f, 32f);
            var clearQImg = AddComp(clearQ, "UnityEngine.UI.Image");
            SetColor(clearQImg, 0.4f, 0.28f, 0.2f, 1f);
            var clearQLab = CreateUiChild(clearQ, "L", rtType);
            StretchFull(RequireRect(clearQLab, "cql"));
            SetText(AddText(clearQLab), "清空队列", 13);
            BindButton(clearQ, clearQImg, () =>
            {
                _escortQueue.Clear();
                Tip("任务护航：队列已清空");
                RebuildEscortTab();
            });
            barY -= 36f;
        }

        var back = CreateUiChild(_bodyRoot, "BackPick", rtType);
        SetAnchoredTop(RequireRect(back, "bp"), 0f, barY, 200f, 30f);
        var backImg = AddComp(back, "UnityEngine.UI.Image");
        SetColor(backImg, 0.35f, 0.25f, 0.25f, 1f);
        var backLab = CreateUiChild(back, "L", rtType);
        StretchFull(RequireRect(backLab, "bpl"));
        SetText(AddText(backLab), _escortActive ? "返回护航" : "返回", 13);
        BindButton(back, backImg, () =>
        {
            _escortPicking = false;
            RebuildEscortTab();
        });
    }

    private static List<EscortCandidate> GetFilteredEscortCandidates()
    {
        var q = (_escortSearch ?? "").Trim();
        if (q.Length == 0)
        {
            return _escortCandidates;
        }

        var list = new List<EscortCandidate>();
        for (var i = 0; i < _escortCandidates.Count; i++)
        {
            var c = _escortCandidates[i];
            var idStr = c.Id.ToString();
            var title = c.Title ?? "";
            var status = c.Status ?? "";
            if (idStr.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0
                || title.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0
                || status.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)
            {
                list.Add(c);
            }
        }

        return list;
    }

    private static void CaptureEscortSearchFromUi()
    {
        var t = ReadInputFieldText(_escortSearchInput);
        if (t != null)
        {
            _escortSearch = t;
        }
    }

    private static string ReadInputFieldText(object input)
    {
        if (input == null || IsUnityNull(input))
        {
            return _escortSearch ?? "";
        }

        try
        {
            var t = GetProp(input, "text") ?? GetMember(input, "text");
            return Convert.ToString(t ?? "") ?? "";
        }
        catch
        {
            return _escortSearch ?? "";
        }
    }

    /// <summary>创建简易 UGUI InputField（反射），用于任务搜索。</summary>
    private static object CreateInputField(
        object parent, Type rtType, string name, float x, float y, float w, float h, string value, string placeholder)
    {
        var go = CreateUiChild(parent, name, rtType);
        SetAnchoredTop(RequireRect(go, name + "rt"), x, y, w, h);
        var img = AddComp(go, "UnityEngine.UI.Image");
        SetColor(img, 0.12f, 0.14f, 0.18f, 1f);

        var inputType = FindType("UnityEngine.UI.InputField") ?? FindType("TMPro.TMP_InputField");
        if (inputType == null)
        {
            // 退化：只显示当前关键字
            var fallback = AddText(go);
            try
            {
                SetProp(fallback, "alignment", EnumValue("UnityEngine.TextAnchor", "MiddleLeft", 3));
            }
            catch
            {
                // ignore
            }

            SetText(fallback, string.IsNullOrEmpty(value) ? (" " + placeholder) : (" " + value), 13);
            return null;
        }

        var input = AddComp(go, inputType);
        SetProp(input, "targetGraphic", img);

        var textGo = CreateUiChild(go, "Text", rtType);
        StretchFull(RequireRect(textGo, name + "txt"));
        try
        {
            var rt = RequireRect(textGo, name + "txt2");
            SetProp(rt, "offsetMin", Vec2(6f, 2f));
            SetProp(rt, "offsetMax", Vec2(-6f, -2f));
        }
        catch
        {
            // ignore
        }

        var text = AddText(textGo);
        try
        {
            SetProp(text, "alignment", EnumValue("UnityEngine.TextAnchor", "MiddleLeft", 3));
            SetProp(text, "supportRichText", false);
        }
        catch
        {
            // ignore
        }

        SetText(text, value ?? "", 13);
        SetProp(text, "color", MakeColor(0.95f, 0.95f, 0.95f, 1f));

        var phGo = CreateUiChild(go, "Placeholder", rtType);
        StretchFull(RequireRect(phGo, name + "ph"));
        try
        {
            var rt = RequireRect(phGo, name + "ph2");
            SetProp(rt, "offsetMin", Vec2(6f, 2f));
            SetProp(rt, "offsetMax", Vec2(-6f, -2f));
        }
        catch
        {
            // ignore
        }

        var ph = AddText(phGo);
        try
        {
            SetProp(ph, "alignment", EnumValue("UnityEngine.TextAnchor", "MiddleLeft", 3));
        }
        catch
        {
            // ignore
        }

        SetText(ph, placeholder ?? "", 13);
        SetProp(ph, "color", MakeColor(0.55f, 0.58f, 0.62f, 1f));

        // InputField / TMP_InputField 绑定
        try
        {
            SetProp(input, "textComponent", text);
        }
        catch
        {
            try
            {
                SetMember(input, "m_TextComponent", text);
            }
            catch
            {
                // ignore
            }
        }

        try
        {
            SetProp(input, "placeholder", ph);
        }
        catch
        {
            // ignore
        }

        try
        {
            SetProp(input, "text", value ?? "");
        }
        catch
        {
            // ignore
        }

        // 有字时藏 placeholder
        try
        {
            var phGoObj = GetProp(ph, "gameObject") ?? phGo;
            var has = !string.IsNullOrEmpty(value);
            phGoObj.GetType().GetMethod("SetActive", new[] { typeof(bool) })
                ?.Invoke(phGoObj, new object[] { !has });
        }
        catch
        {
            // ignore
        }

        return input;
    }

    private static void TryRebuildEscortTab()
    {
        if (_visible && _tab == TabEscort && _canvasGo != null && !IsUnityNull(_canvasGo))
        {
            try
            {
                RebuildEscortTab();
            }
            catch
            {
                // ignore
            }
        }
    }

    private static void RebuildEscortTab()
    {
        if (_tab != TabEscort || _bodyRoot == null || IsUnityNull(_bodyRoot))
        {
            return;
        }

        ClearBody();
        BuildEscortBody();
        RefreshTabButtonLabels();
    }

    private static string FormatEscortQueueSummary()
    {
        if (_escortQueue.Count == 0)
        {
            return "队列为空。点「编辑队列」加入任务（可含未接取）。";
        }

        var sb = new System.Text.StringBuilder();
        sb.Append("队列 ").Append(_escortQueue.Count).Append(" 项");
        if (_escortActive && _escortQueueIndex >= 0)
        {
            sb.Append("｜进度 ").Append(_escortQueueIndex + 1).Append('/').Append(_escortQueue.Count);
        }

        sb.Append('\n');
        var from = 0;
        var to = Math.Min(_escortQueue.Count, 4);
        if (_escortActive && _escortQueueIndex >= 0)
        {
            from = Math.Max(0, _escortQueueIndex);
            to = Math.Min(_escortQueue.Count, from + 4);
        }

        for (var i = from; i < to; i++)
        {
            var c = _escortQueue[i];
            var mark = _escortActive && i == _escortQueueIndex
                ? "▶"
                : (_escortActive && i < _escortQueueIndex ? "✓" : "·");
            var t = c.Title ?? "";
            if (t.Length > 14)
            {
                t = t.Substring(0, 14) + "…";
            }

            sb.Append(mark).Append('#').Append(c.Id).Append(' ').Append(t);
            if (i + 1 < to)
            {
                sb.Append("  ");
            }
        }

        if (to < _escortQueue.Count)
        {
            sb.Append(" …+").Append(_escortQueue.Count - to);
        }

        return sb.ToString();
    }

    /// <summary>读当前护航任务 MissionData.missionStepNum；-1=读不到。</summary>
    private static int GetEscortMissionStepNum()
    {
        try
        {
            if (_escortMissionId <= 0)
            {
                return -1;
            }

            var mission = GetMissionDataById(_escortMissionId);
            if (mission == null)
            {
                return -1;
            }

            var v = GetMember(mission, "missionStepNum");
            return Convert.ToInt32(v ?? -1);
        }
        catch
        {
            return -1;
        }
    }

    /// <summary>取当前护航任务标题（带子步骤进度，如「任务名 2/5」）；失败回退纯标题。</summary>
    private static string GetEscortMissionTitleWithStep()
    {
        var fallback = _escortMissionTitle ?? "";
        try
        {
            if (_escortMissionId <= 0)
            {
                return fallback;
            }

            var mission = GetMissionDataById(_escortMissionId);
            if (mission == null)
            {
                return fallback;
            }

            var m = mission.GetType().GetMethod(
                "GetTitleWithStepProgress",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            if (m == null)
            {
                return fallback;
            }

            var s = Convert.ToString(m.Invoke(mission, null) ?? "") ?? "";
            return string.IsNullOrEmpty(s) ? fallback : s;
        }
        catch
        {
            return fallback;
        }
    }

    // ---------------- 龙族纷争循环 ----------------

    /// <summary>判断任务 ID 是否属于龙族纷争（硬编码 + 标题关键字双校验）。</summary>
    private static bool IsDragonMission(int missionId)
    {
        foreach (var id in DragonMissionIds)
        {
            if (id == missionId)
            {
                return true;
            }
        }

        try
        {
            var mission = GetMissionDataById(missionId);
            var title = Convert.ToString(GetMember(mission, "title") ?? "") ?? "";
            if (!string.IsNullOrEmpty(title) && title.IndexOf(DragonTitleKeyword, StringComparison.Ordinal) >= 0)
            {
                return true;
            }
        }
        catch
        {
            // ignore
        }

        return false;
    }

    /// <summary>读取任务当前状态字符串（Started/NotStart/Ended）。</summary>
    private static string GetMissionStatusStr(object mission)
    {
        try
        {
            return Convert.ToString(GetMember(mission, "taskstatus") ?? "") ?? "";
        }
        catch
        {
            return "";
        }
    }

    /// <summary>
    /// 判断当前循环任务集（A/B 线）是否均非「已完成」状态。
    /// 已接(Started) 或 可接(NotStart) 都算就绪；入队后由护航自身的 ClickEscortTaskNav
    /// 负责把「可接」任务实际接取（含等级绕过与 20 次恢复重试），此处不做预接取。
    /// </summary>
    private static bool CheckDragonMissionsReady(out string failReason)
    {
        failReason = "";
        var ids = _dragonMissionIds ?? DragonMissionIds;
        for (var i = 0; i < ids.Length; i++)
        {
            var id = ids[i];
            var mission = GetMissionDataById(id);
            if (mission == null)
            {
                failReason = "找不到龙族纷争" + (i + 1) + "任务数据(#" + id + ")";
                return false;
            }

            var st = GetMissionStatusStr(mission);
            if (st.EndsWith("Ended", StringComparison.Ordinal) || st == "2")
            {
                failReason = "龙族纷争" + (i + 1) + "(#" + id + ")已完成（未重置）";
                return false;
            }
        }

        return true;
    }

    /// <summary>对所有队员发送重置龙族纷争4（resetId 有效才发）。</summary>
    private static void ResetDragon4ForAll()
    {
        var uids = CollectTeamOrMultiUids();
        if (uids.Count == 0)
        {
            var cap = GetCaptainUid();
            if (!string.IsNullOrEmpty(cap))
            {
                uids.Add(cap);
            }
        }

        var resetType = FindType("Proto_CS_ResetTask");
        var lss = FindType("LSSPROTO");
        var opcodeField = lss?.GetField("LSSPROTO_RESET_TASK_FUNC", BindingFlags.Public | BindingFlags.Static);
        var net = GetManagerInstance("NetManager");
        var send = net?.GetType().GetMethod("SendMessage", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        if (resetType == null || opcodeField == null || net == null || send == null)
        {
            WriteLog("dragon reset: 反射缺失 resetType=" + (resetType != null)
                     + " opcode=" + (opcodeField != null) + " net=" + (net != null) + " send=" + (send != null));
            return;
        }

        foreach (var uid in uids)
        {
            var mission = GetMissionDataById(113); // 龙族纷争4
            var resetId = mission != null ? Convert.ToInt32(GetMember(mission, "resetId") ?? -1) : -1;
            if (resetId <= 0)
            {
                WriteLog("dragon reset: uid=" + uid + " resetId 无效，跳过");
                continue;
            }

            try
            {
                var msg = Activator.CreateInstance(resetType);
                SetMember(msg, "Type", "重置任务");
                SetMember(msg, "Id", resetId.ToString());
                SetMember(msg, "KUid", uid);
                send.Invoke(net, new object[] { opcodeField.GetValue(null), msg });
                WriteLog("dragon reset: uid=" + uid + " resetId=" + resetId);
            }
            catch (Exception ex)
            {
                WriteLog("dragon reset EX uid=" + uid + " " + RootMessage(ex));
            }
        }
    }

    /// <summary>护航页：洗礼预备开关。开=重置洗礼5→入队1/2/4；战败暂停；圣魔龙手动打。</summary>
    private static void ToggleBaptismPrep()
    {
        if (_baptismPrepActive)
        {
            StopBaptismPrep("已手动停止");
            return;
        }

        StartBaptismPrep();
    }

    private static void StopBaptismPrep(string reason)
    {
        if (!_baptismPrepActive && !_escortActive)
        {
            Tip("洗礼预备：未在运行");
            return;
        }

        _baptismPrepActive = false;
        _baptismPrepPhase = 0;
        _baptismSawForceQuit = false;
        ClearBaptismBagPrepState();
        ClearBaptism5BridgeFlags();
        WriteLog("baptism prep stop reason=" + reason);
        if (_floraHealActive && _floraHealBaptismStage != FloraBaptismNone)
        {
            _floraHealBaptismStage = FloraBaptismNone;
            StopFloraHeal("洗礼预备已停止", false);
        }
        else
        {
            _floraHealBaptismStage = FloraBaptismNone;
        }

        if (_escortActive || _escortPicking || _escortQueue.Count > 0)
        {
            CancelEscort(true, "洗礼预备已停止");
        }
        else
        {
            Tip("洗礼预备：已关闭");
        }

        TryRebuildEscortTab();
    }

    private static void ClearBaptism5BridgeFlags()
    {
        _baptismNeedItemBefore5 = false;
        _baptismNeedFloraBefore5 = false;
        _baptism5ItemUsePending = false;
        _baptism5ItemUseAtMs = 0;
        _baptism5NavAborted = false;
        _baptism5BossPauseDone = false;
        _baptism5LastNavNudgeMs = 0;
    }

    /// <summary>开局：全员丢弃#13651，再用完古钱包；完后进法兰治疗。</summary>
    private static void TickBaptismBagPrep()
    {
        if (!_baptismPrepActive || _baptismPrepPhase != BaptismPhaseBagPrep)
        {
            return;
        }

        try
        {
            if (IsDialoguePanelOpen())
            {
                TryAutoPickDialogue();
                return;
            }

            var now = NowMs();
            if (_baptismBagAwaitUse)
            {
                if (now - _baptismBagUseAtMs < BaptismBagUseSettleMs)
                {
                    return;
                }

                _baptismBagAwaitUse = false;
                _baptismBagNextAtMs = now;
            }

            if (now < _baptismBagNextAtMs)
            {
                return;
            }

            if (_baptismBagUids == null || _baptismBagUids.Count == 0)
            {
                BeginBaptismFloraAfterBagPrep();
                return;
            }

            if (_baptismBagUidIdx >= _baptismBagUids.Count)
            {
                BeginBaptismFloraAfterBagPrep();
                return;
            }

            var uid = _baptismBagUids[_baptismBagUidIdx];
            if (string.IsNullOrEmpty(uid))
            {
                AdvanceBaptismBagUid("空uid");
                return;
            }

            if (_baptismBagSub == BaptismBagSubDrop)
            {
                if (!TryFindBagItemById(uid, BaptismDropItemId, out var index, out var data, out var pile))
                {
                    _baptismBagSub = BaptismBagSubUse;
                    _baptismBagFailStreak = 0;
                    _baptismBagNote = FormatBaptismPlayerShort(uid) + " 用" + BaptismWalletKeyword;
                    _baptismBagNextAtMs = now;
                    return;
                }

                if (!SendBaptismDropItem(uid, index, data, pile))
                {
                    _baptismBagFailStreak++;
                    WriteLog("baptism bag drop send fail#" + _baptismBagFailStreak + " uid=" + uid);
                    if (_baptismBagFailStreak >= BaptismBagMaxFails)
                    {
                        Tip("洗礼预备：丢弃#" + BaptismDropItemId + "失败，跳过该角色");
                        AdvanceBaptismBagUid("丢弃发包失败");
                        return;
                    }

                    _baptismBagNextAtMs = now + BaptismBagIntervalMs;
                    return;
                }

                _baptismBagDropped++;
                _baptismBagFailStreak = 0;
                _baptismBagNote = "已丢#" + BaptismDropItemId + "×" + pile
                                   + " @" + FormatBaptismPlayerShort(uid);
                _baptismBagNextAtMs = now + BaptismBagIntervalMs;
                return;
            }

            // 使用古钱包直到没有
            var left = CountBagItemByKeyword(uid, BaptismWalletKeyword);
            if (left <= 0)
            {
                AdvanceBaptismBagUid("钱包用完");
                return;
            }

            if (!TryUseMemoryItem(uid, BaptismWalletKeyword))
            {
                _baptismBagFailStreak++;
                WriteLog("baptism bag use wallet fail#" + _baptismBagFailStreak
                         + " uid=" + uid + " left=" + left);
                if (_baptismBagFailStreak >= BaptismBagMaxFails)
                {
                    Tip("洗礼预备：使用" + BaptismWalletKeyword + "失败，跳过该角色");
                    AdvanceBaptismBagUid("使用失败");
                    return;
                }

                _baptismBagNextAtMs = now + BaptismBagIntervalMs;
                return;
            }

            _baptismBagUsed++;
            _baptismBagFailStreak = 0;
            _baptismBagAwaitUse = true;
            _baptismBagUseAtMs = now;
            _baptismBagNote = "已用" + BaptismWalletKeyword + " @" + FormatBaptismPlayerShort(uid)
                               + " 余约" + Math.Max(0, left - 1);
            _baptismBagNextAtMs = now + BaptismBagIntervalMs;
        }
        catch (Exception ex)
        {
            WriteLog("TickBaptismBagPrep EX: " + RootMessage(ex));
            Tip("洗礼预备：背包处理异常，进入治疗");
            BeginBaptismFloraAfterBagPrep();
        }
    }

    private static void AdvanceBaptismBagUid(string reason)
    {
        WriteLog("baptism bag uid done idx=" + _baptismBagUidIdx + " reason=" + reason
                 + " dropped=" + _baptismBagDropped + " used=" + _baptismBagUsed);
        _baptismBagUidIdx++;
        _baptismBagSub = BaptismBagSubDrop;
        _baptismBagFailStreak = 0;
        _baptismBagAwaitUse = false;
        _baptismBagNextAtMs = NowMs();
        if (_baptismBagUids != null && _baptismBagUidIdx < _baptismBagUids.Count)
        {
            _baptismBagNote = "下一位 " + (_baptismBagUidIdx + 1) + "/" + _baptismBagUids.Count;
        }
    }

    private static bool TryFindBagItemById(
        string uid, int itemId, out int index, out object data, out int pile)
    {
        index = -1;
        data = null;
        pile = 1;
        if (string.IsNullOrEmpty(uid) || itemId <= 0)
        {
            return false;
        }

        try
        {
            var items = GetItemDatasFromUid(uid);
            if (items == null)
            {
                return false;
            }

            for (var i = 0; i < items.Count; i++)
            {
                var item = items[i];
                if (item == null || Convert.ToInt32(GetMember(item, "useFlag") ?? 0) != 1)
                {
                    continue;
                }

                var d = GetMember(item, "data");
                var id = Convert.ToInt32(GetMember(d, "Id") ?? GetProp(d, "Id") ?? 0);
                if (id != itemId)
                {
                    continue;
                }

                index = i;
                data = d;
                pile = Convert.ToInt32(GetMember(d, "Pile") ?? 1);
                if (pile < 1)
                {
                    pile = 1;
                }

                return true;
            }
        }
        catch (Exception ex)
        {
            WriteLog("TryFindBagItemById EX: " + RootMessage(ex));
        }

        return false;
    }

    private static bool SendBaptismDropItem(string uid, int index, object data, int pile)
    {
        var itemMgr = GetManagerInstance("ItemManager");
        var send = FindSendBackPackMessage(itemMgr);
        if (send == null || string.IsNullOrEmpty(uid) || index < 0)
        {
            return false;
        }

        if (pile < 1)
        {
            pile = 1;
        }

        send.Invoke(itemMgr, new object[] { "丢弃道具", index, pile, uid });
        var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? ("#" + BaptismDropItemId);
        WriteLog("baptism drop uid=" + uid + " idx=" + index + " pile=" + pile + " name=" + name);
        return true;
    }

    private static void StartBaptismPrep()
    {
        try
        {
            if (!CheckBaptismUnbindGoldOrTip())
            {
                return;
            }

            if (_dragonLoopActive || _midAutumnLoopActive || _escortActive || _escortPicking)
            {
                CancelEscort(true, "已切换到洗礼预备");
            }


            if (_floraHealActive)
            {
                _floraHealBaptismStage = FloraBaptismNone;
                StopFloraHeal("已切换到洗礼预备", false);
            }

            _baptismPrepActive = true;
            _baptismPrepPhase = BaptismPhaseBagPrep;
            _baptismPrepPhaseAtMs = NowMs();
            _baptismSawForceQuit = false;
            ClearBaptism5BridgeFlags();
            InitBaptismBagPrepState();
            EnsureCaptainAttackModeCombo();
            WriteLog("baptism prep start bag-prep then flora reset #99 queue 84/85/87/99");
            Tip("洗礼预备：先丢弃#" + BaptismDropItemId + "并使用" + BaptismWalletKeyword + "…");
            TryRebuildEscortTab();
        }
        catch (Exception ex)
        {
            WriteLog("StartBaptismPrep EX: " + RootMessage(ex));
            Tip("洗礼预备：启动失败");
            _baptismPrepActive = false;
            _baptismPrepPhase = 0;
            _floraHealBaptismStage = FloraBaptismNone;
            ClearBaptismBagPrepState();
            ClearBaptism5BridgeFlags();
            TryRebuildEscortTab();
        }
    }

    private static void ClearBaptismBagPrepState()
    {
        _baptismBagUids = null;
        _baptismBagUidIdx = 0;
        _baptismBagSub = BaptismBagSubDrop;
        _baptismBagNextAtMs = 0;
        _baptismBagNote = "";
        _baptismBagDropped = 0;
        _baptismBagUsed = 0;
        _baptismBagFailStreak = 0;
        _baptismBagAwaitUse = false;
        _baptismBagUseAtMs = 0;
    }

    private static void InitBaptismBagPrepState()
    {
        ClearBaptismBagPrepState();
        var uids = CollectTeamOrMultiUids();
        if (uids.Count == 0)
        {
            var cap = GetCaptainUid();
            if (!string.IsNullOrEmpty(cap))
            {
                uids.Add(cap);
            }
        }

        _baptismBagUids = uids;
        _baptismBagUidIdx = 0;
        _baptismBagSub = BaptismBagSubDrop;
        _baptismBagNextAtMs = NowMs();
        _baptismBagNote = "准备丢弃#" + BaptismDropItemId;
        WriteLog("baptism bag-prep uids=" + uids.Count);
    }

    /// <summary>开局背包处理完毕：进入法兰治疗。</summary>
    private static void BeginBaptismFloraAfterBagPrep()
    {
        var dropped = _baptismBagDropped;
        var used = _baptismBagUsed;
        ClearBaptismBagPrepState();
        _baptismPrepPhase = BaptismPhaseFlora;
        _baptismPrepPhaseAtMs = NowMs();
        WriteLog("baptism bag-prep done dropped=" + dropped + " used=" + used + " → flora");
        Tip("洗礼预备：背包处理完成（丢" + dropped + "/用" + used + "），开始法兰治疗…");
        StartFloraHealForBaptism(FloraBaptismPrepStart);
        TryRebuildEscortTab();
    }

    /// <summary>
    /// 开局检查非绑定魔币（unBindGold）：队长 &gt;120000，队员 &gt;20000。
    /// 不足则 Tip 并返回 false（不启动）。
    /// </summary>
    private static bool CheckBaptismUnbindGoldOrTip()
    {
        var cap = GetCaptainUid();
        if (string.IsNullOrEmpty(cap))
        {
            Tip("洗礼预备：无队长，无法检查魔币");
            WriteLog("baptism gold check: no captain");
            return false;
        }

        var fails = new List<string>();
        var capGold = GetPlayerUnbindGold(cap);
        if (capGold <= BaptismCaptainUnbindGoldMin)
        {
            fails.Add("队长" + FormatBaptismPlayerShort(cap) + "非绑定魔币"
                      + capGold + "（需>" + BaptismCaptainUnbindGoldMin + "）");
        }

        var uids = CollectTeamOrMultiUids();
        foreach (var uid in uids)
        {
            if (string.IsNullOrEmpty(uid) || uid == cap)
            {
                continue;
            }

            var g = GetPlayerUnbindGold(uid);
            if (g <= BaptismMemberUnbindGoldMin)
            {
                fails.Add("队员" + FormatBaptismPlayerShort(uid) + "非绑定魔币"
                          + g + "（需>" + BaptismMemberUnbindGoldMin + "）");
            }
        }

        if (fails.Count == 0)
        {
            WriteLog("baptism gold check ok cap=" + capGold + " members=" + (uids.Count - 1));
            return true;
        }

        var msg = "洗礼预备：魔币不足 — " + string.Join("；", fails);
        Tip(msg);
        WriteLog("baptism gold check fail " + msg);
        return false;
    }

    private static long GetPlayerUnbindGold(string uid)
    {
        try
        {
            var player = GetPlayer(uid);
            if (player == null)
            {
                return 0;
            }

            return Convert.ToInt64(GetMember(player, "unBindGold") ?? 0);
        }
        catch
        {
            return 0;
        }
    }

    private static string FormatBaptismPlayerShort(string uid)
    {
        try
        {
            var player = GetPlayer(uid);
            var name = Convert.ToString(GetMember(player, "Name") ?? GetMember(player, "name") ?? "") ?? "";
            if (!string.IsNullOrEmpty(name))
            {
                return name;
            }
        }
        catch
        {
            // ignore
        }

        if (string.IsNullOrEmpty(uid) || uid.Length <= 4)
        {
            return uid ?? "";
        }

        return uid.Substring(uid.Length - 4);
    }

    /// <summary>洗礼预备：走脚本页同款法兰治疗（不丢头盔）。</summary>
    private static void StartFloraHealForBaptism(int stage)
    {
        _floraHealBaptismStage = stage;
        StartFloraHeal(false);
    }

    /// <summary>法兰治疗成功后：重置洗礼5，进入等待再入队。</summary>
    private static void BeginBaptismResetAfterFlora()
    {
        if (!_baptismPrepActive)
        {
            return;
        }

        Tip("洗礼预备：治疗完成，重置洗礼5…");
        ResetBaptism5ForAll();
        _baptismPrepPhase = BaptismPhaseResetWait;
        _baptismPrepPhaseAtMs = NowMs();
        WriteLog("baptism prep after flora -> reset wait");
        TryRebuildEscortTab();
    }

    /// <summary>洗礼4后治疗完成：检查/使用#651022，再开洗礼5。</summary>
    private static void BeginBaptism5AfterFlora()
    {
        if (!_baptismPrepActive)
        {
            return;
        }

        Tip("洗礼预备：治疗完成，检查洗礼5道具…");
        TryStartBaptism5WithItem("after-flora");
        TryRebuildEscortTab();
    }

    /// <summary>队长背包有#651022则使用并短等后开洗礼5；否则暂停。</summary>
    private static bool TryStartBaptism5WithItem(string reason)
    {
        if (!_baptismPrepActive || !_escortActive)
        {
            return false;
        }

        if (_escortQueueIndex < 0 || _escortQueueIndex >= _escortQueue.Count
            || _escortQueue[_escortQueueIndex].Id != Baptism5MissionId)
        {
            WriteLog("baptism5 item: queue not on #99 reason=" + reason);
            return false;
        }

        var uid = GetCaptainUid();
        if (string.IsNullOrEmpty(uid))
        {
            PauseEscort("洗礼5：无队长，无法检查道具#" + Baptism5StartItemId, true);
            _baptismNeedItemBefore5 = true;
            return false;
        }

        var bag = CountBagItemById(uid, Baptism5StartItemId);
        if (bag <= 0)
        {
            _baptismNeedItemBefore5 = true;
            WriteLog("baptism5 item missing uid=" + uid + " id=" + Baptism5StartItemId
                     + " reason=" + reason);
            PauseEscort("洗礼5：队长背包无道具#" + Baptism5StartItemId + "，备好后点继续", true);
            return false;
        }

        if (!TryUseBagItemById(uid, Baptism5StartItemId))
        {
            _baptismNeedItemBefore5 = true;
            WriteLog("baptism5 item use fail uid=" + uid + " id=" + Baptism5StartItemId);
            PauseEscort("洗礼5：使用道具#" + Baptism5StartItemId + "失败，处理后点继续", true);
            return false;
        }

        _baptismNeedItemBefore5 = false;
        _baptism5ItemUsePending = true;
        _baptism5ItemUseAtMs = NowMs();
        Tip("洗礼预备：已使用道具#" + Baptism5StartItemId + "，即将开始洗礼5…");
        WriteLog("baptism5 item used reason=" + reason + " bagWas=" + bag);
        return true;
    }

    /// <summary>按道具 Id 使用队长/指定角色背包中的一件（SendUseItem）。</summary>
    private static bool TryUseBagItemById(string uid, int itemId)
    {
        if (string.IsNullOrEmpty(uid) || itemId <= 0)
        {
            return false;
        }

        try
        {
            var items = FindType("PlayerDataHolder")?.GetMethod(
                "GetItemDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic)
                ?.Invoke(null, new object[] { uid }) as System.Collections.IList;
            if (items == null)
            {
                return false;
            }

            var itemMgr = GetManagerInstance("ItemManager");
            if (itemMgr == null)
            {
                return false;
            }

            MethodInfo use = null;
            foreach (var m in itemMgr.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
            {
                if (m.Name != "SendUseItem")
                {
                    continue;
                }

                var ps = m.GetParameters();
                if (ps.Length >= 4 && ps[0].ParameterType == typeof(int) && ps[3].ParameterType == typeof(string))
                {
                    use = m;
                    break;
                }
            }

            if (use == null)
            {
                return false;
            }

            for (var i = 0; i < items.Count; i++)
            {
                var item = items[i];
                if (item == null)
                {
                    continue;
                }

                var useFlag = Convert.ToInt32(GetMember(item, "useFlag") ?? 0);
                if (useFlag != 1)
                {
                    continue;
                }

                var data = GetMember(item, "data");
                var id = Convert.ToInt32(GetMember(data, "Id") ?? GetProp(data, "Id") ?? 0);
                if (id != itemId)
                {
                    continue;
                }

                var x = 0;
                var y = 0;
                TryGetPlayerXY(out x, out y);
                var ps = use.GetParameters();
                if (ps.Length >= 7)
                {
                    use.Invoke(itemMgr, new object[] { x, y, i, uid, 0, -1, 1 });
                }
                else if (ps.Length >= 4)
                {
                    use.Invoke(itemMgr, new object[] { x, y, i, uid });
                }

                var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
                WriteLog("use bag item-by-id uid=" + uid + " id=" + itemId + " idx=" + i + " name=" + name);
                return true;
            }

            return false;
        }
        catch (Exception ex)
        {
            WriteLog("TryUseBagItemById EX: " + RootMessage(ex));
            return false;
        }
    }

    /// <summary>洗礼5：进 60305 掐任务导航，走到 (173,28) 后暂停等手动 Boss。</summary>
    private static bool TickBaptism5BossApproach()
    {
        if (!_baptismPrepActive || _escortMissionId != Baptism5MissionId || _escortPaused)
        {
            return false;
        }

        int floor;
        string floorName;
        int mapRes;
        if (!TryGetCurrentMapInfo(out floor, out floorName, out mapRes) || floor != Baptism5BossFloor)
        {
            return false;
        }

        if (!_baptism5NavAborted)
        {
            _baptism5NavAborted = true;
            AbortEscortTaskPathFully("baptism5-60305");
            ClearEscortStuckPending();
            StopEscortEncounterWait("baptism5-60305", false);
            string how;
            TryNavigateTo(Baptism5BossFloor, Baptism5BossX, Baptism5BossY, out how);
            _baptism5LastNavNudgeMs = NowMs();
            Tip("洗礼5：已进Boss图，停止任务导航，前往 (" + Baptism5BossX + "," + Baptism5BossY + ")");
            WriteLog("baptism5 abort task-nav floor=" + floor + " nav=" + how);
            return true;
        }

        int px;
        int py;
        if (!TryGetPlayerXY(out px, out py))
        {
            return true;
        }

        var dist = Math.Abs(px - Baptism5BossX) + Math.Abs(py - Baptism5BossY);
        if (dist <= Baptism5BossArriveNear)
        {
            if (!_baptism5BossPauseDone)
            {
                _baptism5BossPauseDone = true;
                AbortEscortTaskPathFully("baptism5-boss-arrive");
                ClearEscortStuckPending();
                WriteLog("baptism5 boss pause at " + px + "," + py);
                PauseEscort("洗礼5：已到Boss点(" + Baptism5BossX + "," + Baptism5BossY
                            + ")，请手动打完后点继续", true);
            }

            return true;
        }

        var now = NowMs();
        if (now - _baptism5LastNavNudgeMs >= Baptism5NavNudgeMs)
        {
            string how;
            TryNavigateTo(Baptism5BossFloor, Baptism5BossX, Baptism5BossY, out how);
            _baptism5LastNavNudgeMs = now;
            WriteLog("baptism5 nudge boss xy dist=" + dist + " how=" + how);
        }

        return true;
    }

    /// <summary>
    /// 队长攻击方式改为合击（清 PROTO_CHAR_FS_BATTLERANDOM=0x4000）。
    /// 已是合击则不发包。协议：RoleManager.SendConfig(flg, uid)。
    /// </summary>
    private static void EnsureCaptainAttackModeCombo()
    {
        const int BattleRandomFlag = 0x4000; // PROTO_CHAR_FS_BATTLERANDOM
        try
        {
            var uid = GetCaptainUid();
            if (string.IsNullOrEmpty(uid))
            {
                WriteLog("baptism combo: 无队长 uid");
                return;
            }

            var player = GetPlayer(uid);
            if (player == null)
            {
                WriteLog("baptism combo: 找不到队长玩家 uid=" + uid);
                return;
            }

            var etcObj = GetMember(player, "etcFlag");
            var flg = Convert.ToInt32(etcObj ?? 0);
            if ((flg & BattleRandomFlag) == 0)
            {
                WriteLog("baptism combo: 队长已是合击 flg=" + flg);
                return;
            }

            var newFlg = flg & ~BattleRandomFlag;
            var roleMgr = GetManagerInstance("RoleManager");
            var send = roleMgr?.GetType().GetMethod(
                "SendConfig",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                null,
                new[] { typeof(int), typeof(string) },
                null);
            if (roleMgr == null || send == null)
            {
                WriteLog("baptism combo: SendConfig 反射失败");
                return;
            }

            send.Invoke(roleMgr, new object[] { newFlg, uid });
            try
            {
                // 本地先改，避免等 Config 回包前仍读到随机
                var etcType = etcObj?.GetType();
                if (etcType != null && etcType.IsEnum)
                {
                    SetMember(player, "etcFlag", Enum.ToObject(etcType, newFlg));
                }
                else
                {
                    SetMember(player, "etcFlag", newFlg);
                }
            }
            catch
            {
                // ignore local mirror
            }

            WriteLog("baptism combo: 队长攻击方式 随机→合击 flg " + flg + "->" + newFlg);
            Tip("洗礼预备：队长攻击方式已改为合击");
        }
        catch (Exception ex)
        {
            WriteLog("EnsureCaptainAttackModeCombo EX: " + RootMessage(ex));
        }
    }

    /// <summary>对所有队员发送重置洗礼5（#99，resetId 有效才发）。</summary>
    private static void ResetBaptism5ForAll()
    {
        var uids = CollectTeamOrMultiUids();
        if (uids.Count == 0)
        {
            var cap = GetCaptainUid();
            if (!string.IsNullOrEmpty(cap))
            {
                uids.Add(cap);
            }
        }

        var resetType = FindType("Proto_CS_ResetTask");
        var lss = FindType("LSSPROTO");
        var opcodeField = lss?.GetField("LSSPROTO_RESET_TASK_FUNC", BindingFlags.Public | BindingFlags.Static);
        var net = GetManagerInstance("NetManager");
        var send = net?.GetType().GetMethod("SendMessage", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        if (resetType == null || opcodeField == null || net == null || send == null)
        {
            WriteLog("baptism reset: 反射缺失 resetType=" + (resetType != null)
                     + " opcode=" + (opcodeField != null) + " net=" + (net != null) + " send=" + (send != null));
            return;
        }

        foreach (var uid in uids)
        {
            var mission = GetMissionDataById(Baptism5MissionId);
            var resetId = mission != null ? Convert.ToInt32(GetMember(mission, "resetId") ?? -1) : -1;
            if (resetId < 0)
            {
                WriteLog("baptism reset: uid=" + uid + " resetId 无效，跳过");
                continue;
            }

            try
            {
                var msg = Activator.CreateInstance(resetType);
                SetMember(msg, "Type", "重置任务");
                SetMember(msg, "Id", resetId.ToString());
                SetMember(msg, "KUid", uid);
                send.Invoke(net, new object[] { opcodeField.GetValue(null), msg });
                WriteLog("baptism reset: uid=" + uid + " mission=99 resetId=" + resetId);
            }
            catch (Exception ex)
            {
                WriteLog("baptism reset EX uid=" + uid + " " + RootMessage(ex));
            }
        }
    }

    /// <summary>洗礼预备 phase2：等重置回包后入队 1/2/4 并开护航。</summary>
    private static void TickBaptismPrepPrepare()
    {
        if (!_baptismPrepActive || _baptismPrepPhase != BaptismPhaseResetWait)
        {
            return;
        }

        var now = NowMs();
        if (now - _baptismPrepPhaseAtMs < BaptismResetDelayMs)
        {
            return;
        }

        _escortQueue.Clear();
        foreach (var id in BaptismPrepMissionIds)
        {
            var mission = GetMissionDataById(id);
            var title = mission != null
                ? (Convert.ToString(GetMember(mission, "title") ?? "") ?? "")
                : "";
            _escortQueue.Add(new EscortCandidate
            {
                Id = id,
                Title = string.IsNullOrEmpty(title) ? ("#" + id) : title,
                Status = "排队"
            });
        }

        _baptismPrepPhase = BaptismPhaseEscort;
        _escortPicking = false;
        _escortActive = true;
        _escortPaused = false;
        _escortPauseReason = "";
        _escortLastDiag = "";
        StopEscortAlertRing();
        _escortQueueIndex = 0;
        _escortBetweenTasksWaitMs = 0;
        _escortAwaitingReadyMs = 0;
        _escortRecoverAttempts = 0;
        ResetEscortStuckState();
        _escortFinishWaitMs = 0;
        _escortLastStepNum = -1;
        _lastActivityMs = now;
        _prevRunTaskId = GetRunTaskId();
        WriteLog("baptism prep run queue=" + _escortQueue.Count);
        Tip("洗礼预备：已入队洗礼1/2/4/5，开始护航（战败将暂停）");
        BeginEscortAtIndex(0, "baptism-start");
        TryRebuildEscortTab();
    }

    /// <summary>丢弃某个队员背包中含指定关键字的所有道具。返回丢弃件数。</summary>
    private static int DropItemsByKeyword(string uid, string keyword)
    {
        var dropped = 0;
        try
        {
            var items = FindType("PlayerDataHolder")?.GetMethod(
                "GetItemDatasFromUid", BindingFlags.Public | BindingFlags.Static | BindingFlags.NonPublic)
                ?.Invoke(null, new object[] { uid }) as System.Collections.IList;
            if (items == null)
            {
                return 0;
            }

            var itemMgr = GetManagerInstance("ItemManager");
            if (itemMgr == null)
            {
                return 0;
            }

            // 找 SendBackPackMessage(string, int, int, string)
            var send = FindSendBackPackMessage(itemMgr);
            if (send == null)
            {
                return 0;
            }

            for (var i = 0; i < items.Count; i++)
            {
                var item = items[i];
                if (item == null)
                {
                    continue;
                }

                var useFlag = Convert.ToInt32(GetMember(item, "useFlag") ?? 0);
                if (useFlag != 1)
                {
                    continue;
                }

                var data = GetMember(item, "data");
                var name = Convert.ToString(GetMember(data, "Name") ?? "") ?? "";
                if (name.IndexOf(keyword, StringComparison.Ordinal) < 0)
                {
                    continue;
                }

                send.Invoke(itemMgr, new object[] { "丢弃道具", i, 1, uid });
                dropped++;
                Tip("已丢弃[" + name + "]");
            }
        }
        catch (Exception ex)
        {
            WriteLog("DropItemsByKeyword EX uid=" + uid + " kw=" + keyword + " " + RootMessage(ex));
        }

        return dropped;
    }

    private static MethodInfo FindSendBackPackMessage(object itemMgr)
    {
        if (itemMgr == null)
        {
            return null;
        }

        foreach (var m in itemMgr.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
        {
            if (m.Name != "SendBackPackMessage")
            {
                continue;
            }

            var ps = m.GetParameters();
            if (ps.Length == 4
                && ps[0].ParameterType.FullName == "System.String"
                && ps[1].ParameterType.FullName == "System.Int32"
                && ps[2].ParameterType.FullName == "System.Int32"
                && ps[3].ParameterType.FullName == "System.String")
            {
                return m;
            }
        }

        return null;
    }

    /// <summary>龙1/2 特例：丢弃所有队员背包中的黑之记忆/白之记忆。</summary>
    private static void DropTeamMemoryItems()
    {
        StopTaskNavigation(false);
        var uids = CollectTeamOrMultiUids();
        if (uids.Count == 0)
        {
            var cap = GetCaptainUid();
            if (!string.IsNullOrEmpty(cap))
