        var total = 0;
        foreach (var uid in uids)
        {
            total += DropItemsByKeyword(uid, "黑之记忆");
            total += DropItemsByKeyword(uid, "白之记忆");
        }

        WriteLog("dragon drop memory total=" + total + " uids=" + uids.Count);
        if (total > 0)
        {
            Tip("已丢弃全员黑/白之记忆 " + total + " 件");
        }
