        var now = NowMs();
        if (_wildExDelayUntilMs > 0 && now < _wildExDelayUntilMs)
        {
            return;
        }

        _wildExDelayUntilMs = 0;
        if (IsInBattleNow())
        {
            WildExSayWait("兑换暂停：战斗中", now);
            return;
