    private static bool TryPickWildExNpcOption()
    {
        try
        {
            var npcMgr = GetManagerInstance("NpcManager");
            if (npcMgr == null)
            {
                return false;
            }

            var wmdb = GetMember(npcMgr, "wmdb");
