    {
        _escort119TicketBankPending = false;
        _escortLastDiag = tip;
        WriteLog("119 ticket-bank abort " + reason + " fail=" + _escort119TicketBankFailStreak
                 + " stopLoop=" + stopLoop);
        if (stopLoop)
        {
            _midAutumnLoopActive = false;
            CancelEscort(true, tip);
            return;
        }

        PauseEscortOnConditionFail(reason);
